local config = {
  ui_story_5089_50890100_1_dialog_content = "The weather's really nice today. It feels good to wander around Haojin City alone after such a long time.",
  ui_story_5089_50890100_2_dialog_content = "But I felt watched ever since I got here...",
  ui_story_5089_50890100_3_dialog_content = "I don't sense any malice, but it still sends chills down my spine... Am I too strange from others here?",
  ui_story_5089_50890100_4_dialog_content = "Ahem, pardon me, young one, but are you the envoy from Astra?",
  ui_story_5089_50890100_5_dialog_content = "Um, yes, that's right. Is there something you need?",
  ui_story_5089_50890100_6_dialog_content = "Ah, how wonderful! I'm just a small business owner, running some restaurants and hotels in Ji Kingdom.",
  ui_story_5089_50890100_7_dialog_content = "I was told you are fond of dried tofu, and one of my shops specializes in making it. It isn't much of a gift, but please accept it.",
  ui_story_5089_50890100_8_dialog_content = "If the taste is to your liking, just ask and I'll send you even more!",
  ui_story_5089_50890100_9_dialog_content = "Huh? When did I say that I love dried tofu? Wait, I still don't know who you are—",
  ui_story_5089_50890100_10_dialog_content = "The esteemed envoy has finally arrived! What an honor it is to meet you! Please, have a look at my fine silks!",
  ui_story_5089_50890100_11_dialog_content = "Quick! Fetch our shop's priceless Phoenix Harmony Brocade and present it to our guest!",
  ui_story_5089_50890100_12_dialog_content = "Oh no, I couldn't possibly take that!",
  ui_story_5089_50890100_13_dialog_content = "Pardon me, but my master has prepared a great meal for you. We would be honored to have the envoy from Astra as our guest of honor!",
  ui_story_5089_50890100_14_dialog_content = "Greetings, sir! My master's daughter is hosting a poetry gathering at our home tomorrow, and she wrote this invitation especially for you.",
  ui_story_5089_50890100_15_dialog_content = "Who's that over there? Why are they causing such a ruckus?",
  ui_story_5089_50890100_16_dialog_content = "Sounds like it's the envoy from the western lands!",
  ui_story_5089_50890100_17_dialog_content = "The one who gained the favor of the Dragon Maiden, and helped alleviate the flood in Haojin and defeat an evil dragon. I hear the envoy is even going to marry the crown prince soon!",
  ui_story_5089_50890100_18_dialog_content = "Really? Let's go take a look!",
  ui_story_5089_50890100_19_dialog_content = "Envoy! Over here, envoy...!",
  ui_story_5089_50890100_20_dialog_content = "(Th-This is bad! I gotta get out of here!)",
  ui_story_5089_50890100_21_dialog_content = "Ha... Phew... I finally made it back.",
  ui_story_5089_50890100_22_dialog_content = "I know I gave them a hand before, but everyone's enthusiasm seems a little over the top.",
  ui_story_5089_50890100_23_dialog_content = "Do I have to ask Chen'ni to cover me whenever I go out now?",
  ui_story_5089_50890100_24_dialog_content = "Also, I'm pretty sure I heard one of them say something totally ridiculous just now.",
  ui_story_5089_50890100_25_dialog_content = "<color=#e8d9bb>Chirp-chirp!</color>",
  ui_story_5089_50890100_26_dialog_content = "Hey, it's the clockwork bird I sent to deliver a message to Xuan Ji! Let's see...",
  ui_story_5089_50890100_27_dialog_content = "Huh?",
  ui_story_5089_50890100_28_dialog_content = "This is the letter I sent, but it hasn't even been opened. Was it unable to find her?",
  ui_story_5089_50890100_29_dialog_content = "Chirp.",
  ui_story_5089_50890100_30_dialog_content = "That's odd. During the Spring Festival, she said she was going back to Ye Kingdom to handle some unfinished business.",
  ui_story_5089_50890100_31_dialog_content = "So, how did I end up in some ancient mountain forest?",
  ui_story_5089_50890100_32_dialog_content = "Now that I think of it, ever since I arrived in Longzhou, she's been keeping her distance while investigating something. Could it be...?",
  ui_story_5089_50890100_33_dialog_content = "Sir, a guest is here to see you.",
  ui_story_5089_50890100_34_dialog_content = "... D-Did those people follow me all the way to the Royal Guesthouse?!",
  ui_story_5089_50890100_35_dialog_content = "Sorry, but I don't want to see them now. Just say that Caelestites have to hibernate for the winter or something.",
  ui_story_5089_50890100_36_dialog_content = "But... Didn't winter just pass?",
  ui_story_5089_50890100_37_dialog_content = "Th-Then just tell them I'm still adjusting to the spring and that I have to get ready for next year's hibernation! It doesn't matter. Just come up with an excuse!",
  ui_story_5089_50890100_38_dialog_content = "I never thought it would be so difficult to gain an audience with you, PlayerName.",
  ui_story_5089_50890100_39_dialog_content = "D-Dantang?! No, those excuses weren't meant for you—",
  ui_story_5089_50890100_40_dialog_content = "I know.",
  ui_story_5089_50890100_41_dialog_content = "You are no longer just an envoy from Astra, but also an accomplished hero to Ji Kingdom.",
  ui_story_5089_50890100_42_dialog_content = "The streets of Haojin are abuzz with rumors of your upcoming betrothal to the crown prince as well.",
  ui_story_5089_50890100_43_dialog_content = "It's very little wonder that Ji Kingdom's merchants are competing to establish rapport with you.",
  ui_story_5089_50890100_44_dialog_content = "Why does all of Haojin know about this?! And nobody has any questions about it?",
  ui_story_5089_50890100_45_dialog_content = "Even the most ludicrous of rumors hold a kernel of truth, no?",
  ui_story_5089_50890100_46_dialog_content = "G-Give me a break...",
  ui_story_5089_50890100_47_dialog_content = "There are merits to accepting the crown prince's proposal, you know?",
  ui_story_5089_50890100_48_dialog_content = "He may be a bit mischievous, but his heart is pure and full of admiration for your heroics during the spring equinox.",
  ui_story_5089_50890100_49_dialog_content = "After becoming the crown prince's consort and moving into the royal palace, no one will ever dare to spread rumors about you again.",
  ui_story_5089_50890100_50_dialog_content = "Do you actually need something, Dantang? Or did you seriously come here just to mess with me?",
  ui_story_5089_50890100_51_dialog_content = "\"Mess with you\"? Is that truly how you see me, PlayerName?",
  ui_story_5089_50890100_52_dialog_content = "No! That's not what I meant...",
  ui_story_5089_50890100_53_dialog_content = "Heheh, got you. There's no need to be so nervous.",
  ui_story_5089_50890100_54_dialog_content = "There is, however, a reason for my coming here today... Jiu.",
  ui_story_5089_50890100_55_dialog_content = "Yes, Your Highness.",
  ui_story_5089_50890100_56_dialog_content = "Whoa! You're here too, Jiu? I totally didn't see you there!",
  ui_story_5089_50890100_57_dialog_content = "Her Highness has important matters to discuss with the envoy. I will remain at her side; the rest of you are dismissed.",
  ui_story_5089_50890100_58_dialog_content = "Yes, Your Highness.",
  ui_story_5089_50890100_59_dialog_content = "I'll make some tea.",
  ui_story_5089_50890100_60_dialog_content = "Th-That's okay, I can—",
  ui_story_5089_50890100_61_dialog_content = "I've also brought some light fare from the palace for your enjoyment, so please help yourselves. If I am no longer needed, then I'll take my leave now.",
  ui_story_5089_50890100_62_dialog_content = "Huh? You mean you're not gonna eat with us, Jiu?",
  ui_story_5089_50890100_63_dialog_content = "See, Jiu? PlayerName wishes for your company, now please sit.",
  ui_story_5089_50890100_64_dialog_content = "... That would be a breach of etiquette, Your Highness. If you need me, I'll be at the door.",
  ui_story_5089_50890100_65_dialog_content = "...",
  ui_story_5089_50890100_66_dialog_content = "... What was that about?",
  ui_story_5089_50890100_67_dialog_content = "Jiu isn't much for conversation to begin with, but the distance between us feels even stronger than usual today.",
  ui_story_5089_50890100_68_dialog_content = "If anything, I'd prefer that she argue with me.",
  ui_story_5089_50890100_69_dialog_content = "?",
  ui_story_5089_50890100_70_dialog_content = "But let's not talk about that for now. The reason I came here today was to bid farewell to you.",
  ui_story_5089_50890100_71_dialog_content = "Farewell...? Are you going somewhere?",
  ui_story_5089_50890100_72_dialog_content = "My uncle, or rather the current king of Ye Kingdom, has summoned me back to the kingdom.",
  ui_story_5089_50890100_73_dialog_content = "That's great! Dantang, you can finally go home now!",
  ui_story_5089_50890100_74_dialog_content = "But is it really that simple? After all, you came to Ji Kingdom as... Um, as an exchange student.",
  ui_story_5089_50890100_75_dialog_content = "There's nothing to hide. Is it really so difficult to say the word \"hostage\"?",
  ui_story_5089_50890100_76_dialog_content = "Your concerns, however, are perfectly valid. As a political hostage, returning to home from which I was exiled will never be a simple matter.",
  ui_story_5089_50890100_77_dialog_content = "On the surface, it appears that the kingdoms of Ji and Ye are negotiating new terms.",
  ui_story_5089_50890100_78_dialog_content = "But beneath the surface?",
  ui_story_5089_50890100_79_dialog_content = "My master has already assured me that Ji Kingdom will not obstruct my journey home.",
  ui_story_5089_50890100_80_dialog_content = "\"The merchants, though profit-driven, are by no means ungrateful.\" Those were more or less the words of the king.",
  ui_story_5089_50890100_81_dialog_content = "What does that even mean...?",
  ui_story_5089_50890100_82_dialog_content = "After the turmoil of the Spring Festival, a temple dedicated to the Dragon Maiden was built within the palace, and a golden statue was sculpted in her honor.",
  ui_story_5089_50890100_83_dialog_content = "The Lin family is regrouping and growing stronger by the day, and you become a beloved and honored citizen of Ji Kingdom.",
  ui_story_5089_50890100_84_dialog_content = "I myself was not exempt from receiving the kingdom's generous rewards.",
  ui_story_5089_50890100_85_dialog_content = "But there's one person who, despite her efforts, has yet to receive recompense of any kind.",
  ui_story_5089_50890100_86_dialog_content = "You mean Xuan Ji, right? I haven't been able to reach her at all lately... Do you know what's going on with her?",
  ui_story_5089_50890100_87_dialog_content = "This is the second matter I wanted to discuss with you.",
  ui_story_5089_50890100_88_dialog_content = "We received a royal decree from Ye Kingdom. By order of the king, Ministress Armilla is to be arrested and imprisoned following the conclusion of the Spring Festival.",
  ui_story_5089_50890100_89_dialog_content = "She is accused of betraying the kingdom through her use of critical machinery.",
  ui_story_5089_50890100_90_dialog_content = "What?!",
  ui_story_5089_50890100_91_dialog_content = "And for this reason, I've decided to take immediate action and return to Ye Kingdom tomorrow.",
  ui_story_5089_50890100_92_dialog_content = "I only wish I could make the journey even sooner. For Ministress Armilla's sake, I must investigate these accusations and uncover the truth.",
  ui_story_5089_50890100_93_dialog_content = "PlayerName—",
  ui_story_5089_50890100_94_dialog_content = "I'll go too!",
  ui_story_5089_50890100_95_dialog_content = "Very well.",
  ui_story_5089_50890100_96_dialog_content = "When you said you were leaving, I already wanted to ask you to take me with you.",
  ui_story_5089_50890100_97_dialog_content = "I'm no deity, and I didn't come to Longzhou just to sit here and accept offerings—even the real deity didn't do so.",
  ui_story_5089_50890100_98_dialog_content = "There's nothing for me to do here in Haojin, so now is a good time to leave.",
  ui_story_5089_50890100_99_dialog_content = "And besides, Xuan Ji is also my friend. No matter what you say, I'll find a way to come along. Wait, what did you just say?",
  ui_story_5089_50890100_100_dialog_content = "Very well.",
  ui_story_5089_50890100_101_dialog_content = "... I thought you would say that this has nothing to do with me, and tell me to stay here.",
  ui_story_5089_50890100_102_dialog_content = "No one can survive in isolation. Those with many allies thrive, while those with few perish.",
  ui_story_5089_50890100_103_dialog_content = "Your teachings still echo in my ears. I dare not forget them.",
  ui_story_5089_50890100_104_dialog_content = "D-Did I really say something that cool to you?",
  ui_story_5089_50890100_105_dialog_content = "Heheh. If you'll excuse me, I must return to the palace to make our final preparations. Until tomorrow, PlayerName.",
  ui_story_5089_50890100_106_dialog_content = "I should also pack my things...",
  ui_story_5089_50890100_107_dialog_content = "Leaving so soon?",
  ui_story_5089_50890100_108_dialog_content = "Wow! Chen'ni? What are you doing here again?!",
  ui_story_5089_50890100_109_dialog_content = "Oh, around when you wished I could use my power to keep you hidden.",
  ui_story_5089_50890100_110_dialog_content = "Th-Then you've been here this whole time!",
  ui_story_5089_50890100_111_dialog_content = "... Which means you heard all of that too, right? I'm heading to Ye Kingdom tomorrow, so I won't be able to play with you for a while.",
  ui_story_5089_50890100_112_dialog_content = "That's okay! I'll just come along too; if anyone gets in our way, I'll do what I do best!",
  ui_story_5089_50890100_113_dialog_content = "\"Punch the demons and send them flying in every direction!\"",
  ui_story_5089_50890100_114_dialog_content = "No, no, no. That's not in the Dragon's Dance, why do you insist on remembering that?!",
  ui_story_5089_50890100_115_dialog_content = "Does it really matter? After all, the legends about deities and heroes have always changed over the years.",
  ui_story_5089_50890100_116_dialog_content = "And thanks to you, I've decided to take martial arts lessons and live up to my newest legend!",
  ui_story_5089_50890100_117_dialog_content = "Fine, but just remember to pull your punches. I won't be there to keep you in check, so you'll have to do it yourself.",
  ui_story_5089_50890100_118_dialog_content = "So you really don't want me to come with you to Ye Kingdom? Because if you just make a wish...",
  ui_story_5089_50890100_119_dialog_content = "If I did, would you still be my friend?",
  ui_story_5089_50890100_120_dialog_content = "...",
  ui_story_5089_50890100_121_dialog_content = "I want to stay friends with you for as long as I'm around, Chen'ni.",
  ui_story_5089_50890100_122_dialog_content = "This means I'll never treat the Almighty Benevolent Dragon Divinity as a resource to be exploited.",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>Suddenly, Chen'ni reaches out and pulls a leaf from a tree outside the window, then hands it over.</color>",
  ui_story_5089_50890100_124_dialog_content = "What's this?",
  ui_story_5089_50890100_125_dialog_content = "A farewell gift.",
  ui_story_5089_50890100_126_dialog_content = "It's an Aurorian tradition, right?",
  ui_story_5089_50890100_127_dialog_content = "I'll be here waiting when you come back, PlayerName. We'll have lots of fun when you do!",
  ui_story_5089_50890100_128_dialog_content = "I'm pretty sure Aurorians use a willow branch for—Uh, Chen'ni?",
  ui_story_5089_50890100_129_dialog_content = "She left without another word... Guess I'll just put these away for now and dry them out later.",
  ui_story_5089_50890100_130_dialog_content = "This is also a good time to say goodbye to the others.",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>The next day</color>",
  ui_story_5089_50890100_132_dialog_content = "This is where I'm supposed to meet Dantang, right?",
  ui_story_5089_50890100_133_dialog_content = "PlayerName! PlayerName! You're finally here! I've been waiting for a long time now, you know!",
  ui_story_5089_50890100_134_dialog_content = "Crown Prince... What are you doing here? And what's that big box over there?",
  ui_story_5089_50890100_135_dialog_content = "I'm here to send you off, of course. I even prepared a few farewell gifts.",
  ui_story_5089_50890100_136_dialog_content = "I carefully hand-picked each of these priceless treasures just for you!",
  ui_story_5089_50890100_137_dialog_content = "See? This is the doll I used to carry everywhere as a child. And here is the lantern I made myself during the festival.",
  ui_story_5089_50890100_138_dialog_content = "Oh, and my favorite storybook! Master wouldn't let me read it, so I had to ask many people to help me buy it!",
  ui_story_5089_50890100_139_dialog_content = "Which reminds me... Dantang and the Chief Advisor told me everything.",
  ui_story_5089_50890100_140_dialog_content = "I never asked for your opinion before deciding that you would become my consort. It was wrong of me, and I'm sorry for putting you in such a difficult position.",
  ui_story_5089_50890100_141_dialog_content = "Your Highness...",
  ui_story_5089_50890100_142_dialog_content = "The ship is about to set sail, PlayerName.",
  ui_story_5089_50890100_143_dialog_content = "Ah, okay. Anyway, since these are all tokens of your sincerity, I'll be happy to accept them.",
  ui_story_5089_50890100_144_dialog_content = "Splendid!",
  ui_story_5089_50890100_145_dialog_content = "Guards, go bring up the rest of it!",
  ui_story_5089_50890100_146_dialog_content = "H-Hang on... What's with those of crates?!",
  ui_story_5089_50890100_147_dialog_content = "Oh, just a few minor stuff for your journey. I only had time to prepare this box, so I left the rest with my men.",
  ui_story_5089_50890100_148_dialog_content = "But my sincerity is totally real! Please believe me!",
  ui_story_5089_50890100_149_dialog_content = "Now that I've grown to understand the ways of the world, I realize how reckless I was before.",
  ui_story_5089_50890100_150_dialog_content = "I see now that courtship must always take place before marriage!",
  ui_story_5089_50890100_151_dialog_content = "... I'm sorry?",
  ui_story_5089_50890100_152_dialog_content = "Raise anchor—",
  ui_story_5089_50890100_153_dialog_content = "Set sail—",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>As the ship slowly departs, the prince waves and shouts from the shore.</color>",
  ui_story_5089_50890100_155_dialog_content = "Safe travels! And rest assured, I will continue to court you with gifts until you agree to be my consort—",
  ui_story_5089_50890100_156_dialog_content = "...",
  ui_story_5089_50890100_157_dialog_content = "I knew getting out of Haojin was the right move!",
  ui_story_5089_50890100_158_dialog_content = "Even I am surprised by the prince's affection towards you, PlayerName. I've never seen him pursue anything with such single-minded intent.",
  ui_story_5089_50890100_159_dialog_content = "But I can't accept all of these gifts, even if they're just a bunch of toys...",
  ui_story_5089_50890100_160_dialog_content = "If you truly can't accept them, I can always arrange for them to be sent back once we reach Ye Kingdom.",
  ui_story_5089_50890100_161_dialog_content = "That'll have to be the plan. Saving Xuan Ji takes precedence over everything else.",
  ui_story_5089_50890100_162_dialog_content = "Right. It's finally time to go... No, wait.",
  ui_story_5089_50890100_163_dialog_content = "It's finally time to return to Ye Kingdom.",
  ui_story_5089_50890201_1_dialog_content = "Your Highness, PlayerName, please prepare to disembark.",
  ui_story_5089_50890201_2_dialog_content = "But we just passed the border between the two kingdoms, didn't we? Are we really there?",
  ui_story_5089_50890201_3_dialog_content = "Not yet, no. Unlike Ji Kingdom and its many waterways, Ye Kingdom is situated in a vast, central plain. Ships can only take us this far.",
  ui_story_5089_50890201_4_dialog_content = "Hey, I remember this harbor... This is Tongli Town, isn't it?",
  ui_story_5089_50890201_5_dialog_content = "Yes, Your Highness. I've already booked the inn for the night. We'll rest there and continue our journey tomorrow.",
  ui_story_5089_50890201_6_dialog_content = "Once the carriages have been secured, we will travel directly to the capital by land.",
  ui_story_5089_50890201_7_dialog_content = "That's impressive, Jiu! How were you able to do all of that while we're still on the water?",
  ui_story_5089_50890201_8_dialog_content = "The ship comes equipped with a small rowboat. I used it to get to the shore and arrange for everything in advance.",
  ui_story_5089_50890201_9_dialog_content = "Given the sudden and unexpected nature of our voyage, no one has been notified to receive us at this point.",
  ui_story_5089_50890201_10_dialog_content = "It's already crime enough that Her Highness must take up lodging in such a humble little inn, so we must at least ensure the safety of the surroundings.",
  ui_story_5089_50890201_11_dialog_content = "You said we're getting close, but I don't see any signs of land...",
  ui_story_5089_50890201_12_dialog_content = "You rowed all that way by yourself... No wonder you're completely soaked.",
  ui_story_5089_50890201_13_dialog_content = "You should change into something dry before you catch a cold.",
  ui_story_5089_50890201_14_dialog_content = "Your concern is appreciated, but I'm not so frail. A lifetime of martial arts training keeps me in relatively good health.",
  ui_story_5089_50890201_15_dialog_content = "I went ashore to scout the area and ensure its safety, but leaving Her Highness for my own affair would be a dereliction of duty.",
  ui_story_5089_50890201_16_dialog_content = "Then again, it is unbecoming of me to present such a sight around Her Highness. Pardon me, I will stay out of sight.",
  ui_story_5089_50890201_17_dialog_content = "Wait, that's not what I meant—",
  ui_story_5089_50890201_18_dialog_content = "It's fine, PlayerName. Just let her go.",
  ui_story_5089_50890201_19_dialog_content = "This is the longest I've seen her show herself in quite some time.",
  ui_story_5089_50890201_20_dialog_content = "Even in the palace, when I'm busy sorting through letters and paperwork, she often refills my tea and refreshments without me noticing.",
  ui_story_5089_50890201_21_dialog_content = "Or when I come back from meetings with other people, I always find my room perfectly neat and tidy.",
  ui_story_5089_50890201_22_dialog_content = "She has been doing even more than usual without anyone noticing her at all.",
  ui_story_5089_50890201_23_dialog_content = "(T-The shoemaking evles?)",
  ui_story_5089_50890201_24_dialog_content = "So what exactly happened between you two?",
  ui_story_5089_50890201_25_dialog_content = "PlayerName, do you still remember the group of people responsible for the chaos in Haojin some time ago?",
  ui_story_5089_50890201_26_dialog_content = "You mean the guys who called themselves the Fate Riders?",
  ui_story_5089_50890201_27_dialog_content = "Yes. With the aid of the Almighty Benevolent Dragon Divinity, the Inspection Office was able to apprehend a large number of the Fate Riders hiding within Ji Kingdom.",
  ui_story_5089_50890201_28_dialog_content = "Among them were dozens of people who held official positions within the kingdom's court.",
  ui_story_5089_50890201_29_dialog_content = "Though they were mostly lower-level officials, in time, they were able to establish a powerful network amongst themselves...",
  ui_story_5089_50890201_30_dialog_content = "Powerful enough to greatly influence the court, and even the king himself. In fact, one could say that these people had gained the power to shake an entire kingdom to its core.",
  ui_story_5089_50890201_31_dialog_content = "Thankfully, we managed to capture every last of them, and now the king and his advisors are more vigilant than ever. These traitors will not be able to act with impunity ever again.",
  ui_story_5089_50890201_32_dialog_content = "But even so, PlayerName... Do you truly believe that their network was only restricted to Ji Kingdom?",
  ui_story_5089_50890201_33_dialog_content = "You mean...",
  ui_story_5089_50890201_34_dialog_content = "On the night of the turmoil in Haojin, I was trying to look for you, but I was intercepted as soon as I left the palace gates.",
  ui_story_5089_50890201_35_dialog_content = "This is the first I've heard of it! They didn't hurt you, did they? Why didn't you tell anyone?!",
  ui_story_5089_50890201_36_dialog_content = "Because the ones who intercepted me were spies from Ye Kingdom.",
  ui_story_5089_50890201_37_dialog_content = "What?!",
  ui_story_5089_50890201_38_dialog_content = "The current emperor of the Zhao Empire is young, and the eight kings each have their own intentions.",
  ui_story_5089_50890201_39_dialog_content = "While espionage between them is common enough, it isn't something that can be discussed openly.",
  ui_story_5089_50890201_40_dialog_content = "And although Ye Kingdom's spies respected me as their princess, they still only answer to one man: my uncle.",
  ui_story_5089_50890201_41_dialog_content = "So they blocked me, and thus aided the Fate Riders in their schemes...",
  ui_story_5089_50890201_42_dialog_content = "Is the King of Ye really the only one who can control them?",
  ui_story_5089_50890201_43_dialog_content = "My uncle was not well-known before taking the throne and has been an exemplary ruler. He appoints people based on their talents, cares deeply for his subjects, and carries himself with the demeanor of a true king.",
  ui_story_5089_50890201_44_dialog_content = "Which leads me to assume that this is the work of the Fate Riders!",
  ui_story_5089_50890201_45_dialog_content = "I see. No wonder you're in such a hurry to go back.",
  ui_story_5089_50890201_46_dialog_content = "By avoiding Ye Kingdom's Fate Riders as much as possible, you're free to move around and investigate matters, which you can later report to the king.",
  ui_story_5089_50890201_47_dialog_content = "And then, logically, we'd be able to rescue Xuan Ji, who was imprisoned for helping us!",
  ui_story_5089_50890201_48_dialog_content = "You know me all too well, PlayerName.",
  ui_story_5089_50890201_49_dialog_content = "But what does any of this have to do with Jiu?",
  ui_story_5089_50890201_50_dialog_content = "I thought you knew.",
  ui_story_5089_50890201_51_dialog_content = "Jiu is none other than the leader of Ye Kingdom's spies.",
  ui_story_5089_50890201_52_dialog_content = "What?! Isn't she your personal guard?",
  ui_story_5089_50890201_53_dialog_content = "Jiu was originally a trusted servant under my uncle's direct command. She was assigned to me as a guard just before I was sent to Ji Kingdom as a hostage.",
  ui_story_5089_50890201_54_dialog_content = "My uncle has shown her a great deal of favor. She would never defy any order that came from him.",
  ui_story_5089_50890201_55_dialog_content = "And because my uncle ordered her to protect me, she's willing to risk her life to do so.",
  ui_story_5089_50890201_56_dialog_content = "Out of concern for my safety, he has asked her to write to him every month with updates. Regardless of season or circumstance, she has never missed a deadline.",
  ui_story_5089_50890201_57_dialog_content = "That's...",
  ui_story_5089_50890201_58_dialog_content = "I understand my uncle's concern, but from another perspective, it could also be considered surveillance.",
  ui_story_5089_50890201_59_dialog_content = "Wait, does that mean the Fate Riders are still tracking our actions?! Is Jiu...",
  ui_story_5089_50890201_60_dialog_content = "You can set your doubts aside.",
  ui_story_5089_50890201_61_dialog_content = "After all, you've seen it for yourself, haven't you? Jiu refuses to lie about anything to me or my uncle.",
  ui_story_5089_50890201_62_dialog_content = "She would never defy his orders, but she fully understands the significance of our journey. For that reason, she can only look the other way, remain silent, and ask no questions.",
  ui_story_5089_50890201_63_dialog_content = "So long as she fulfills her duties as a guard and keeps her distance from me, she won't have to report anything she doesn't know.",
  ui_story_5089_50890201_64_dialog_content = "She is already doing everything she can for us.",
  ui_story_5089_50890201_65_dialog_content = "However, I can't deny my joy after seeing my stubborn guard waver slightly.",
  ui_story_5089_50890201_66_dialog_content = "At the very least, the five years we spent together in Ji Kingdom weren't entirely wasted.",
  ui_story_5089_50890201_67_dialog_content = "Dantang.",
  ui_story_5089_50890201_68_dialog_content = "Yes? Let me guess: you don't think I should take any pleasure in seeing her struggle, do you?",
  ui_story_5089_50890201_69_dialog_content = "You've had it really hard in Ji Kingdom all these years, haven't you?",
  ui_story_5089_50890201_70_dialog_content = "Huh...?",
  ui_story_5089_50890201_71_dialog_content = "Er, well... I mean...",
  ui_story_5089_50890201_72_dialog_content = "I know that the King of Ji, the Crown Prince, and the Chief Advisor are all good people, but they're not your family.",
  ui_story_5089_50890201_73_dialog_content = "Sigh...",
  ui_story_5089_50890201_74_dialog_content = "Wh-What is it? Did I say something wrong?",
  ui_story_5089_50890201_75_dialog_content = "Not at all. In fact, if you were an army commander, something tells me you would excel at surprise attacks.",
  ui_story_5089_50890201_76_dialog_content = "Huh? Why are we suddenly talking about that?",
  ui_story_5089_50890201_77_dialog_content = "If you'll excuse me, I need to touch up my makeup before we disembark.",
  ui_story_5089_50890201_78_dialog_content = "Uh, alright...",
  ui_story_5089_50890201_79_dialog_content = "Caw...",
  ui_story_5089_50890201_80_dialog_content = "Caw...",
  ui_story_5089_50890201_81_dialog_content = "Rotten wood can never be carved!",
  ui_story_5089_50890201_82_dialog_content = "And an iron tree will never bloom!",
  ui_story_5089_50890201_83_dialog_content = "Hey, who are you calling \"rotten wood\"?! Wait... Squawk? Jabber? What are you two doing here?",
  ui_story_5089_50890201_84_dialog_content = "Hand over some gold melons and I'll guide your path!",
  ui_story_5089_50890201_85_dialog_content = "Offer some silver dates, and I'll dispel all of your doubts!",
  ui_story_5089_50890201_86_dialog_content = "Sorry to disappoint, but I don't have either of those things.",
  ui_story_5089_50890201_87_dialog_content = "If you're hungry, just ask your master for food. He should be around here too, right? I'm well aware of his tendency to show up out of nowhere.",
  ui_story_5089_50890201_88_dialog_content = "Tianxian! You're here too, right?",
  ui_story_5089_50890201_89_dialog_content = "We no longer have a master!",
  ui_story_5089_50890201_90_dialog_content = "The waters have claimed him!",
  ui_story_5089_50890201_91_dialog_content = "Over there!",
  ui_story_5089_50890201_92_dialog_content = "What...?!",
  ui_story_5089_50890201_93_dialog_content = "Glub, glub... Help... I... Can't swim... Glub, glub, glub...",
  ui_story_5089_50890201_94_dialog_content = "What's he doing in the water?! Ah, this isn't good...",
  ui_story_5089_50890201_95_dialog_content = "I have to save him!",
  ui_story_5089_50890202_1_dialog_content = "Achoo!",
  ui_story_5089_50890202_2_dialog_content = "Thank goodness, I live to see another day.",
  ui_story_5089_50890202_3_dialog_content = "What the heck were you doing, drowning in a place like this? Don't tell me you got another invitation to the Dragon Palace?!",
  ui_story_5089_50890202_4_dialog_content = "No... It's actually much less complicated than that.",
  ui_story_5089_50890202_5_dialog_content = "I had grown tired of wandering Ji Kingdom, so I thought of visiting new lands. But as you know, I'm often short on funds.",
  ui_story_5089_50890202_6_dialog_content = "Unable to afford passage on a larger ship, I had no choice but to travel with a smaller caravan of merchants. After countless stops along the way, we finally arrived at Ye Kingdom.",
  ui_story_5089_50890202_7_dialog_content = "But wouldn't you know it? As we were traveling through the wilderness, we encountered a pack of bloodthirsty Eclipsites!",
  ui_story_5089_50890202_8_dialog_content = "What a rare sight, given that the court hosts an annual ceremony to vanquish these monsters from their lands. The borderlands between the Ji and Ye Kingdoms aren't even close to the ocean.",
  ui_story_5089_50890202_9_dialog_content = "I fear those starved Eclipsites had been hiding in the mountains somewhere, and I just so happened to run into them while they were foraging for food.",
  ui_story_5089_50890202_10_dialog_content = "And so they gave chase without a second thought. As I ran for my life, I lost sight of my surroundings and ultimately plunged into the sea.",
  ui_story_5089_50890202_11_dialog_content = "But thanks to all of you, my life is spared once again. If only I had something of value to offer as a token of my gratitude...",
  ui_story_5089_50890202_12_dialog_content = "It seems I have no choice but to repay you with my body!",
  ui_story_5089_50890202_13_dialog_content = "N-No need for that!",
  ui_story_5089_50890202_14_dialog_content = "Don't you have anything better to do right now?!",
  ui_story_5089_50890202_15_dialog_content = "Tell me, do you still remember my name?",
  ui_story_5089_50890202_16_dialog_content = "Uh, yeah? It's Tianxian, isn't it?",
  ui_story_5089_50890202_17_dialog_content = "Correct! And if you were to break it down to its most literal interpretation, it means \"the world's greatest idler\"!",
  ui_story_5089_50890202_18_dialog_content = "So please, don't be so quick to turn me away. Before I set off, I divined my own fortune. Though it foretold great misfortune on my journey, it also hinted at the arrival of a kind and wealthy benefactor.",
  ui_story_5089_50890202_19_dialog_content = "As for who that might be... Come, hold out your hands for me.",
  ui_story_5089_50890202_20_dialog_content = "Like this?",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>Clatter!</color>",
  ui_story_5089_50890202_22_dialog_content = "Uh... Why did you dump all of your divination sticks into my hands?",
  ui_story_5089_50890202_23_dialog_content = "Oh dear, the Yin Dragon and Yin Rat hexagrams. This does not bode well for us.",
  ui_story_5089_50890202_24_dialog_content = "The rising dragon and leaping rat are normally auspicious signs, but xact opposite in this case. in this case Together, they signify that a terrible threat lies hidden before us, and that villains are plotting something nefarious as we speak. In short, we are facing an imminent disaster.",
  ui_story_5089_50890202_25_dialog_content = "Under normal circumstances, I would be running for my life right now. However, I couldn't leave my saviors alone to face this disaster.",
  ui_story_5089_50890202_26_dialog_content = "Ah, well, it can't be helped. Allow me to join you on your travels so that we may face this terrible threat together.",
  ui_story_5089_50890202_27_dialog_content = "I'm always suspicious of anything you say, but this entire situation seems especially fishy.",
  ui_story_5089_50890202_28_dialog_content = "How so? You were the one who rescued me from a water grave, weren't you?",
  ui_story_5089_50890202_29_dialog_content = "Yes, but your fortune said a \"wealthy benefactor\" would rescue you.",
  ui_story_5089_50890202_30_dialog_content = "Not to brag or anything, but I've never been rich a day in my life!",
  ui_story_5089_50890202_31_dialog_content = "Hmm, how strange. My divinations indicated that you would be wealthy enough to rival an entire nation by now.",
  ui_story_5089_50890202_32_dialog_content = "Yeah, maybe in my dreams...",
  ui_story_5089_50890202_33_dialog_content = "The ship has now docked, PlayerName. A boatman will be along shortly to carry your belongings, so feel free to disembark at any time.",
  ui_story_5089_50890202_34_dialog_content = "A boatman? That won't do at all! As part of repaying my life's debt to you, allow me to carry this box—",
  ui_story_5089_50890202_35_dialog_content = "Urgh! Why is it so heavy...?!",
  ui_story_5089_50890202_36_dialog_content = "<color=#e8d9bb>Slam!</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>The box falls with a resounding thud, knocking its lid off. To everyone's surprise, the box is filled to the brim with dazzling, golden treasures.</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName, it's time to disembark—",
  ui_story_5089_50890202_39_dialog_content = "...",
  ui_story_5089_50890202_40_dialog_content = "...",
  ui_story_5089_50890202_41_dialog_content = "...",
  ui_story_5089_50890202_42_dialog_content = "N-None of it is damaged, I hope? Oh dear, oh heavens above... I'd never be able to replace any of this if I broke it!",
  ui_story_5089_50890202_43_dialog_content = "Uh, guys? I'm pretty sure there's something wrong with my eyes.",
  ui_story_5089_50890202_44_dialog_content = "The box that the prince gave me... Why does it look like it's full of gold? Hahaha...",
  ui_story_5089_50890202_45_dialog_content = "... Jiu.",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>Jiu suddenly appears at Dantang's call. Without another word, she inspects every single crate given to them by the crown prince.</color>",
  ui_story_5089_50890202_47_dialog_content = "My inspection is complete, Lady Dantang. Apart from two boxes full of toys and a few cases of jade and precious stones, everything else is gold.",
  ui_story_5089_50890301_1_dialog_content = "We've been walking for ages... How are we still not there yet? Is the inn really that far from the dock...?",
  ui_story_5089_50890301_2_dialog_content = "Aren't you the one who insisted on taking back roads out of fear of getting robbed? You have no one to blame but yourself for inviting the god of wealth into your home, my friend.",
  ui_story_5089_50890301_3_dialog_content = "Don't get the wrong idea! I'm only terrified of getting robbed because I have an obligation to return all this stuff! Anyone else would react the same way!",
  ui_story_5089_50890301_4_dialog_content = "The prince even said these boxes were just \"minor stuff\" for our trip...",
  ui_story_5089_50890301_5_dialog_content = "For the crown prince of Ji Kingdom, gold and silver are but trivial objects.",
  ui_story_5089_50890301_6_dialog_content = "But for anyone else... You could easily buy an entire city in Ye Kingdom with this much gold, PlayerName.",
  ui_story_5089_50890301_7_dialog_content = "But there's no need to worry. With Jiu at our side, no ordinary bandit could ever hope to approach us.",
  ui_story_5089_50890301_8_dialog_content = "We're almost to the inn. It's just at the end of this street.",
  ui_story_5089_50890301_9_dialog_content = "Finally, some much-needed rest. This part of the trip has been so nerve-wracking... Huh? Is something wrong, Dantang?",
  ui_story_5089_50890301_10_dialog_content = "No, it's just that... I recall passing through here on my way to Ji Kingdom years ago.",
  ui_story_5089_50890301_11_dialog_content = "Tongli Town... A seaside settlement bordering one of Ye Kingdom's largest grain-producing regions. It may not compare to a major city, but it was certainly bustling at the time.",
  ui_story_5089_50890301_12_dialog_content = "Yet somehow, it feels much more desolate this time.",
  ui_story_5089_50890301_13_dialog_content = "Then it seems you haven't been here for many years, young lady.",
  ui_story_5089_50890301_14_dialog_content = "Please enlighten me, kind sir.",
  ui_story_5089_50890301_15_dialog_content = "Enlighten you, eh? What can I teach you that everyone doesn't already know?",
  ui_story_5089_50890301_16_dialog_content = "In the last few years, the city has built many large workshops, offering generous monthly wages and attracting all the young people to work in them.",
  ui_story_5089_50890301_17_dialog_content = "If I wasn't so old and decrepit, I would love to work in a place where I'm not at the mercy of the elements.",
  ui_story_5089_50890301_18_dialog_content = "I see. May I ask how much this rice costs, kind sir?",
  ui_story_5089_50890301_19_dialog_content = "You're looking to buy some? I should warn you, the price of grains has been rising for the past two months, and it's a bit higher today. For this much rice—",
  ui_story_5089_50890301_20_dialog_content = "... I see. Thank you.",
  ui_story_5089_50890301_21_dialog_content = "Is there something wrong with that bag of rice?",
  ui_story_5089_50890301_22_dialog_content = "When we were back in Haojin, I asked about the price of rice, and it seemed to match the price here. That shouldn't be a problem, right?",
  ui_story_5089_50890301_23_dialog_content = "The cost of rice in a small town like this is shockingly similar to that of Haojin, one of the wealthiest cities of the Zhao Empire.",
  ui_story_5089_50890301_24_dialog_content = "To say it isn't a problem couldn't be further from the truth. But how could this be...?",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5089_50890301_26_dialog_content = "Oh, sorry about that! I didn't mean to bump into you... Huh? What's that in your arms...?",
  ui_story_5089_50890301_27_dialog_content = "...!",
  ui_story_5089_50890301_28_dialog_content = "S-Sir! You have to stop that child!",
  ui_story_5089_50890301_29_dialog_content = "He's running away with your luggage!",
  ui_story_5089_50890301_30_dialog_content = "!",
  ui_story_5089_50890301_31_dialog_content = "—!",
  ui_story_5089_50890301_32_dialog_content = "Stop resisting.",
  ui_story_5089_50890301_33_dialog_content = "Hrngh! Let me go! Let me... GO!",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>The little boy ferociously bites down on Jiu's hand, but the latter remains entirely unfazed, her expression stony and unfeeling.</color>",
  ui_story_5089_50890301_35_dialog_content = "Return what you've stolen.",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>With red and puffy eyes, the boy bites down even harder.</color>",
  ui_story_5089_50890301_37_dialog_content = "Jiu!",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>Within that momentary lapse of focus, the boy slips out of Jiu's grasp like a fish.</color>",
  ui_story_5089_50890301_39_dialog_content = "Pffft!",
  ui_story_5089_50890301_40_dialog_content = "Hey, you—",
  ui_story_5089_50890301_41_dialog_content = "Help! Save me! Those people are trying to kidnap me!",
  ui_story_5089_50890301_42_dialog_content = "What? Who's stupid enough to try and kidnap a child in broad daylight?!",
  ui_story_5089_50890301_43_dialog_content = "Those guys over there, the ones wearing those strange clothes! I knew they were trouble as soon as I saw them!",
  ui_story_5089_50890301_44_dialog_content = "Call the town guards! Arrest those criminals!",
  ui_story_5089_50890301_45_dialog_content = "Wh-What's all this now? Please don't be hasty! I assure you that we're all on the same side, so let's just talk things out calmly and rationally!",
  ui_story_5089_50890301_46_dialog_content = "No one's on your side, criminal!",
  ui_story_5089_50890301_47_dialog_content = "Argh, there are too many people here! That kid's getting away!",
  ui_story_5089_50890301_48_dialog_content = "Step away from the princess!",
  ui_story_5089_50890301_49_dialog_content = "It's fine, Jiu. They're just ordinary citizens concerned for their own safety.",
  ui_story_5089_50890301_50_dialog_content = "But what if...",
  ui_story_5089_50890301_51_dialog_content = "You're faster without me, so take PlayerName and go find that child. I'll deal with the rest of the townsfolk.",
  ui_story_5089_50890301_52_dialog_content = "I can't do that, Your Highness. My orders are to protect you.",
  ui_story_5089_50890301_53_dialog_content = "Then consider it an order from me. Now go.",
  ui_story_5089_50890301_54_dialog_content = "... Yes, Your Highness.",
  ui_story_5089_50890301_55_dialog_content = "Please stay close to me, PlayerName.",
  ui_story_5089_50890301_56_dialog_content = "How'd that kid manage to slip away so quickly?",
  ui_story_5089_50890301_57_dialog_content = "Sigh... I had a feeling something like this would happen as soon as I saw that pile of gold.",
  ui_story_5089_50890301_58_dialog_content = "Still, I'm surprised that the person who robbed me was just a child.",
  ui_story_5089_50890301_59_dialog_content = "He was dressed in rags, though. I'm sure he's dealt with his share of hardship too.",
  ui_story_5089_50890301_60_dialog_content = "...",
  ui_story_5089_50890301_61_dialog_content = "You're not going to talk to me unless it's absolutely necessary, are you?",
  ui_story_5089_50890301_62_dialog_content = "...",
  ui_story_5089_50890301_63_dialog_content = "I know I'm just an outsider, and I still have a lot to learn about Longzhou. It'd be arrogant of me to say that I understand your situation.",
  ui_story_5089_50890301_64_dialog_content = "But I've met a lot of different people throughout my travels.",
  ui_story_5089_50890301_65_dialog_content = "Some of them willingly sacrificed everything for their beliefs, and became beacons for the coming dawn.",
  ui_story_5089_50890301_66_dialog_content = "Some people were willing to destroy everything for their dreams, even if it meant falling into the darkest abyss.",
  ui_story_5089_50890301_67_dialog_content = "I have no right to judge their rights or wrongs, and I'm definitely not qualified to define other people's lives in just a few words. I guess that's what I'm trying to say.",
  ui_story_5089_50890301_68_dialog_content = "Is that there's only one way to accomplish nothing, and that's by doing nothing at all.",
  ui_story_5089_50890301_69_dialog_content = "I am a warrior under the King of Ye's command, and a guard entrusted with Princess Dantang's protection.",
  ui_story_5089_50890301_70_dialog_content = "My duty is to obey orders and fulfill my responsibilities without hesitation.",
  ui_story_5089_50890301_71_dialog_content = "There is no need for me to change anything.",
  ui_story_5089_50890301_72_dialog_content = "Then let me ask you something. What would you do if the king and Dantang gave you conflicting orders?",
  ui_story_5089_50890301_73_dialog_content = "Both the king and the princess are benevolent rulers who bear the plight of their subjects in their hearts. They dedicate themselves wholly to the interests of Ye Kingdom.",
  ui_story_5089_50890301_74_dialog_content = "That's not a very convincing answer, you know.",
  ui_story_5089_50890301_75_dialog_content = "I...",
  ui_story_5089_50890301_76_dialog_content = "Still no sign of that kid, huh? Maybe I should try sensing his location.",
  ui_story_5089_50890301_77_dialog_content = "Psychic Scan!",
  ui_story_5089_50890301_78_dialog_content = "There! He's in an alleyway to the south of us—Huh?",
  ui_story_5089_50890301_79_dialog_content = "Pffffft—",
  ui_story_5089_50890301_80_dialog_content = "That kid...",
  ui_story_5089_50890301_81_dialog_content = "(Eh? I think I tripped over something...)",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>Clatter, clatter!</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>A bundle of bamboo poles comes crashing down.</color>",
  ui_story_5089_50890301_84_dialog_content = "A trap?!",
  ui_story_5089_50890301_85_dialog_content = "(I-I gotta get out of the way!)",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>As though in anticipation of the trespasser's next move, the stone bricks just below the trap collapsed into a well-concealed hole.</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>Sploosh!</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>A wooden bucket full of water falls from the sky—</color>",
  ui_story_5089_50890301_89_dialog_content = "Ahhhh!",
  ui_story_5089_50890301_90_dialog_content = "Watch out.",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>Jiu dashes forward like an unseen gust of wind.</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>Nimbly, she strikes the bucket with the tip of her undrawn blade, redirecting it away from its intended target.</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>With a light thud, it lands gracefully at the boy's feet without spilling so much as a single drop of water.</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>At the same time, the cascading bamboo poles hover in the air for a brief moment before splitting into countless pieces and falling harmlessly to the floor..</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>At some point, they had been cleanly cut in half.</color>",
  ui_story_5089_50890301_96_dialog_content = "Th-That... was incredible.",
  ui_story_5089_50890301_97_dialog_content = "How did she...",
  ui_story_5089_50890301_98_dialog_content = "Return what you've stolen. I won't say it again.",
  ui_story_5089_50890301_99_dialog_content = "... I don't know what you're talking about!!",
  ui_story_5089_50890301_100_dialog_content = "Stop—",
  ui_story_5089_50890301_101_dialog_content = "Wait, Jiu.",
  ui_story_5089_50890301_102_dialog_content = "He went through a lot of trouble to set up these traps, and he even stayed here when he didn't have to. There's probably a good reason for that.",
  ui_story_5089_50890301_103_dialog_content = "The stolen items must be hidden in the house next door.",
  ui_story_5089_50890301_104_dialog_content = "!",
  ui_story_5089_50890301_105_dialog_content = "Hey, cut it out! I'm the one who stole your stuff, so come and catch me!",
  ui_story_5089_50890301_106_dialog_content = "I knew it.",
  ui_story_5089_50890301_107_dialog_content = "I won't go in just yet, but would you be willing to calm down and talk to us in exchange?",
  ui_story_5089_50890301_108_dialog_content = "We're not bad people, I promise. In fact, if you're going through tough times, we might even be able to help.",
  ui_story_5089_50890301_109_dialog_content = "... Actually, I...",
  ui_story_5089_50890301_110_dialog_content = "Step back!",
  ui_story_5089_50890301_111_dialog_content = "What...?!",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>Jiu draws her blade faster than anyone can see.</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>With a flourish, she deflects several powerful and extremely fine metal wires.</color>",
  ui_story_5089_50890301_116_dialog_content = "There you are.",
  ui_story_5089_50890301_117_dialog_content = "Who are—",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>Without responding, the mysterious figure unleashes another ruthless wire attack!</color>",
  ui_story_5089_50890302_1_dialog_content = "Now's your chance, Jiu! Take him down!",
  ui_story_5089_50890302_2_dialog_content = "Hmph.",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>Now lying on the ground, the assassin suddenly raises his arm and launches a sneak attack with his wires!</color>",
  ui_story_5089_50890302_4_dialog_content = "Urgh!",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>Drip.</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>A single drop of crimson blood silently falls to the grimy ground.</color>",
  ui_story_5089_50890302_7_dialog_content = "Jiu...!",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>Jiu stands before their attacker, his wire caught in her bare hands.</color>",
  ui_story_5089_50890302_9_dialog_content = "My apologies for startling you, Lord PlayerName.",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>Suddenly, she clasps her hands together and pulls with all her might.</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>The assassin, who attempted to escape by leaping away, is pulled down by a blood-red metal wire and falls heavily to the ground.</color>",
  ui_story_5089_50890302_12_dialog_content = "One moment while I apprehend him.",
  ui_story_5089_50890302_13_dialog_content = "Damn... If only it was anyone other than that masked demon...",
  ui_story_5089_50890302_14_dialog_content = "Come along peacefully, and your life may be spared.",
  ui_story_5089_50890302_15_dialog_content = "Frost Blade... I may just be a scout, but both of us answer directly to the king. That means we're on the same side, doesn't it?",
  ui_story_5089_50890302_16_dialog_content = "I'm simply trying to carry out my mission. Do you really intend to keep me from fulfilling our king's orders?",
  ui_story_5089_50890302_17_dialog_content = "...",
  ui_story_5089_50890302_18_dialog_content = "You're back, Jiu! How are your wounds? That assassin just now...",
  ui_story_5089_50890302_19_dialog_content = "Forgive me, I... I let him escape.",
  ui_story_5089_50890302_20_dialog_content = "As long as you're okay, then it's fine... Wait, no, it's not fine at all!",
  ui_story_5089_50890302_21_dialog_content = "Why did you just use your hand to block his attack?! Do you not feel pain or something?! Here, let me see your wounds!",
  ui_story_5089_50890302_22_dialog_content = "They're just scratches, PlayerName, nothing more. I can tend to them myself.",
  ui_story_5089_50890302_23_dialog_content = "Again? Ugh... Never mind. Do whatever you want, I'm gonna go deal with the kids.",
  ui_story_5089_50890302_24_dialog_content = "\"Kids\"?",
  ui_story_5089_50890302_25_dialog_content = "That's right, those two kids from before. They're in that house over there.",
  ui_story_5089_50890302_26_dialog_content = "Waaaaaah! I'm so scared!",
  ui_story_5089_50890302_27_dialog_content = "J-Just stop crying already, would you? Here, I brought you some really nice stuff today!",
  ui_story_5089_50890302_28_dialog_content = "See? Lots of cute toys and a pretty lantern, just for you!",
  ui_story_5089_50890302_29_dialog_content = "And look at all these storybooks! Want me to read one to you? C'mon, don't cry...",
  ui_story_5089_50890302_30_dialog_content = "Waaaaaaaaah!",
  ui_story_5089_50890302_31_dialog_content = "And that's what happened. The kid never stole any of the prince's gold. All he wanted was a box full of toys.",
  ui_story_5089_50890302_32_dialog_content = "Who cares about your stinkin' gold?",
  ui_story_5089_50890302_33_dialog_content = "Waaaaaah! Another scary person!",
  ui_story_5089_50890302_34_dialog_content = "Oh, great. Now look at what you did! Just get out of here already! There, there, don't cry! I'll get you whatever you want, I promise!",
  ui_story_5089_50890302_35_dialog_content = "...",
  ui_story_5089_50890302_36_dialog_content = "Jiu?",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>Jiu squats down in front of the little girl, awkwardly raises her hand, and places her mask over the girl's head.</color>",
  ui_story_5089_50890302_38_dialog_content = "Wh-What do you think you're doing?! If you lay a finger on her—",
  ui_story_5089_50890302_39_dialog_content = "The wind is here, the rain is here, the Dragon King beats his drum.",
  ui_story_5089_50890302_40_dialog_content = "Beneath this mask, you'll find a place to hide, my little one.",
  ui_story_5089_50890302_41_dialog_content = "And we'll eat a melon in the sun when the storm has passed.",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>As Jiu softly recites the lullaby, the sobs of the girl hidden behind the mask gradually subside.</color>",
  ui_story_5089_50890302_43_dialog_content = "(I had no idea Jiu could be so gentle.)",
  ui_story_5089_50890302_44_dialog_content = "PlayerName! Jiu! Thank goodness I've finally found you!",
  ui_story_5089_50890302_45_dialog_content = "Oh? What's happening here? Why did Jiu decide to take off her mask?",
  ui_story_5089_50890302_46_dialog_content = "Your Highness! I was just...",
  ui_story_5089_50890302_47_dialog_content = "Um, excuse me...",
  ui_story_5089_50890302_48_dialog_content = "Huh?",
  ui_story_5089_50890302_49_dialog_content = "C-Could you sing that song one more time?",
  ui_story_5089_50890302_50_dialog_content = "It's just like... The one my mom used to sing.",
  ui_story_5089_50890302_51_dialog_content = "Of course.",
  ui_story_5089_50890302_52_dialog_content = "Really? Then can my friends come and listen too?",
  ui_story_5089_50890302_53_dialog_content = "Your friends...?",
  ui_story_5089_50890302_54_dialog_content = "Big brother Ergou! Go call the others!",
  ui_story_5089_50890302_55_dialog_content = "Guess they're not so bad after all. Just a sec, I'll go find them.",
  ui_story_5089_50890302_56_dialog_content = "What's going on, Xiaohua? Why'd you call us over?",
  ui_story_5089_50890302_57_dialog_content = "Does it really matter? It's not like we had anything better to do.",
  ui_story_5089_50890302_58_dialog_content = "What are all these grown-ups doing here...?",
  ui_story_5089_50890302_59_dialog_content = "Why are there so many kids here?",
  ui_story_5089_50890302_60_dialog_content = "The innkeeper was kind enough to apprise me of the situation here in town. Allow me to explain.",
  ui_story_5089_50890302_61_dialog_content = "Remember what that older gentleman said about the city's workshops, and how most of the town's able-bodied folks left to work in them? Lucrative as these jobs may be, they still require workers to leave their homes far behind.",
  ui_story_5089_50890302_62_dialog_content = "As such, many children have been left in the care of their grandparents, who cannot be expected to keep watch over them at all hours of the day.",
  ui_story_5089_50890302_63_dialog_content = "Unsupervised, these children tend to gather and run amok.",
  ui_story_5089_50890302_64_dialog_content = "So they're not actually related by blood? I thought those two were brother and sister, so I...",
  ui_story_5089_50890302_65_dialog_content = "Xiaohua is still my sister. My parents died early, but her family has been feeding me all this time.",
  ui_story_5089_50890302_66_dialog_content = "So of course, I agreed to take care of her when they told me they were leaving for work a few days ago.",
  ui_story_5089_50890302_67_dialog_content = "But Xiaohua really misses her parents. She's been crying these past few days, so that's why I...",
  ui_story_5089_50890302_68_dialog_content = "Wanted to cheer her up with a few toys?",
  ui_story_5089_50890302_69_dialog_content = "Yeah. But now that you've caught me, I'll take whatever beating or scolding you have for me.",
  ui_story_5089_50890302_70_dialog_content = "Even though stealing is wrong, how could I possibly scold you after knowing all of this?",
  ui_story_5089_50890302_71_dialog_content = "Ah, what should we do about these kids? Now that they've surrounded Jiu, it looks like she's totally stuck.",
  ui_story_5089_50890302_72_dialog_content = "Then you should rush to her aid right away, PlayerName.",
  ui_story_5089_50890302_73_dialog_content = "But what should I do?",
  ui_story_5089_50890302_74_dialog_content = "Asking Jiu to sing for so many people is a bit much, even for her. We should try to lighten the load for her.",
  ui_story_5089_50890302_75_dialog_content = "Come, let's go fetch my pipa from the inn.",
  ui_story_5089_50890302_76_dialog_content = "I was told long ago that you're quite skilled at the piano, but I've never heard you play. Would you be willing to join me for a duet today?",
  ui_story_5089_50890302_77_dialog_content = "I'd love to, but I don't see a piano here.",
  ui_story_5089_50890302_78_dialog_content = "Oh, that shouldn't be a problem.",
  ui_story_5089_50890302_79_dialog_content = "The musicians of the past could improvise a melody with everyday objects. I see no reason why a Caelestite couldn't do the same, especially when we have all of these cups.",
  ui_story_5089_50890302_80_dialog_content = "See? We can produce all kinds of notes by filling them with different amounts of water and striking them like this.",
  ui_story_5089_50890302_81_dialog_content = "I guess I could give it a shot.",
  ui_story_5089_50890302_82_dialog_content = "Jiu, do you still remember what I told you when we first visited Twin Pavilions Bay?",
  ui_story_5089_50890302_83_dialog_content = "If, one day, I could perform a duet with the piano player, I hoped you would come and perform a dance with your sword.",
  ui_story_5089_50890302_84_dialog_content = "B-B-But there are so many people...",
  ui_story_5089_50890302_85_dialog_content = "You're not alone, Jiu. We're with you, as well.",
  ui_story_5089_50890302_86_dialog_content = "If it's too much to ask, I won't force you. It's just that today's performance may be somewhat lacking without your help.",
  ui_story_5089_50890302_87_dialog_content = "U-Understood...",
  ui_story_5089_50890302_88_dialog_content = "How embarrassing.",
  ui_story_5089_50890302_89_dialog_content = "Hehe, I hardly think so. Just look at how brightly the children's eyes are shining, Jiu!",
  ui_story_5089_50890302_90_dialog_content = "To them, your sword dance is the best in the world!",
  ui_story_5089_50890302_91_dialog_content = "You flatter me, Your Highness. I'm only doing my best to avoid making an even bigger fool of myself.",
  ui_story_5089_50890302_92_dialog_content = "My, just look at this splendid performance! Is there anything I can do to contribute?",
  ui_story_5089_50890302_93_dialog_content = "Perhaps a jubilant song to liven things up for everyone?",
  ui_story_5089_50890302_94_dialog_content = "Oh? What songs do you know?",
  ui_story_5089_50890302_95_dialog_content = "Ahem, let me see...",
  ui_story_5089_50890302_96_dialog_content = "From south to north, we bring you our wonderful show!",
  ui_story_5089_50890302_97_dialog_content = "Be you prince or pauper, it matters not. Your spare change, however, would mean a lot!",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>Ding.</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>Surprisingly, a number of unsuspecting townspeople toss him a couple of coins.</color>",
  ui_story_5089_50890302_100_dialog_content = "Li Tianxian!",
  ui_story_5089_50890302_101_dialog_content = "I-It's all a part of the show, Your Highness! Remember to focus on the music!",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>A looming storm and a motley band of unlikely performers, each with their own concerns.</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>Far from a perfect performance, their show is more of a whimsical coincidence.</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>But at the very least, this moment—</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>Deserves a song of its own.</color>",
  ui_story_5089_50890401_1_dialog_content = "What are you turning over in your hands, PlayerName?",
  ui_story_5089_50890401_2_dialog_content = "You mean this? It's just a bronze figurine. Er Gou gave it back to me before we parted ways earlier.",
  ui_story_5089_50890401_3_dialog_content = "Xiaohua didn't want any more toys after she got that mask from Jiu, so Ergou handed over everything he stole.",
  ui_story_5089_50890401_4_dialog_content = "And as an apology, he gave me this too.",
  ui_story_5089_50890401_5_dialog_content = "He said that a nice lady gave it to him as she was passing through town. He says it's called a Moheluo doll.",
  ui_story_5089_50890401_6_dialog_content = "There were a bunch of people following her around too. They wore all black and barely said a word the entire time, it was so creepy!",
  ui_story_5089_50890401_7_dialog_content = "But she was a nice person, no doubt about it. She even invited us to one of the bigger inns for dinner, and gave us all the meat we could eat!",
  ui_story_5089_50890401_8_dialog_content = "She's pretty smart too. All the traps we set in the alley were made using her designs.",
  ui_story_5089_50890401_9_dialog_content = "She said that they're the basics of trapping techniques, and that we could become smarter by understanding them.",
  ui_story_5089_50890401_10_dialog_content = "Did she mention her name at all?",
  ui_story_5089_50890401_11_dialog_content = "No... She and her followers only stayed in town for a day, and they left just as quickly. But that reminds me!",
  ui_story_5089_50890401_12_dialog_content = "She had a weird habit of carrying a huge umbrella wherever she went, even though it had never rained while she was here!",
  ui_story_5089_50890401_13_dialog_content = "That sounds just like someone we know, doesn't it?",
  ui_story_5089_50890401_14_dialog_content = "It's true that this route is the fastest way to return to Ji Kingdom. Perhaps Ministress Armilla really did pass through here?",
  ui_story_5089_50890401_15_dialog_content = "Still, for her to play with children and treat them to luxurious dinners, all while carrying her weapons in broad daylight...",
  ui_story_5089_50890401_16_dialog_content = "It seems the most wanted criminal in the entire Ye Kingdom is actually living quite a carefree life.",
  ui_story_5089_50890401_17_dialog_content = "But with all of those black-clothed people following her around, she probably can't move around as freely as she'd like.",
  ui_story_5089_50890401_18_dialog_content = "Pardon me PlayerName, but may I see that figurine for a moment?",
  ui_story_5089_50890401_19_dialog_content = "Sure. I've been trying to sense it for useful information, but I haven't found anything.",
  ui_story_5089_50890401_20_dialog_content = "It seems our minds think alike. If there's information to be found, it may very well be hidden within this doll...",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>Late at night</color>",
  ui_story_5089_50890401_22_dialog_content = "*yawn*",
  ui_story_5089_50890401_23_dialog_content = "Ugh, my throat's so dry. I need water...",
  ui_story_5089_50890401_24_dialog_content = "Ah, the teapot's empty... Better go check the hallway.",
  ui_story_5089_50890401_25_dialog_content = "Huh? The light's still on over there. Isn't that Dantang's room?",
  ui_story_5089_50890401_26_dialog_content = "Is that you out there, PlayerName?",
  ui_story_5089_50890401_27_dialog_content = "Eh? Can you see me or something?",
  ui_story_5089_50890401_28_dialog_content = "No, but I could tell from the sound of your footsteps. Please come in.",
  ui_story_5089_50890401_29_dialog_content = "That doll again... Are you still studying it?",
  ui_story_5089_50890401_30_dialog_content = "Yes. Whether she meant to leave this behind or not, I'm certain that this doll holds some knowledge regarding Ministress Armilla.",
  ui_story_5089_50890401_31_dialog_content = "So what exactly is a Moheluo doll?",
  ui_story_5089_50890401_32_dialog_content = "It's a type of toy that was popular in the past. However, it's usually carved from clay or wood, not metal.",
  ui_story_5089_50890401_33_dialog_content = "And yet, this one's made of bronze, right?",
  ui_story_5089_50890401_34_dialog_content = "Correct, and Ministress Armilla happens to be very skilled with bronze. In fact, her earliest claim to fame came from a set of musical mechanical puppets that she personally designed and crafted.",
  ui_story_5089_50890401_35_dialog_content = "She played music alongside these mannequins, and it wasn't until the show ended that her audience realized something was amiss. That was when they realized that the musicians were all mechanical puppets.",
  ui_story_5089_50890401_36_dialog_content = "I'm impressed that Xuan Ji can create such amazing puppets... So why is this one so crude and ugly?",
  ui_story_5089_50890401_37_dialog_content = "That's another odd point that I wish to mention.",
  ui_story_5089_50890401_38_dialog_content = "Moheluo dolls are normally crafted in the likeness of a cute and lovable child, yet this one is wrinkled and grotesque.",
  ui_story_5089_50890401_39_dialog_content = "Moreover, it's meant to hold a lotus leaf or flower in its hand.",
  ui_story_5089_50890401_40_dialog_content = "Though this figurine is indeed holding a flower, a closer inspection reveals it to be a magnolia.",
  ui_story_5089_50890401_41_dialog_content = "One species thrives underwater while the other fears the flood. They're as incompatible as water and fire.",
  ui_story_5089_50890401_42_dialog_content = "This doll resembles a Moheluo doll in many ways, and yet it couldn't be more different. I can only describe it as a substitute, or even a fake.",
  ui_story_5089_50890401_43_dialog_content = "A substitute or a fake, huh...",
  ui_story_5089_50890401_44_dialog_content = "In the past, there was also a play of the exact same name.",
  ui_story_5089_50890401_45_dialog_content = "Most people aren't very familiar with the play itself, but one of its lines is extremely well-known and recognized by all.",
  ui_story_5089_50890401_46_dialog_content = "What line is that?",
  ui_story_5089_50890401_47_dialog_content = "\"You can paint a tiger's coat, but not its soul. You can see a person's face, but not their heart.\"",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5089_50890401_49_dialog_content = "!",
  ui_story_5089_50890401_50_dialog_content = "Who goes there?!",
  ui_story_5089_50890402_1_dialog_content = "Fleeing in the face of defeat? At the very least, I've taken their measure today.",
  ui_story_5089_50890402_2_dialog_content = "Were those Fate Riders just now? Or were they...",
  ui_story_5089_50890402_3_dialog_content = "I'm not sure.",
  ui_story_5089_50890402_4_dialog_content = "But as things stand, there is no distinction between them and Ye Kingdom's spies.",
  ui_story_5089_50890402_5_dialog_content = "Thankfully, there weren't many of them, and their martial arts were mediocre.",
  ui_story_5089_50890402_6_dialog_content = "They did excel at making a hasty retreat, which leads me to assume they were only scouts gathering information.",
  ui_story_5089_50890402_7_dialog_content = "But that means we've been exposed, doesn't it? Shouldn't we leave right away?",
  ui_story_5089_50890402_8_dialog_content = "Tell me, PlayerName, have you noticed anything strange?",
  ui_story_5089_50890402_9_dialog_content = "What do you... Wait!",
  ui_story_5089_50890402_10_dialog_content = "We made such a huge commotion just now... But Jiu's nowhere in sight!",
  ui_story_5089_50890402_11_dialog_content = "Why haven't those guys come back yet? They weren't killed, were they?",
  ui_story_5089_50890402_12_dialog_content = "Hmph, if they couldn't handle something this small, then they deserved to die.",
  ui_story_5089_50890402_13_dialog_content = "*sigh* I suppose that's our lot in life. Forget them, and I'm going to the restroom.",
  ui_story_5089_50890402_14_dialog_content = "Don't move.",
  ui_story_5089_50890402_15_dialog_content = "!",
  ui_story_5089_50890402_16_dialog_content = "A-Alright, you got me. I won't move.",
  ui_story_5089_50890402_17_dialog_content = "If you were able to infiltrate our camp and take me hostage like this, then I'm definitely no match for you.",
  ui_story_5089_50890402_18_dialog_content = "So could you please move your blade a bit further from my neck? After all, I won't be able to answer any questions if your hand happens to slip.",
  ui_story_5089_50890402_19_dialog_content = "Why are you here? What are your orders?",
  ui_story_5089_50890402_20_dialog_content = "Is there a specific reason you're...",
  ui_story_5089_50890402_21_dialog_content = "Enough. Answer the question.",
  ui_story_5089_50890402_22_dialog_content = "A-As you wish. We're simply following our master's order to bring his disobedient daughter back to his home.",
  ui_story_5089_50890402_23_dialog_content = "We're only helping with small family matters, that's all. We've done nothing illegal.",
  ui_story_5089_50890402_24_dialog_content = "Does helping with a \"small family matter\" usually require this many warriors?",
  ui_story_5089_50890402_25_dialog_content = "Can you blame us? Our master's house is grand, and his daughter is protected by one of the kingdom's most formidable soldiers.",
  ui_story_5089_50890402_26_dialog_content = "Our master personally assigned her to his beloved daughter, but she seems to have gone rogue along with her charge.",
  ui_story_5089_50890402_27_dialog_content = "Our master is quite disappointed with both of them.",
  ui_story_5089_50890402_28_dialog_content = "...",
  ui_story_5089_50890402_29_dialog_content = "Like I said, it's a small family matter, and it's best left in their hands.",
  ui_story_5089_50890402_30_dialog_content = "Despite his anger, our master would never hurt his daughter in any way.",
  ui_story_5089_50890402_31_dialog_content = "Even if she continues to be unreasonable, no harm will come to her. At worst, she will be confined to her home and forced to write her family's edicts over and over again.",
  ui_story_5089_50890402_32_dialog_content = "On the other hand, her guard threatened our master's plans by abandoning her duties.",
  ui_story_5089_50890402_33_dialog_content = "I can only imagine his pain after spending all those years, just to raise an ungrateful traitor. What do you make of it—",
  ui_story_5089_50890402_34_dialog_content = "Hello? Are you still there?",
  ui_story_5089_50890402_35_dialog_content = "Heh.",
  ui_story_5089_50890402_36_dialog_content = "What took you so long?",
  ui_story_5089_50890402_37_dialog_content = "Sorry, I stopped to chat with an old friend just now.",
  ui_story_5089_50890402_38_dialog_content = "Do me a favor and pass a message on to our spies when they get back.",
  ui_story_5089_50890402_39_dialog_content = "Tell them we'll have the princess home by the end of tomorrow.",
  ui_story_5089_50890402_40_dialog_content = "And if that masked demon gets in our way, consider it an act of high treason...",
  ui_story_5089_50890402_41_dialog_content = "Punishable by death.",
  ui_story_5089_50890402_42_dialog_content = "... Your Highness? PlayerName? Why are you both outside?",
  ui_story_5089_50890402_43_dialog_content = "Where were you, Jiu? We just got—",
  ui_story_5089_50890402_44_dialog_content = "PlayerName.",
  ui_story_5089_50890402_45_dialog_content = "It's late. We should retire to our rooms for the rest of the night.",
  ui_story_5089_50890402_46_dialog_content = "I still have much to consider, if you don't mind.",
  ui_story_5089_50890402_47_dialog_content = "... Okay.",
  ui_story_5089_50890402_48_dialog_content = "Good night, Dantang. You too, Jiu.",
  ui_story_5089_50890402_49_dialog_content = "Good night, PlayerName.",
  ui_story_5089_50890402_50_dialog_content = "...",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>The next day</color>",
  ui_story_5089_50890402_52_dialog_content = "Master Li? May I trouble you for a moment?",
  ui_story_5089_50890402_53_dialog_content = "Nngh... Am I still dreaming? Has the sun risen from the west today?",
  ui_story_5089_50890402_54_dialog_content = "What has possessed you to speak to me so politely today, Your Highness?",
  ui_story_5089_50890402_55_dialog_content = "... I need you to perform a divination for me.",
  ui_story_5089_50890402_56_dialog_content = "My, what a truly rare occurrence.",
  ui_story_5089_50890402_57_dialog_content = "What will it be today, Your Highness? The machinations of destiny? A forecast of fortunes? Or perhaps something more pressing, like marriage prospects?",
  ui_story_5089_50890402_58_dialog_content = "I... Simply wanted to ask about the path ahead.",
  ui_story_5089_50890402_59_dialog_content = "I have a certain matter on my hands, but I don't know how to proceed with it... Or if I can even do it, for that matter.",
  ui_story_5089_50890402_60_dialog_content = "Certainly, Your Highness! Now if you would, please hold out your hand and we can begin.",
  ui_story_5089_50890402_61_dialog_content = "Very well.",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>Clatter!</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>Two divination sticks fall into Dantang's hands. But before she can take a closer look—</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>Tianxian pours out the rest of his divination sticks.</color>",
  ui_story_5089_50890402_65_dialog_content = "Wh-What is the meaning of this, Master Li?",
  ui_story_5089_50890402_66_dialog_content = "Agh, hearing you say that feels so unnatural. Please call me Tianxian or Lying Li if you prefer.",
  ui_story_5089_50890402_67_dialog_content = "Now then, my divination sticks may not seem like much to you, but I've relied on them to roam the world for a long time now.",
  ui_story_5089_50890402_68_dialog_content = "There are those who believe in my talents. With their faith, I can help them avert all manner of chaos and calamity.",
  ui_story_5089_50890402_69_dialog_content = "There are also those who don't believe, those who laugh at my prophecies and simply go about their day.",
  ui_story_5089_50890402_70_dialog_content = "But for you to ask for my help and doubt it in the same breath, for you to seek my guidance yet refuse to follow it in good faith...",
  ui_story_5089_50890402_71_dialog_content = "This is no different than spitting upon my art.",
  ui_story_5089_50890402_72_dialog_content = "... Don't you think you may be exaggerating somewhat?",
  ui_story_5089_50890402_73_dialog_content = "I hardly think so.",
  ui_story_5089_50890402_74_dialog_content = "If I may be so bold as to ask, Lady Dantang, when the first two sticks fell into your hand, you were already hoping for a certain outcome, weren't you?",
  ui_story_5089_50890402_75_dialog_content = "...",
  ui_story_5089_50890402_76_dialog_content = "I can see I'm not mistaken. The honorable Princess Zhuohua is not one to resign herself to destiny.",
  ui_story_5089_50890402_77_dialog_content = "And since you've already made up your mind, there's no sense in playing along any further.",
  ui_story_5089_50890402_78_dialog_content = "However, I must ask that you help me put my divination sticks back in their place. It's a professional courtesy, you see?",
  ui_story_5089_50890402_79_dialog_content = "Master Li.",
  ui_story_5089_50890402_80_dialog_content = "No need for the honorific. Was I not clear about that just now?",
  ui_story_5089_50890402_81_dialog_content = "I still have one more favor to ask.",
  ui_story_5089_50890402_82_dialog_content = "... My apologies. Allow me to retract my previous statement.",
  ui_story_5089_50890402_83_dialog_content = "Come, hold out your hand once again. I'll make sure your fortune tells you to leave this matter alone.",
  ui_story_5089_50890402_84_dialog_content = "That won't be necessary. After all, I am Princess Zhuohua.",
  ui_story_5089_50890402_85_dialog_content = "My disbelief in destiny is known to all.",
  ui_story_5089_50890402_86_dialog_content = "Ah, yes, I suppose I did just say that.",
  ui_story_5089_50890402_87_dialog_content = "I really should stop doing this to myself!",
  ui_story_5089_50890402_88_dialog_content = "*Sigh* Very well, then... After all, I still owe you a debt of gratitude for saving my life.",
  ui_story_5089_50890402_89_dialog_content = "Go on, name your favor.",
  ui_story_5089_50890402_90_dialog_content = "Hey Dantang, I found an armed escort service like you asked.",
  ui_story_5089_50890402_91_dialog_content = "They agreed to return the crown prince's gold to Ji Kingdom capital.",
  ui_story_5089_50890402_92_dialog_content = "So what's next for us? Should we get going too?",
  ui_story_5089_50890402_93_dialog_content = "Not just yet.",
  ui_story_5089_50890402_94_dialog_content = "The innkeeper just brought over two fresh packs of tea, and they taste quite superb. It wouldn't hurt to spend a few more minutes enjoying our tea, would it?",
  ui_story_5089_50890402_95_dialog_content = "I guess not, but can we really afford to take it easy like this?",
  ui_story_5089_50890402_96_dialog_content = "Don't worry, this won't take long.",
  ui_story_5089_50890402_97_dialog_content = "Are you there, Jiu?",
  ui_story_5089_50890402_98_dialog_content = "... Yes, Your Highness.",
  ui_story_5089_50890402_99_dialog_content = "Come and have a cup of tea with us. I have something to tell you once we're finished here.",
  ui_story_5089_50890402_100_dialog_content = "As you wish.",
  ui_story_5089_50890402_101_dialog_content = "This tea really is delicious! It has a light but refreshing flavor and a fruity aroma that other teas usually don't have.",
  ui_story_5089_50890402_102_dialog_content = "Oh, that's because I added some \"blood-chilling powder,\" which is made from a mildly toxic fruit.",
  ui_story_5089_50890402_103_dialog_content = "... Hah?",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>Suddenly, Jiu falls to one knee.</color>",
  ui_story_5089_50890402_106_dialog_content = "J-Jiu...!",
  ui_story_5089_50890402_107_dialog_content = "Don't worry, this kind of drug only paralyzes the limbs without harming the body itself. It will naturally wear off after some time.",
  ui_story_5089_50890402_108_dialog_content = "Interestingly enough, its effects are faster and more potent in those with great inner strength and martial arts prowess.",
  ui_story_5089_50890402_109_dialog_content = "Oh, that explains why I don't feel anything yet... Wait, that's not the point!",
  ui_story_5089_50890402_110_dialog_content = "Why would you do something like this, Dantang?!",
  ui_story_5089_50890402_111_dialog_content = "Because we're out of time.",
  ui_story_5089_50890402_112_dialog_content = "Your Highness, Squawk and Jabber have informed me that quite a few people have already arrived at the inn.",
  ui_story_5089_50890402_113_dialog_content = "And it seems our new guests do not come in peace.",
  ui_story_5089_50890402_114_dialog_content = "Tianxian, not you too... Wait, who the heck are you?!",
  ui_story_5089_50890402_115_dialog_content = "Clearly, I'm the one and only Miss Jiu. Whether at rest or on the road, that much doesn't change.",
  ui_story_5089_50890402_116_dialog_content = "This isn't the time to reinvent yourself, Tianxian!",
  ui_story_5089_50890402_117_dialog_content = "Nor is it the time to be making such an unnecessary fuss, wouldn't you agree?",
  ui_story_5089_50890402_118_dialog_content = "Can you really blame me? This is completely ridiculous!",
  ui_story_5089_50890402_119_dialog_content = "That's quite enough, my friend. Now help me hide Miss Jiu in that wardrobe over there, and quickly.",
  ui_story_5089_50890402_120_dialog_content = "Uh, sure... Whoa!",
  ui_story_5089_50890402_121_dialog_content = "Jiu, what are you...",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>Jiu's body sways slightly as she resists the effects of the medicine with all her might. The sound of her bones rattling from within can almost be heard.</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>Suddenly, the wounds on her hands split open, soaking her clothes in fresh blood.</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>She forcibly moves her stiff body just enough to clutch the hem of Dantang's skirt.</color>",
  ui_story_5089_50890402_125_dialog_content = "...",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>Dantang steps back, pulling her skirt from Jiu's bloody hand.</color>",
  ui_story_5089_50890402_127_dialog_content = "Day and night for the last five years, you've been at my side. I'm eternally grateful for all that you've done for me, Jiu.",
  ui_story_5089_50890402_128_dialog_content = "You're a good person, as well as the most loyal servant anyone could ask for.",
  ui_story_5089_50890402_129_dialog_content = "But there's no way to maintain our peace any longer.",
  ui_story_5089_50890402_130_dialog_content = "I know you don't wish to harm me, but you would never defy my uncle's orders, either.",
  ui_story_5089_50890402_131_dialog_content = "As one person, you cannot walk two opposing paths, or serve as a sword in the hands of two different people with opposing goals.",
  ui_story_5089_50890402_132_dialog_content = "Princes... Dantang...",
  ui_story_5089_50890402_133_dialog_content = "In truth, I have no right to give you orders until you make your decision.",
  ui_story_5089_50890402_134_dialog_content = "Just know that if you refuse to do so, someone like me will eventually step in and take that right from you.",
  ui_story_5089_50890402_135_dialog_content = "By forfeiting your freedom of choice, you will naturally become a puppet at the mercy of others.",
  ui_story_5089_50890402_136_dialog_content = "Your situation right now should be proof of that.",
  ui_story_5089_50890402_137_dialog_content = "Jiu.",
  ui_story_5089_50890402_138_dialog_content = "From this moment on, you are now relieved of your duty as guardian of Princess Zhuohua.",
  ui_story_5089_50890402_139_dialog_content = "!",
  ui_story_5089_50890402_140_dialog_content = "I neither want nor need you as you are now.",
  ui_story_5089_50890402_141_dialog_content = "I refuse to live under your protection or, worse, your surveillance.",
  ui_story_5089_50890402_142_dialog_content = "What I want is...",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>Dantang's last few words were drowned out by a loud noise outside.</color>",
  ui_story_5089_50890402_145_dialog_content = "In you go!",
  ui_story_5089_50890402_146_dialog_content = "?",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>I was also pushed into the wardrobe.</color>",
  ui_story_5089_50890402_148_dialog_content = "Forgive me for selfishly taking matters into my own hands, PlayerName.",
  ui_story_5089_50890402_149_dialog_content = "I'm leaving Jiu and everything else in your hands now.",
  ui_story_5089_50890402_150_dialog_content = "Wait, Dantang!",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>The wardrobe's doors swing shut.</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>The next moment, the room's door is suddenly thrown open.</color>",
  ui_story_5089_50890402_153_dialog_content = "Ah, finally. Securing an audience with you hasn't been very easy, Princess Zhuohua.",
  ui_story_5089_50890402_154_dialog_content = "(That voice!)",
  ui_story_5089_50890402_155_dialog_content = "Zhui Hu...",
  ui_story_5089_50890402_156_dialog_content = "It seems Ministress Armilla was right: you are very much alive and well.",
  ui_story_5089_50890402_157_dialog_content = "But of course. After all, I couldn't possibly die before creating the world's most powerful Clockwork Beast.",
  ui_story_5089_50890402_158_dialog_content = "I didn't have a chance to ask you before, but the rumors of your affiliation with the Fate Riders were clearly true.",
  ui_story_5089_50890402_159_dialog_content = "Yes, but isn't that perfectly normal? Anyone willing to support my craft deserves to be called my master.",
  ui_story_5089_50890402_160_dialog_content = "Still, it hasn't been easy obtaining the Zhuyin Flame once more. I've been busy developing a new power system for the latest Stinger.",
  ui_story_5089_50890402_161_dialog_content = "But these men insisted on dragging me here to meet you.",
  ui_story_5089_50890402_162_dialog_content = "They did promise me something nice for my troubles, however.",
  ui_story_5089_50890402_163_dialog_content = "They said that if you or your guard resisted us in any way, I could test out my newest weapon on you.",
  ui_story_5089_50890402_164_dialog_content = "Now then, would you mind putting up a bit of a struggle? Even the smallest one will do, hehehe.",
  ui_story_5089_50890402_165_dialog_content = "I see no reason to do so.",
  ui_story_5089_50890402_166_dialog_content = "I am Princess Zhuohua of Ye Kingdom, and aside from you, the rest of these soldiers are my uncle's loyal servants.",
  ui_story_5089_50890402_167_dialog_content = "As such, they would never harm me in any way. They've simply come to welcome me home, right Jiu?",
  ui_story_5089_50890402_168_dialog_content = "*nods*",
  ui_story_5089_50890402_169_dialog_content = "Such a pity, but have it your way then. There's still much to do in my workshop, so let's get going.",
  ui_story_5089_50890402_170_dialog_content = "... Wait. There were two more people traveling with the princess.",
  ui_story_5089_50890402_171_dialog_content = "Yes, but that fortune-telling fraud fled the moment he saw your men approaching.",
  ui_story_5089_50890402_172_dialog_content = "As for the Caelestite, he's incapable of accomplishing anything on his own, especially in a foreign land. Why are you so worried about them?",
  ui_story_5089_50890402_173_dialog_content = "My uncle's orders were to escort me back to the capital, and no one else. Am I mistaken?",
  ui_story_5089_50890402_174_dialog_content = "No, Your Highness... This way, please.",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>The room returns to silence.</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>But this time, only Jiu and I are left.</color>",
  ui_story_5089_50890501_1_dialog_content = "... What were those two thinking?!",
  ui_story_5089_50890501_2_dialog_content = "She was just talking about fighting for more time, and now she's walking right into their trap!",
  ui_story_5089_50890501_3_dialog_content = "How are we supposed to keep ourselves safe when someone like Zhui Hu is involved?!",
  ui_story_5089_50890501_4_dialog_content = "None of this makes sense! You think so too, don't you, Jiu?",
  ui_story_5089_50890501_5_dialog_content = "I... I don't know.",
  ui_story_5089_50890501_6_dialog_content = "It seems Princess Dantang no longer trusts me.",
  ui_story_5089_50890501_7_dialog_content = "Perhaps she was right. Perhaps I've failed in my duties.",
  ui_story_5089_50890501_8_dialog_content = "But now that I'm no longer her guard, I don't know what must be done...",
  ui_story_5089_50890501_9_dialog_content = "What are you talking about? There's still one thing that absolutely has to be done, remember?",
  ui_story_5089_50890501_10_dialog_content = "What?",
  ui_story_5089_50890501_11_dialog_content = "Dantang said we were out of time.",
  ui_story_5089_50890501_12_dialog_content = "But she wasn't in a hurry when we were on the ship. She even said she could understand your hesitation.",
  ui_story_5089_50890501_13_dialog_content = "But after last night, something happened that made her change her attitude.",
  ui_story_5089_50890501_14_dialog_content = "Whatever it is, it must have something to do with that doll.",
  ui_story_5089_50890501_15_dialog_content = "Not only that, but she said she's leaving the rest to me, even though she didn't explain anything...",
  ui_story_5089_50890501_16_dialog_content = "My guess is that we need to keep looking for clues that'll lead us to Xuan Ji. Once we find her, I'm sure we'll understand things much better.",
  ui_story_5089_50890501_17_dialog_content = "You can argue with Dantang all you want once we do, Jiu.",
  ui_story_5089_50890501_18_dialog_content = "Argue... with Her Highness? I-I would never do something so presumptuous!",
  ui_story_5089_50890501_19_dialog_content = "But she's clearly not your master anymore, right?",
  ui_story_5089_50890501_20_dialog_content = "Even so...",
  ui_story_5089_50890501_21_dialog_content = "Whatever the situation may be, she made this decision on her own without consulting either of us.",
  ui_story_5089_50890501_22_dialog_content = "To be honest, even I'm a little upset with her.",
  ui_story_5089_50890501_23_dialog_content = "Not only did she leave me in a place I know almost nothing about...",
  ui_story_5089_50890501_24_dialog_content = "She also put me in a situation where I had to watch my friends risk their lives for me.",
  ui_story_5089_50890501_25_dialog_content = "So once this mess is all sorted out, let's go give her a piece of our minds.",
  ui_story_5089_50890501_26_dialog_content = "We'll have a nice, long talk with the princess about how to properly treat her friends.",
  ui_story_5089_50890501_27_dialog_content = "PlayerName...",
  ui_story_5089_50890501_28_dialog_content = "But before we do that, could you please lend me your support?",
  ui_story_5089_50890501_29_dialog_content = "After all, there's only so much I can do on my own.",
  ui_story_5089_50890501_30_dialog_content = "I was raised under the King of Ye's command. Wielding a blade and following orders are all that I know.",
  ui_story_5089_50890501_31_dialog_content = "But if my skills can be put to good use, PlayerName, then please command me as you see fit.",
  ui_story_5089_50890501_32_dialog_content = "Uh sure, but let's start by changing that mindset a little bit...",
  ui_story_5089_50890501_33_dialog_content = "Just remember that we're friends and always help each other out. Simple enough, right?",
  ui_story_5089_50890501_34_dialog_content = "... I've never had a friend before.",
  ui_story_5089_50890501_35_dialog_content = "I wouldn't let Dantang hear you say that, or else she'll be angrier than us!",
  ui_story_5089_50890501_36_dialog_content = "Her Highness Lady Dantang was born to a high and noble bloodline! How could she possibly be friends with someone like me?! I—",
  ui_story_5089_50890501_37_dialog_content = "Alright, I get it. The medicine still hasn't worn off, so just give me your hand and take it slowly.",
  ui_story_5089_50890501_38_dialog_content = "Come on, we're heading to the capital together.",
  ui_story_5089_50890502_1_dialog_content = "Roar—",
  ui_story_5089_50890502_2_dialog_content = "The wicked spirits have been purged, PlayerName.",
  ui_story_5089_50890502_3_dialog_content = "We're not that far from the town, are we?",
  ui_story_5089_50890502_4_dialog_content = "There are plenty of other villages around here too, and the royal capital is less than a half-hour away.",
  ui_story_5089_50890502_5_dialog_content = "I thought Longzhou's annual Eclipsite-hunting ritual kept them well outside of populated areas like this?",
  ui_story_5089_50890502_6_dialog_content = "Well...",
  ui_story_5089_50890502_7_dialog_content = "Then again, Tianxian mentioned that he ran into Eclipsites too.",
  ui_story_5089_50890502_8_dialog_content = "Hopefully, it's just a coincidence. We don't have time to deal with more trouble right now... Let's keep moving.",
  ui_story_5089_50890502_9_dialog_content = "Understood.",
  ui_story_5089_50890502_10_dialog_content = "Is there something over there?",
  ui_story_5089_50890502_11_dialog_content = "?",
  ui_story_5089_50890502_12_dialog_content = "Sorry, it just feels like your gaze keeps drifting over there.",
  ui_story_5089_50890502_13_dialog_content = "It's the village where I lived when I was young.",
  ui_story_5089_50890502_14_dialog_content = "Your hometown, huh? Did you want to go back and take a look?",
  ui_story_5089_50890502_15_dialog_content = "There's no need. I lost my family long ago, and I'm not very familiar with the other villagers.",
  ui_story_5089_50890502_16_dialog_content = "Besides, the two remaining cottages can hardly be called homes anymore.",
  ui_story_5089_50890502_17_dialog_content = "We have more important matters at hand.",
  ui_story_5089_50890502_18_dialog_content = "Look over there, PlayerName. Before you is the capital of Ye Kingdom: Jingliang City.",
  ui_story_5089_50890502_19_dialog_content = "...",
  ui_story_5089_50890502_20_dialog_content = "(I thought after seeing the gold and jade of Ji Kingdom's palace, I wouldn't be surprised by anything else in Longzhou.)",
  ui_story_5089_50890502_21_dialog_content = "(But in Jingliang City, dragon-shaped machines spew clouds of mist from the rooftops, while copper phoenixes deliver messages all across the city.)",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>The streets are wide and bustling as smoke and fire erupt from countless workshops.</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>In place of opulent ornaments and extravagant natural beauty, Jingliang City is characterized by metallic hues and the pulsating energy of ingenious craftsmanship.</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5089_50890502_25_dialog_content = "Wh-What was that?!",
  ui_story_5089_50890502_26_dialog_content = "Just the sound of a Huolong Carrier.",
  ui_story_5089_50890502_27_dialog_content = "PlayerName, have you noticed anything unusual about the streets here?",
  ui_story_5089_50890502_28_dialog_content = "You're talking about the two metal tracks embedded in the ground, right? I've been seeing them from time to time.",
  ui_story_5089_50890502_29_dialog_content = "They're really similar to something I've seen before...",
  ui_story_5089_50890502_30_dialog_content = "The Huolong Carrier was designed for the royal court many years ago by a great inventor known as Lord Houfeng.",
  ui_story_5089_50890502_31_dialog_content = "By combining both Water and Flame Force Arts as its power source, the Huolong Carrier is capable of transporting massive amounts of cargo without losing its mobility.",
  ui_story_5089_50890502_32_dialog_content = "Its main drawbacks are its excessive energy consumption and its limitation to very specific tracks.",
  ui_story_5089_50890502_33_dialog_content = "As such, the royal court is charged with most of its planning and infrastructure, while the owners of larger workshops support its construction through funding.",
  ui_story_5089_50890502_34_dialog_content = "In exchange for assisting with the Huolong Carrier's tracks, workshop owners are also given priority when transporting goods and materials.",
  ui_story_5089_50890502_35_dialog_content = "Just as I thought... It's a steam train, isn't it?!",
  ui_story_5089_50890502_36_dialog_content = "A \"steam train\"? What's that?",
  ui_story_5089_50890502_37_dialog_content = "Think of it as Astra's own version of the Huolong Carrier. I'm impressed that Lord Houfeng was able to invent something like it too!",
  ui_story_5089_50890502_38_dialog_content = "Princess Dantang said something similar in the past.",
  ui_story_5089_50890502_39_dialog_content = "She believes that with his creations, his talents must rival Lady Xuan Ji's.",
  ui_story_5089_50890502_40_dialog_content = "At one point, they said he was developing some sort of giant kite that could transport people to and from distant lands.",
  ui_story_5089_50890502_41_dialog_content = "Unfortunately, due to political strife within the kingdom, he disappeared without a trace and his research was ultimately halted.",
  ui_story_5089_50890502_42_dialog_content = "That's a shame. I'm sure it would've been just as impressive as his Huolong Carrier, if not more so.",
  ui_story_5089_50890502_43_dialog_content = "You seem to know a lot about this, Jiu. I didn't think you were interested in this kind of stuff?",
  ui_story_5089_50890502_44_dialog_content = "It's only because Her Highne told me so much about it.",
  ui_story_5089_50890502_45_dialog_content = "She also lamented being too young and naive at the time, otherwise she would have found a way to retain such a talented inventor.",
  ui_story_5089_50890502_46_dialog_content = "Heh, that definitely sounds like Dantang.",
  ui_story_5089_50890502_47_dialog_content = "Alright, Jiu, let's do our best to find a way to do it.",
  ui_story_5089_50890502_48_dialog_content = "We need to keep Ye Kingdom from losing a brilliant inventor like Xuan Ji and their dutiful Princess Zhuohua.",
  ui_story_5089_50890502_49_dialog_content = "First, we must figure out a way to meet them...",
  ui_story_5089_50890502_50_dialog_content = "Criminals whom the king's personal guards apprehend are normally detained in the Sky Prison on the outer edge of the palace.",
  ui_story_5089_50890502_51_dialog_content = "Though it's protected by a legion of soldiers, even if I fall, I'm certain you will succeed in rescuing Lady Xuan Ji from her imprisonment, PlayerName.",
  ui_story_5089_50890502_52_dialog_content = "Wh-Why are we starting off with the most aggressive strategy?!",
  ui_story_5089_50890502_53_dialog_content = "PlayerName, when you asked for my help, did you not mean for me to become your sword?",
  ui_story_5089_50890502_54_dialog_content = "I'm not trying to become an enemy of the court, Jiu! And I certainly don't plan on sending you off to die!",
  ui_story_5089_50890502_55_dialog_content = "There's gotta be another way. Let's just go check out that Sky Prison first.",
  ui_story_5089_50890502_56_dialog_content = "If they hurt Xuan Ji in any way... That's when we'll use our final resort.",
  ui_story_5089_50890502_57_dialog_content = "I've been meaning to ask, Jiu. Do lots of people recognize you here in Jingliang City?",
  ui_story_5089_50890502_58_dialog_content = "Perhaps. As the king's guard, I served him mostly in the shadows and only interacted with my fellow guards as needed.",
  ui_story_5089_50890502_59_dialog_content = "Some people may recognize me by my mask, but not much else. In fact, they may not even know if I'm a man or a woman.",
  ui_story_5089_50890502_60_dialog_content = "After all, they only refer to me as \"the masked demon\" when they talk behind my back.",
  ui_story_5089_50890502_61_dialog_content = "But if you think it will help, PlayerName...",
  ui_story_5089_50890502_62_dialog_content = "I suppose this will have to do.",
  ui_story_5089_50890502_63_dialog_content = "Uh, sure... For some reason, though, I feel like you stand out even more now.",
  ui_story_5089_50890502_64_dialog_content = "As I thought, my face really is an unbearable sight... I'll go find something to cover it right away.",
  ui_story_5089_50890502_65_dialog_content = "Th-That's not what I meant! Where'd you get that idea anyway?! The truth is, you actually look really... Uh...",
  ui_story_5089_50890502_66_dialog_content = "Really beautiful!",
  ui_story_5089_50890502_67_dialog_content = "?",
  ui_story_5089_50890502_68_dialog_content = "Er, never mind. There's no time to waste, so let's keep moving.",
  ui_story_5089_50890502_69_dialog_content = "This place is under the jurisdiction of the royal palace. If you have no business here, then leave at once.",
  ui_story_5089_50890502_70_dialog_content = "Guess the direct approach is impossible after all.",
  ui_story_5089_50890502_71_dialog_content = "Then allow me to infiltrate the premises...",
  ui_story_5089_50890502_72_dialog_content = "L-Let's just save that for last!",
  ui_story_5089_50890502_73_dialog_content = "That's right, I still have Xuan Ji's clockwork bird with me. Maybe I can use it to communicate with her if we can distract the soldiers.",
  ui_story_5089_50890502_74_dialog_content = "Then allow me to distract the soldiers—",
  ui_story_5089_50890502_75_dialog_content = "Wait—Uh-oh!",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>To their surprise, the clockwork bird suddenly springs to life and takes flight.</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>As though following a predetermined program, it heads straight for the palace gates in search of Xuan Ji...</color>",
  ui_story_5089_50890502_78_dialog_content = "We're done for... Huh?",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>A streak of golden light flashes from an unknown origin.</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>The two soldiers, seemingly oblivious to it, allow the clockwork bird to pass through the gates.</color>",
  ui_story_5089_50890502_81_dialog_content = "... Do you still need me to distract the soldiers?",
  ui_story_5089_50890502_82_dialog_content = "Well...",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>Suddenly, a faint noise can be heard from beyond the palace gates.</color>",
  ui_story_5089_50890502_84_dialog_content = "Forgive me, but may I ask if a distinguished guest is waiting outside?",
  ui_story_5089_50890502_85_dialog_content = "Uh, who are you?",
  ui_story_5089_50890502_86_dialog_content = "Just a lowly maid, sir. Now, please follow me.",
  ui_story_5089_50890502_87_dialog_content = "Lady Xuan Ji has been expecting you.",
  ui_story_5089_50890502_88_dialog_content = "Welcome, PlayerName. We haven't seen each other since last spring, have we?",
  ui_story_5089_50890502_89_dialog_content = "And you as well, Jiu. Have you been well?",
  ui_story_5089_50890502_90_dialog_content = "It's the real Xuan Ji! Are you okay? They didn't hurt you, did they?!",
  ui_story_5089_50890502_91_dialog_content = "Of course not—Ugh, these rails are such a nuisance. Just a moment, please.",
  ui_story_5089_50890502_92_dialog_content = "... Hah?",
  ui_story_5089_50890502_93_dialog_content = "Come, have a seat! You haven't had lunch yet, have you? If not, you came at just the right time!",
  ui_story_5089_50890502_94_dialog_content = "Fixit, Crafty, go see what they have in the palace kitchens today.",
  ui_story_5089_50890502_95_dialog_content = "I won a bet against Jie Gaoqing, and he promised to bring me a fresh fish today.",
  ui_story_5089_50890502_96_dialog_content = "Tell the cooks to steam it and serve it with black bean sauce.",
  ui_story_5089_50890502_97_dialog_content = "As you wish.",
  ui_story_5089_50890502_98_dialog_content = "Uh, Xuan Ji...? What's going on here?",
  ui_story_5089_50890502_99_dialog_content = "Oh don't worry, the palace food is perfectly delicious. It's just hard to get something this fresh around here, is all.",
  ui_story_5089_50890502_100_dialog_content = "...",
  ui_story_5089_50890502_101_dialog_content = "Suddenly, I feel like our determination to bust you out of prison was a total joke.",
  ui_story_5089_50890502_102_dialog_content = "Did you even get arrested in the first place? Is this even a prison, for that matter?!",
  ui_story_5089_50890502_103_dialog_content = "Hahaha, of course it is! Can't you see how empty my wine gourd is?",
  ui_story_5089_50890502_104_dialog_content = "But remember, I was once an esteemed member of the royal court. I still have many friends on the inside, including a few colleagues who care deeply for my safety.",
  ui_story_5089_50890502_105_dialog_content = "Besides, no matter how much the king may resent me, punishing me without formally convicting me first wouldn't be right.",
  ui_story_5089_50890502_106_dialog_content = "Unfortunately, since I'm still detained as a criminal, they won't provide me anything stronger than plain tea. Hope you don't mind!",
  ui_story_5089_50890502_107_dialog_content = "Miss Jiu, PlayerName.",
  ui_story_5089_50890502_108_dialog_content = "The journey here must have been quite difficult. Allow me to raise this cup of tea in your honor.",
  ui_story_5089_50890502_109_dialog_content = "Thank you for your kind consideration.",
  ui_story_5089_50890502_110_dialog_content = "I never expected that the greatest treasure from my journey to Astra wouldn't be the Zhuyin Flame, but the friends I made along the way.",
  ui_story_5089_50890502_111_dialog_content = "Th-There's no need to be so formal, Xuan Ji...",
  ui_story_5089_50890502_112_dialog_content = "But that reminds me! Do you happen to know who has the Zhuyin Flame now? Because Dantang is—",
  ui_story_5089_50890502_113_dialog_content = "Shhh.",
  ui_story_5089_50890502_114_dialog_content = "Don't forget, I'm just a prisoner now. There's no point in telling me about the world beyond my cell.",
  ui_story_5089_50890502_115_dialog_content = "And besides, I have everything I could ever want right here. It's so comfortable that I could almost forget about my life's troubles.",
  ui_story_5089_50890502_116_dialog_content = "Why would I care about anything else?",
  ui_story_5089_50890502_117_dialog_content = "Liar.",
  ui_story_5089_50890502_118_dialog_content = "Oh?",
  ui_story_5089_50890502_119_dialog_content = "There isn't a single piece of machinery in here, is there?",
  ui_story_5089_50890502_120_dialog_content = "Who in the right mind would believe that the famous Xuan Ji would find this place even remotely comfortable?",
  ui_story_5089_50890502_121_dialog_content = "Hahaha, as straightforward as ever, PlayerName.",
  ui_story_5089_50890502_122_dialog_content = "Then please listen closely.",
  ui_story_5089_50890502_123_dialog_content = "The king personally ordered my capture, and now my fate is entirely in his hands.",
  ui_story_5089_50890502_124_dialog_content = "Even if I were to escape by relying on Miss Jiu's superior martial prowess, my name would still be tarnished and my words would never be accepted.",
  ui_story_5089_50890502_125_dialog_content = "But you must know something about all of this, right? What should we do now?",
  ui_story_5089_50890502_126_dialog_content = "Now's not the time to consider \"what to do.\"",
  ui_story_5089_50890502_127_dialog_content = "Though it's not my place to comment on external affairs, I did serve as a strategist for a time, so I can share some of my experiences with you.",
  ui_story_5089_50890502_128_dialog_content = "For instance, if you wish to achieve something but lack the strength and vision to do so, you must rely on strategy and tactics to advance.",
  ui_story_5089_50890502_129_dialog_content = "The best choice will always be to move with purpose and gain momentum.",
  ui_story_5089_50890502_130_dialog_content = "Move with the flow of your circumstances, and the heavens will guide your path.",
  ui_story_5089_50890502_131_dialog_content = "But remember, you must first broaden your horizons to discern the looming wave's direction.",
  ui_story_5089_50890502_132_dialog_content = "Only then will you be able to gain momentum when the opportunity presents itself.",
  ui_story_5089_50890502_133_dialog_content = "Much like a clockwork creature, even the tiniest turn of a cog can set the entire body in motion.",
  ui_story_5089_50890502_134_dialog_content = "And even the simplest of actions requires the coordination of several parts.",
  ui_story_5089_50890502_135_dialog_content = "You never know which tiny component might fail, causing the entire machine to collapse.",
  ui_story_5089_50890502_136_dialog_content = "But... I don't even know where to look.",
  ui_story_5089_50890502_137_dialog_content = "Then let's start by taking a look around us, shall we?",
  ui_story_5089_50890502_138_dialog_content = "For example, right now it's only the two of you standing before me. Doesn't that already seem like a deliberate part of someone else's plan?",
  ui_story_5089_50890502_139_dialog_content = "!",
  ui_story_5089_50890502_140_dialog_content = "Furthermore, we've known Miss Jiu here for quite some time now...",
  ui_story_5089_50890502_141_dialog_content = "But do you actually know where she came from?",
  ui_story_5089_50890502_142_dialog_content = "Lady Xuan Ji, the dishes are ready.",
  ui_story_5089_50890502_143_dialog_content = "The king's guards suddenly appeared just now, claiming that they wish to bring you in for questioning.",
  ui_story_5089_50890502_144_dialog_content = "Crafty is hindering them as we speak,, but I'm afraid she won't be able to keep them away for much longer...",
  ui_story_5089_50890502_145_dialog_content = "I understand.",
  ui_story_5089_50890502_146_dialog_content = "An interrogation right as we were about to have lunch. Their timing couldn't be more terrible!",
  ui_story_5089_50890502_147_dialog_content = "Thanks to them, PlayerName and Miss Jiu have to miss out on our lovely steamed fish.",
  ui_story_5089_50890502_148_dialog_content = "Ah, but such is the life of a prisoner, I suppose.",
  ui_story_5089_50890502_149_dialog_content = "... Why don't you just come with us, Xuan Ji?",
  ui_story_5089_50890502_150_dialog_content = "We saw it with our own eyes earlier. The king's guards are also in league with Zhui Hu, and they—",
  ui_story_5089_50890502_151_dialog_content = "Fixit, please see our guests out.",
  ui_story_5089_50890502_152_dialog_content = "Xuan Ji!",
  ui_story_5089_50890502_153_dialog_content = "That's enough, now off you go. We each have our own matters to deal with, don't we?",
  ui_story_5089_50890502_154_dialog_content = "I have complete trust in you, PlayerName.",
  ui_story_5089_50890502_155_dialog_content = "You'll definitely find your momentum soon enough.",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>Fixit leaves after escorting us out of the city in a carriage.</color>",
  ui_story_5089_50890601_2_dialog_content = "Looks like it's just the two of us again, Jiu.",
  ui_story_5089_50890601_3_dialog_content = "Xuan Ji said so much, but what did any of it mean...?",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>Growl—</color>",
  ui_story_5089_50890601_5_dialog_content = "...",
  ui_story_5089_50890601_6_dialog_content = "Now that I think about it, we haven't had anything to eat today.",
  ui_story_5089_50890601_7_dialog_content = "I'll go ask if any of the villagers would be willing to feed us in exchange for payment.",
  ui_story_5089_50890601_8_dialog_content = "Please wait here, PlayerName.",
  ui_story_5089_50890601_9_dialog_content = "Okay... Huh?",
  ui_story_5089_50890601_10_dialog_content = "Is there really a village around here?",
  ui_story_5089_50890601_11_dialog_content = "Rice has been selling for higher prices lately, which is unlikely around these parts, so I sold all of my rice to some passing merchants from Ji Kingdom.",
  ui_story_5089_50890601_12_dialog_content = "Unfortunately, I only have a bit of porridge made from our family's aged brown rice. It's not much, but I hope it's to your liking...",
  ui_story_5089_50890601_13_dialog_content = "We don't mind at all! We haven't eaten all day, so food is a blessing.",
  ui_story_5089_50890601_14_dialog_content = "Pardon me, but is there a reason you aren't eating? Would you like something else to go with your porridge?",
  ui_story_5089_50890601_15_dialog_content = "No, thank you. I don't require food right now.",
  ui_story_5089_50890601_16_dialog_content = "Now, now, that won't do! Your body won't be able to keep up without a decent meal, you know?",
  ui_story_5089_50890601_17_dialog_content = "As I said, I don't require sustenance right now. I've gone without food for days during mission, which has never affected my swordsmanship.",
  ui_story_5089_50890601_18_dialog_content = "What's more, I would prefer not to scare anyone with my appearance.",
  ui_story_5089_50890601_19_dialog_content = "About that...",
  ui_story_5089_50890601_20_dialog_content = "Your mask and manner of speech are a bit familiar... Wait! Jiu-mei... Is that you?",
  ui_story_5089_50890601_21_dialog_content = "\"Jiu-mei\"?",
  ui_story_5089_50890601_22_dialog_content = "... Yes.",
  ui_story_5089_50890601_23_dialog_content = "It's been some time, Uncle Li.",
  ui_story_5089_50890601_24_dialog_content = "Good heavens! I can't believe you're still alive!",
  ui_story_5089_50890601_25_dialog_content = "After your parents died so tragically that year, even the authorities were convinced that you died along with them!",
  ui_story_5089_50890601_26_dialog_content = "You were just a child back then! My, how you've grown, Jiu-mei!",
  ui_story_5089_50890601_27_dialog_content = "How have you been all these years, my girl...?",
  ui_story_5089_50890601_28_dialog_content = "I've been well, Uncle Li. A kind man took me in and gave me a good life.",
  ui_story_5089_50890601_29_dialog_content = "Good, good! Hearing that makes my heart swell with joy!",
  ui_story_5089_50890601_30_dialog_content = "Come, sit down and have some porridge! Wait here while Uncle Li fetches you some pickled vegetables!",
  ui_story_5089_50890601_31_dialog_content = "This must be your hometown, right, Jiu?",
  ui_story_5089_50890601_32_dialog_content = "In a manner of speaking, yes.",
  ui_story_5089_50890601_33_dialog_content = "My family originally lived in an even more remote village. We moved here to avoid a disaster.",
  ui_story_5089_50890601_34_dialog_content = "A disaster?",
  ui_story_5089_50890601_35_dialog_content = "Yes. I wasn't even ten years old then, so I don't remember many details.",
  ui_story_5089_50890601_36_dialog_content = "I believe a certain noble took a liking to my face, and wanted to buy me to keep as a servant.",
  ui_story_5089_50890601_37_dialog_content = "But when my parents refused, he and his men began harassing us at every turn. Eventually, we fled to this place.",
  ui_story_5089_50890601_38_dialog_content = "After that, my parents forced me to wear a mask and had me tell everyone that I looked like a demon, unfit to be seen by others.",
  ui_story_5089_50890601_39_dialog_content = "That's unbelievable...",
  ui_story_5089_50890601_40_dialog_content = "I didn't mind wearing it. After all, my face caused my family to suffer, and I've never been one for talking to others.",
  ui_story_5089_50890601_41_dialog_content = "If anything, my parents felt more remorse than I did.",
  ui_story_5089_50890601_42_dialog_content = "Whenever the other village children called me a freak, my mother held and sang to me.",
  ui_story_5089_50890601_43_dialog_content = "And my father would give me the sweet melons he couldn't bear to eat himself.",
  ui_story_5089_50890601_44_dialog_content = "Then that lullaby you sang earlier... It was made just for you, wasn't it? Your parents must've really loved you.",
  ui_story_5089_50890601_45_dialog_content = "Can I ask what happened to them?",
  ui_story_5089_50890601_46_dialog_content = "There's a mountain just to the west of this village. You noticed it earlier, didn't you PlayerName?",
  ui_story_5089_50890601_47_dialog_content = "Uh... Which one again?",
  ui_story_5089_50890601_48_dialog_content = "Come. We'll talk outside.",
  ui_story_5089_50890601_49_dialog_content = "Jiu-mei... Are you and your friend leaving so soon?",
  ui_story_5089_50890601_50_dialog_content = "Yes, Uncle Li. We'd like to visit the mine over there.",
  ui_story_5089_50890601_51_dialog_content = "Very well, but you should know that the mine was depleted just a few years ago, and the laborers have all left as well.",
  ui_story_5089_50890601_52_dialog_content = "A large workshop was built on that piece of land afterward, but nothing of note seems to have been produced there.",
  ui_story_5089_50890601_53_dialog_content = "One of the younger men in our village went there seeking work, but there wasn't a single soul there. From what we gather, the place has been abandoned for some time.",
  ui_story_5089_50890601_54_dialog_content = "One more thing, Jiu-mei...",
  ui_story_5089_50890601_55_dialog_content = "Yes?",
  ui_story_5089_50890601_56_dialog_content = "I-It's nothing terribly important... It's just that we've all been struggling for the last few years.",
  ui_story_5089_50890601_57_dialog_content = "But you were fortunate enough to find a good life, so please... Live well and be happy.",
  ui_story_5089_50890601_58_dialog_content = "If your parents could see you now, I'm sure they would also be overjoyed with you.",
  ui_story_5089_50890601_59_dialog_content = "... Understood.",
  ui_story_5089_50890601_60_dialog_content = "Is that the mountain you mentioned earlier, Jiu?",
  ui_story_5089_50890601_61_dialog_content = "Yes. Before our king ascended to the throne, all of these lands, including mine, were his domain.",
  ui_story_5089_50890601_62_dialog_content = "He set up a labor camp at the foot of the mountain, where he would put refugees and prisoners to work.",
  ui_story_5089_50890601_63_dialog_content = "One day, two of the king's retainers were escorting a death row inmate to the labor camp, but they got lazy and decided to take up lodging at our nearby home.",
  ui_story_5089_50890601_64_dialog_content = "My parents were forced to serve them all day and trade our precious grain supplies for their wine. They even had to deliver food to that prisoner.",
  ui_story_5089_50890601_65_dialog_content = "In their drunken stupor, they insisted on seeing my true face. They forcibly removed my mask and threatened to harm me.",
  ui_story_5089_50890601_66_dialog_content = "That was when a mysterious passerby knocked down the heavy fence behind my attackers, trapping and killing them in the process.",
  ui_story_5089_50890601_67_dialog_content = "He kept himself hidden in the shadows the entire time, most likely to avoid being implicated in their deaths. But I didn't have the time to think about him or his actions.",
  ui_story_5089_50890601_68_dialog_content = "All I knew was that I had caused my parents trouble again, so I went back to look for them...",
  ui_story_5089_50890601_69_dialog_content = "But when I returned, all I found were their bodies lying in a pool of blood.",
  ui_story_5089_50890601_70_dialog_content = "Beside them was a spilled bowl of piping-hot porridge. The prisoner had long since broken free from his chains and escaped.",
  ui_story_5089_50890601_71_dialog_content = "Sometimes, I wonder if there is some truth to the saying, \"Fate makes fools of us all.\"",
  ui_story_5089_50890601_72_dialog_content = "I've never been afraid. Even when others called me a freak or a demon, or subjected me to insult and injury, I never felt fearful of them.",
  ui_story_5089_50890601_73_dialog_content = "But on that day, when I saw my parents' lifeless bodies... That was the day I truly felt fear.",
  ui_story_5089_50890601_74_dialog_content = "But just that once, my mother couldn't be there to sing her song to me.",
  ui_story_5089_50890601_75_dialog_content = "Forgive me, I've said too much. From now on, I'll—",
  ui_story_5089_50890601_76_dialog_content = "Jiu!",
  ui_story_5089_50890601_77_dialog_content = "?",
  ui_story_5089_50890601_78_dialog_content = "You don't have to tell me any of these things, especially if you don't want to.",
  ui_story_5089_50890601_79_dialog_content = "It has nothing to do with whether or not I want to tell you.",
  ui_story_5089_50890601_80_dialog_content = "I still don't understand the meaning of Lady Xuan Ji's words, but I know that every word she says carries its own significance.",
  ui_story_5089_50890601_81_dialog_content = "And since she mentioned my origins, I thought it was only proper to share them with you.",
  ui_story_5089_50890601_82_dialog_content = "The details of my life are trivial at best, but I thank you all for listening to them, PlayerName.",
  ui_story_5089_50890601_83_dialog_content = "... How could you possibly say that about yourself, Jiu?",
  ui_story_5089_50890601_84_dialog_content = "If you really didn't care...",
  ui_story_5089_50890601_85_dialog_content = "You wouldn't have remembered something as small as that bowl of spilled porridge on the ground!",
  ui_story_5089_50890601_86_dialog_content = "Are you angry, PlayerName?",
  ui_story_5089_50890601_87_dialog_content = "I'm surprised you could tell!",
  ui_story_5089_50890601_88_dialog_content = "Yes, of course I'm angry!",
  ui_story_5089_50890601_89_dialog_content = "Forgive me... I know it isn't the most pleasant story to hear.",
  ui_story_5089_50890601_90_dialog_content = "But if it's any consolation... My vengeance came soon afterward.",
  ui_story_5089_50890601_91_dialog_content = "After finding my parents like that, I took the dagger from one of the dead officers and hunted the prisoner for a day and a night.",
  ui_story_5089_50890601_92_dialog_content = "To my surprise, he traveled straight to the mine's labor camp and attempted to assassinate our lord, the man who would later become the King of Ye.",
  ui_story_5089_50890601_93_dialog_content = "By the time I had caught up with him, justice had already been served.",
  ui_story_5089_50890601_94_dialog_content = "His Highness asked my reasons for being there. After learning about my family's demise, he took me in and bestowed upon me the name Jiu.",
  ui_story_5089_50890601_95_dialog_content = "Not only did he avenge me, but he also allowed me to settle in his mansion. There, he taught me to read and write, and strengthened me through martial arts training.",
  ui_story_5089_50890601_96_dialog_content = "For this reason, I owe him my life and will do anything to repay his kindness.",
  ui_story_5089_50890601_97_dialog_content = "Beyond this debt of gratitude, I have no other reason to wield my sword... Or to keep living, for that matter.",
  ui_story_5089_50890601_98_dialog_content = "That's not what I'm talking about, Jiu.",
  ui_story_5089_50890601_99_dialog_content = "All you do is talk about revenge and gratitude.",
  ui_story_5089_50890601_100_dialog_content = "But what about your own feelings? What about the things that you want to do?",
  ui_story_5089_50890601_101_dialog_content = "Whether it was taking a hit for me before, nonchalantly suggesting to storm the prison, or thinking that your feelings don't matter... It's always the same with you.",
  ui_story_5089_50890601_102_dialog_content = "Why do you keep taking your sacrifices for granted, as if they don't matter?!",
  ui_story_5089_50890601_103_dialog_content = "You may be strong but still made of flesh and blood. You can get hurt, feel pain, be sad, and if you're not careful, you could actually die.",
  ui_story_5089_50890601_104_dialog_content = "It's not that I don't recognize that. It's just that for the sake of my missions...",
  ui_story_5089_50890601_105_dialog_content = "Alright, I get it. I think I'm starting to understand how to talk to you.",
  ui_story_5089_50890601_106_dialog_content = "And now that I've personally experienced how stubborn you can be, I feel like I owe Dantang an apology too.",
  ui_story_5089_50890601_107_dialog_content = "Let me put this in a way you can understand.",
  ui_story_5089_50890601_108_dialog_content = "?",
  ui_story_5089_50890601_109_dialog_content = "Frankly, your recklessness and willingness to sacrifice yourself always scare me.",
  ui_story_5089_50890601_110_dialog_content = "The Caelestites are a kind and peaceful race. We don't want to see bloodshed, and we especially don't want to see our friends get hurt.",
  ui_story_5089_50890601_111_dialog_content = "I want to return you to Dantang safely and soundly.",
  ui_story_5089_50890601_112_dialog_content = "So if orders are the only things you'll listen to, then I have an order just for you.",
  ui_story_5089_50890601_113_dialog_content = "\"No matter your situation, always cherish your life and protect yourself first.\"",
  ui_story_5089_50890601_114_dialog_content = "I...",
  ui_story_5089_50890601_115_dialog_content = "I'm not looking for any excuses, either. A simple yes will do just fine.",
  ui_story_5089_50890601_116_dialog_content = "Yes. I will remember your orders.",
  ui_story_5089_50890601_117_dialog_content = "But is there a time limit for these orders?",
  ui_story_5089_50890601_118_dialog_content = "You really don't get it, do you?",
  ui_story_5089_50890601_119_dialog_content = "Never mind. If you really need a time limit, then...",
  ui_story_5089_50890601_120_dialog_content = "Your orders won't end until the day you can swing your blade without doing so out of gratitude or vengeance. How about that?",
  ui_story_5089_50890601_121_dialog_content = "Uh...",
  ui_story_5089_50890601_122_dialog_content = "I'm not changing any part of your orders, if that's what you're about to ask.",
  ui_story_5089_50890601_123_dialog_content = "No, it's just that my master once told me the same thing.",
  ui_story_5089_50890601_124_dialog_content = "Your \"master\"?",
  ui_story_5089_50890601_125_dialog_content = "The greatest swordsman in the world and the man who taught me the way of the blade.",
  ui_story_5089_50890601_126_dialog_content = "Though he refused to accept someone as stubborn as myself as a formal disciple, he still taught me a great many things.",
  ui_story_5089_50890601_127_dialog_content = "But there was one thing he would not teach me: the Thundering Edge, a technique rumored to have the power to part mountains and seas.",
  ui_story_5089_50890601_128_dialog_content = "He claimed it wasn't a real sword technique, and so he couldn't teach it to me.",
  ui_story_5089_50890601_129_dialog_content = "Only when I can wield my sword for neither vengeance nor gratitude will I be worthy of learning it.",
  ui_story_5089_50890601_130_dialog_content = "That's weird. I do not see any other clues around here—Urk!",
  ui_story_5089_50890601_131_dialog_content = "Forgive me, PlayerName, but we're not alone.",
  ui_story_5089_50890601_132_dialog_content = "Mmf... Is that Zhui Hu?!",
  ui_story_5089_50890601_133_dialog_content = "What could she be doing here...? Come on Jiu, let's follow her!",
  ui_story_5089_50890601_134_dialog_content = "She went into that workshop, right? Let's go—",
  ui_story_5089_50890601_135_dialog_content = "Creak—",
  ui_story_5089_50890601_136_dialog_content = "Careful, Jiu! There are clockwork beasts guarding the workshop!",
  ui_story_5089_50890602_1_dialog_content = "Why would an abandoned workshop need this much protection?",
  ui_story_5089_50890602_2_dialog_content = "There are plenty of signs of recent activity. Not only that, but Zhui Hu also showed up here.",
  ui_story_5089_50890602_3_dialog_content = "If I had to guess, this is probably a Fate Rider stronghold.",
  ui_story_5089_50890602_4_dialog_content = "Then we'll need to be extremely careful. Aside from its enormous and maze-like interior, part of the workshop is also located deep underground.",
  ui_story_5089_50890602_5_dialog_content = "Once inside, we can't afford to lose our way.",
  ui_story_5089_50890602_6_dialog_content = "Then we're lucky because I have lots of experience with buildings like this. Psychic abilities can be pretty handy for scouting ahead.",
  ui_story_5089_50890602_7_dialog_content = "Psychic Scan—",
  ui_story_5089_50890602_8_dialog_content = "Whoa! There are so many weapons stored in here!",
  ui_story_5089_50890602_9_dialog_content = "What do the Fate Riders plan to do with them? Huh?",
  ui_story_5089_50890602_10_dialog_content = "It looks like someone's locked in that room over there.",
  ui_story_5089_50890602_11_dialog_content = "!",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>The moment they set foot in the room, a foul stench assaults their senses.</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>A huddled figure trembles in the corner of the room, desperately shrinking away from them.</color>",
  ui_story_5089_50890602_14_dialog_content = "Just look at this place. They must've been keeping him here for a long time now.",
  ui_story_5089_50890602_15_dialog_content = "Who are you? What are you doing here?",
  ui_story_5089_50890602_16_dialog_content = "Ahh—Ahh—",
  ui_story_5089_50890602_17_dialog_content = "Urgh... Haha... Woooo—",
  ui_story_5089_50890602_18_dialog_content = "Looks like the poor guy is already too far gone. We won't get anything out of him anymore.",
  ui_story_5089_50890602_19_dialog_content = "Let's just keep investigating the workshop. Maybe we'll find a way to save him...",
  ui_story_5089_50890602_20_dialog_content = "Jiu? Why are you still standing there?",
  ui_story_5089_50890602_21_dialog_content = "No... This can't be... Why are you...",
  ui_story_5089_50890602_22_dialog_content = "Why are you here, my king?!",
  ui_story_5089_50890602_23_dialog_content = "Wait... That's the King of Ye?!",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>The next day</color>",
  ui_story_5089_50890700_2_dialog_content = "... Princess?",
  ui_story_5089_50890700_3_dialog_content = "Hmm? Yes?",
  ui_story_5089_50890700_4_dialog_content = "You asked me to inquire about those two princesses, didn't you? Fang Ze and Shao Qin?",
  ui_story_5089_50890700_5_dialog_content = "Ah, yes. Tell me, what have you learned about my sisters?",
  ui_story_5089_50890700_6_dialog_content = "It seems the king sent them to venerate the royal ancestors some time ago. As such, they will be staying in one of the imperial villas instead of returning to Jingliang City.",
  ui_story_5089_50890700_7_dialog_content = "I should've known...",
  ui_story_5089_50890700_8_dialog_content = "Have you been standing in a daze here the entire time? You've hardly touched your breakfast... Letting all of these delectable dishes go cold is such a waste.",
  ui_story_5089_50890700_9_dialog_content = "Forgive me, but I don't have much of an appetite.",
  ui_story_5089_50890700_10_dialog_content = "No matter how great our woes may be, neglecting our bodies will solve nothing. Wouldn't you agree?",
  ui_story_5089_50890700_11_dialog_content = "And besides, worrying won't help you now that we're trapped in the palace. All we can do is place our hopes on PlayerName and Miss Jiu.",
  ui_story_5089_50890700_12_dialog_content = "Your maid told us that our friends are doing fine, right?",
  ui_story_5089_50890700_13_dialog_content = "Or are you saying you don't believe in them?",
  ui_story_5089_50890700_14_dialog_content = "Of course I believe in them. You, on the other hand...",
  ui_story_5089_50890700_15_dialog_content = "I expected you to run away at your earliest convenience, and yet here you are.",
  ui_story_5089_50890700_16_dialog_content = "Come now, why would I ever choose to leave? The palace offers me plenty of food and a warm place to sleep. If anything, these are some of the best days of my life!",
  ui_story_5089_50890700_17_dialog_content = "I couldn't bear parting with such a wonderful life, so I performed a divination to see how much longer I could stay here. Can you guess what I saw, Your Highness?",
  ui_story_5089_50890700_18_dialog_content = "My divination revealed that you still need me here.",
  ui_story_5089_50890700_19_dialog_content = "Having you impersonate Jiu is already asking too much. How could I possibly impose on you any further?",
  ui_story_5089_50890700_20_dialog_content = "Once this matter is settled, I still have to offer you a fitting reward—",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>Boom!!</color>",
  ui_story_5089_50890700_22_dialog_content = "Wh-What was that?!",
  ui_story_5089_50890700_23_dialog_content = "Your Highness! An intruder has forced their way into the palace! Please hurry to the—Nngh!",
  ui_story_5089_50890700_24_dialog_content = "Why did you knock that poor man unconscious, Tianxian?",
  ui_story_5089_50890700_25_dialog_content = "To show you that I still have much to offer, of course!",
  ui_story_5089_50890700_26_dialog_content = "Ah— Ahhh—",
  ui_story_5089_50890700_27_dialog_content = "*yawn* Ugh, morning already?",
  ui_story_5089_50890700_28_dialog_content = "I was too scared to sleep last night...",
  ui_story_5089_50890700_29_dialog_content = "Ahh—",
  ui_story_5089_50890700_30_dialog_content = "*sigh* We already took a huge risk by bringing you to a bunch of different doctors in the middle of the night.",
  ui_story_5089_50890700_31_dialog_content = "But they all said the same thing: that your condition was caused by poisoning, and that the poison has already seeped into your bones. According to them, you're beyond saving now.",
  ui_story_5089_50890700_32_dialog_content = "Awoo, awoooo—",
  ui_story_5089_50890700_33_dialog_content = "Are you really the King of Ye himself? If so...",
  ui_story_5089_50890700_34_dialog_content = "\"Hopeless\" doesn't even begin to describe the situation we're in now.",
  ui_story_5089_50890700_35_dialog_content = "Not only that, but something that Jiu said yesterday gave me a really bad feeling.",
  ui_story_5089_50890700_36_dialog_content = "So this clinic can't do anything for him either, huh?",
  ui_story_5089_50890700_37_dialog_content = "Don't give up yet, Jiu. Maybe we can get one of these doctors to write a letter to Liqing?",
  ui_story_5089_50890700_38_dialog_content = "We could even try finding that \"Bucunzi\" guy Dantang mentioned before—",
  ui_story_5089_50890700_39_dialog_content = "PlayerName.",
  ui_story_5089_50890700_40_dialog_content = "If the person on the throne isn't the true King of Ye, then what will become of Her Highness?",
  ui_story_5089_50890700_41_dialog_content = "Well...",
  ui_story_5089_50890700_42_dialog_content = "I'm deeply indebted to not just the king, but to her as well. In our time together, Her Highness has shown me nothing but kindness.",
  ui_story_5089_50890700_43_dialog_content = "Now that the princess has relieved me of my duties as her bodyguard, I may not have the right to meddle in her affairs.",
  ui_story_5089_50890700_44_dialog_content = "But if I can no longer protect her...",
  ui_story_5089_50890700_45_dialog_content = "Then I'm entrusting Her Highness' safety to you.",
  ui_story_5089_50890700_46_dialog_content = "I'm sorry.",
  ui_story_5089_50890700_47_dialog_content = "Wait a minute... Where the heck is she, anyway?!",
  ui_story_5089_50890700_48_dialog_content = "Grrr... I knew it!",
  ui_story_5089_50890700_49_dialog_content = "Good thing I planned for something like this to happen...",
  ui_story_5089_50890700_50_dialog_content = "Uncle Li! I'm sorry, but could I please ask you to take care of this man?",
  ui_story_5089_50890700_51_dialog_content = "Eh? Of course, my young friend, but where are you off to in such a hurry?",
  ui_story_5089_50890700_52_dialog_content = "To Jingliang City!",
  ui_story_5089_50890700_53_dialog_content = "Ahh—",
  ui_story_5089_50890700_54_dialog_content = "My lord, an assassin has breached the palace gates and our guards are no match for her. She's approaching the main hall as we speak!",
  ui_story_5089_50890700_55_dialog_content = "It must be Frost Blade, Your Highness.",
  ui_story_5089_50890700_56_dialog_content = "Shall we intercept her?",
  ui_story_5089_50890700_57_dialog_content = "No need. If she seeks an audience with the king, then I shall await her right here.",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50890700_59_dialog_content = "Halt! You stand before the mighty King of Ye, now step no further!",
  ui_story_5089_50890700_60_dialog_content = "Stand aside.",
  ui_story_5089_50890700_61_dialog_content = "Eurgh—",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>Jiu strides into the main hall and locks eyes with the man upon the throne.</color>",
  ui_story_5089_50890700_63_dialog_content = "It seems your reputation as the king's sharpest blade is well-earned.",
  ui_story_5089_50890700_64_dialog_content = "No warrior in the entire palace could ever hope to rival you.",
  ui_story_5089_50890700_65_dialog_content = "Drop the act!",
  ui_story_5089_50890700_66_dialog_content = "I've already met with the real king, you impostor—",
  ui_story_5089_50890700_67_dialog_content = "Now remove yourself from his throne!",
  ui_story_5089_50890700_68_dialog_content = "Ah, so you've seen that addled fool for yourself.",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>Their swords clash, filling the hall with their powerful reverberation.</color>",
  ui_story_5089_50890700_71_dialog_content = "How dare you insult the king so callously!",
  ui_story_5089_50890700_72_dialog_content = "Heh, I admire your ferocity.",
  ui_story_5089_50890700_73_dialog_content = "You truly are the most powerful swordfighter under my command.",
  ui_story_5089_50890700_74_dialog_content = "Why you...!",
  ui_story_5089_50890700_75_dialog_content = "Guards! Greet your superior with a friendly test of strength!",
  ui_story_5089_50890700_76_dialog_content = "Yes, Your Highness!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>The king's shadow guards approach from both sides, their sharp metal wires cutting through the air.</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>Just as Jiu is about to dodge, she notices a lapse in the false king's defenses and strikes.</color>",
  ui_story_5089_50890700_79_dialog_content = "—!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>A metal wire pierces her lower leg, but her attack does not falter for even a moment. She thrusts her blade straight at the false king's heart with her full strength!</color>",
  ui_story_5089_50890700_81_dialog_content = "Ever since you were a child, you've always had this terrible habit.",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>The tip of her blade presses into the king's light armor and rebounds slightly.</color>",
  ui_story_5089_50890700_84_dialog_content = "Damn you...",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>Jiu immediately recovers and prepares to strike once again.</color>",
  ui_story_5089_50890700_86_dialog_content = "Your blade is sharp, but honing an edge to its limit comes at the cost of the blade's durability.",
  ui_story_5089_50890700_87_dialog_content = "Have you forgotten the reason why I gave you the name \"Jiu\"?",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>—Ten years ago</color>",
  ui_story_5089_50890700_90_dialog_content = "So you chased your family's murderer here, barefoot and alone, without eating or drinking anything for an entire day?",
  ui_story_5089_50890700_91_dialog_content = "Hahaha, I never expected someone so young to be so determined.",
  ui_story_5089_50890700_92_dialog_content = "But just look at you now: starving, covered in blisters, and hardly able to stay on your feet.",
  ui_story_5089_50890700_93_dialog_content = "Even if you caught up to your enemy in this condition, the only victory you could hope for is one in which both of you die.",
  ui_story_5089_50890700_94_dialog_content = "... But that didn't bother you, did it? After all, what else could you do with your life besides sacrifice it in the name of vengeance?",
  ui_story_5089_50890700_95_dialog_content = "But now that I've carried out your vengeance, it's only fitting that your life belongs to me now.",
  ui_story_5089_50890700_96_dialog_content = "\"Jiu-mei,\" was it? A name meaning \"the ninth daughter\" is hardly worth keeping.",
  ui_story_5089_50890700_97_dialog_content = "From this day forth, you will be known simply as \"Jiu.\"",
  ui_story_5089_50890700_98_dialog_content = "A name that refers to a precious stone of the purest black. It's as beautiful as jade, but far stronger.",
  ui_story_5089_50890700_99_dialog_content = "Under my command, you will hone your edge and become my sharpest blade, so long as you do not allow yourself to become brittle.",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>Jiu momentarily loses focus, and is immediately pinned to the ground by a network of countless metal wires.</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>Her mask falls to the ground, but she continues to glower menacingly at the false king.</color>",
  ui_story_5089_50890700_102_dialog_content = "Who... Who are you?",
  ui_story_5089_50890700_103_dialog_content = "Didn't they say someone infiltrated the palace? Why are there still so many guards watching this place?",
  ui_story_5089_50890700_104_dialog_content = "When you said to run away just now, I thought it was because you had some sort of brilliant plan.",
  ui_story_5089_50890700_105_dialog_content = "Improvising is a perfectly acceptable plan of action, given our circumstances.",
  ui_story_5089_50890700_106_dialog_content = "I understand that you place very little faith in my divination, but I believe in it wholeheartedly.",
  ui_story_5089_50890700_107_dialog_content = "The ominous fortune that PlayerName drew earlier perfectly matches our current situation.",
  ui_story_5089_50890700_108_dialog_content = "However, if my calculations are correct, we cannot rely entirely on PlayerName and Miss Jiu to solve this predicament.",
  ui_story_5089_50890700_109_dialog_content = "What are you trying to say?",
  ui_story_5089_50890700_110_dialog_content = "It's simple: while I distract the soldiers, you'll seize the opportunity to escape from the palace.",
  ui_story_5089_50890700_111_dialog_content = "As for what comes next, we'll just have to improvise!",
  ui_story_5089_50890700_112_dialog_content = "Wait, Tianxian!",
  ui_story_5089_50890700_113_dialog_content = "Who goes there?!",
  ui_story_5089_50890700_114_dialog_content = "After them!",
  ui_story_5089_50890700_115_dialog_content = "I'll never understand that man.",
  ui_story_5089_50890700_116_dialog_content = "But it seems I don't have a choice now—",
  ui_story_5089_50890700_117_dialog_content = "Where are you going, Your Highness?",
  ui_story_5089_50890700_118_dialog_content = "...",
  ui_story_5089_50890700_119_dialog_content = "Xuan Ji, the soldiers—",
  ui_story_5089_50890700_120_dialog_content = "Quiet down, I'm busy here.",
  ui_story_5089_50890700_121_dialog_content = "But there's no time left! Why are you still fumbling around with those tiles?",
  ui_story_5089_50890700_122_dialog_content = "These are no ordinary tiles! They're ingenious devices that I've been painstakingly crafting for several days now.",
  ui_story_5089_50890700_123_dialog_content = "You've gotten much wiser, but you still have a lot to learn when it comes to cunning and guile.",
  ui_story_5089_50890700_124_dialog_content = "What's that supposed to mean?",
  ui_story_5089_50890700_125_dialog_content = "What I mean is that this may look like an ordinary prison cell to you.",
  ui_story_5089_50890700_126_dialog_content = "But in the hands of a true artisan, anything can be modified into a device or mechanism: stools, tables, roof beams, and even the ground beneath your feet.",
  ui_story_5089_50890700_127_dialog_content = "Now feast your eyes on my latest invention, which was inspired by our favorite Caelestite and made using simple household items: the Lumina Deflector Tile!",
  ui_story_5089_50890700_128_dialog_content = "... You're joking, right? So what exactly does it do?",
  ui_story_5089_50890700_129_dialog_content = "This fine piece of equipment is capable of redirecting any incoming light or Lumina to a desired location.",
  ui_story_5089_50890700_130_dialog_content = "And how exactly is that supposed to help us?",
  ui_story_5089_50890700_131_dialog_content = "We'll find out soon enough!",
  ui_story_5089_50890700_132_dialog_content = "Ten years ago, a high-ranking official, exhausted by the power struggles within the royal court, fell from grace and became a prisoner. He was sentenced to hard labor in the mines until his death.",
  ui_story_5089_50890700_133_dialog_content = "Fate, however, had other plans for him. The officers escorting him to the labor camp were indolent, and rather than finish the journey, they decided to take up lodging at a nearby family's home.",
  ui_story_5089_50890700_134_dialog_content = "They were nothing more than ordinary citizens, which made it easy for him to ambush them and make his escape.",
  ui_story_5089_50890700_135_dialog_content = "But as he fled the courtyard, he encountered his captors as they were trying to take advantage of the family's young daughter.",
  ui_story_5089_50890700_136_dialog_content = "And so he killed them without a second thought, and continued along his original route to the labor camp.",
  ui_story_5089_50890700_137_dialog_content = "The prince who was in charge of the labor camp at the time was a good man, but a bumbling oaf nonetheless. With just a single dose of a certain medicine, his mind was completely lost.",
  ui_story_5089_50890700_138_dialog_content = "And so, after donning a slight disguise, the prisoner swapped places with the prince.",
  ui_story_5089_50890700_139_dialog_content = "The men in his presence were so devoid of loyalty, that they never realized that another man had quietly replaced their master.",
  ui_story_5089_50890700_140_dialog_content = "Coincidentally, it was at this moment that the young daughter arrived, seeking vengeance for her fallen family.",
  ui_story_5089_50890700_141_dialog_content = "It was then that the prisoner realized that his heavy-handed escape resulted in their deaths.",
  ui_story_5089_50890700_142_dialog_content = "And so he took the girl in, and forged her into a loyal and faithful blade.",
  ui_story_5089_50890700_143_dialog_content = "I-It was you all along—!",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>Jiu's eyes turn red as she strains to lift her body. The wire net pinning her down emits a sharp groan, as if about to break.</color>",
  ui_story_5089_50890700_145_dialog_content = "The time has finally come for me to reveal the truth.",
  ui_story_5089_50890700_146_dialog_content = "Now tell me, do you still intend to avenge the death of your family?",
  ui_story_5089_50890700_147_dialog_content = "Or will you express gratitude to me for taking you in and raising you for all these years?",
  ui_story_5089_50890700_148_dialog_content = "I...",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>For the first time, Jiu's blade trembles in her hand.</color>",
  ui_story_5089_50890700_150_dialog_content = "What have you been living for all this time, Jiu? What is your purpose?",
  ui_story_5089_50890700_151_dialog_content = "Hraaagh—!",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>A streak of light flashes by.</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>The metal wires snap and go flying in every direction. Amid the falling debris, Jiu unleashes her ultimate attack.</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>She swings her Lumina-charged blade, and the resulting shockwave cleaves the palace in two, leaving deep trenches in the stone floor.</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>The King of Ye, however, easily sidesteps the attack and emerges unscathed.</color>",
  ui_story_5089_50890700_157_dialog_content = "Are you truly so doubtful that you can't even hold your sword steady?",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>Wham—</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>The king strikes Jiu's sword out of her hand and into a corner of the room.</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>Moments ago.</color>",
  ui_story_5089_50890700_161_dialog_content = "Your Highness, if you insist on leaving, we'll have no choice but to forcibly detain you.",
  ui_story_5089_50890700_162_dialog_content = "I never thought I'd see the day I would have to fight my palace guards in Ye Kingdom.",
  ui_story_5089_50890700_163_dialog_content = "Unfortunately for you, retreat is no longer an option for me.",
  ui_story_5089_50890700_164_dialog_content = "I still have someone waiting for me out there.",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>Suddenly, the nearby main hall is ripped apart by a powerful surge of Lumina.</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>Immediately afterward, a flash of light fills the room as the wave of Lumina heads directly toward them!</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>The palace tower is split down the middle, creating a rift between the royal guards and Dantang.</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>Another sudden flash of light illuminates the path out of the palace.</color>",
  ui_story_5089_50890700_171_dialog_content = "That direction... Ministress Armilla?",
  ui_story_5089_50890700_172_dialog_content = "I had a feeling she would never sit idly in her jail cell.",
  ui_story_5089_50890700_173_dialog_content = "So you think I should escape from the palace as well?",
  ui_story_5089_50890700_174_dialog_content = "Your Highness.",
  ui_story_5089_50890700_175_dialog_content = "What is it?",
  ui_story_5089_50890700_176_dialog_content = "Forgive us, but the Princess has escaped from the palace.",
  ui_story_5089_50890700_177_dialog_content = "The status of the person who entered the palace with the princess is also unknown, as are his whereabouts.",
  ui_story_5089_50890700_178_dialog_content = "Our guards claim to have seen him diving into a patch of bushes, but when they went to investigate, all they found was a sugar figurine.",
  ui_story_5089_50890700_179_dialog_content = "Also...",
  ui_story_5089_50890700_180_dialog_content = "What else? Speak already.",
  ui_story_5089_50890700_181_dialog_content = "It seems \"they\" are planning to make their move soon.",
  ui_story_5089_50890700_182_dialog_content = "They insist that we deliver the weapons within the next three days.",
  ui_story_5089_50890700_183_dialog_content = "However, the workshop claims to lack the capacity to fill its massive order in such a short amount of time. The Ji Kingdom is also urging us to complete their previous transaction...",
  ui_story_5089_50890700_184_dialog_content = "Understood.",
  ui_story_5089_50890700_185_dialog_content = "We'll discuss this later.",
  ui_story_5089_50890700_186_dialog_content = "For now, restrain your former leader until she regains her composure.",
  ui_story_5089_50890700_187_dialog_content = "Yes, Your Highness.",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>The shadow guard throws Jiu into an empty room and leaves.</color>",
  ui_story_5089_50890700_190_dialog_content = "Well, if it isn't Miss Jiu!",
  ui_story_5089_50890700_191_dialog_content = "Have you come to keep me company?",
  ui_story_5089_50890700_192_dialog_content = "...",
  ui_story_5089_50890802_1_dialog_content = "Alert every guard in the city! The princess has been kidnapped!",
  ui_story_5089_50890802_2_dialog_content = "Search every corner of the city! Report any suspicious characters immediately!",
  ui_story_5089_50890802_3_dialog_content = "Understood!",
  ui_story_5089_50890802_4_dialog_content = "So many guards... It feels like the entire atmosphere of Jingliang City suddenly changed.",
  ui_story_5089_50890802_5_dialog_content = "And something tells me I'm one of the \"suspicious characters\" they're looking for.",
  ui_story_5089_50890802_6_dialog_content = "Who's there? Show yourself!",
  ui_story_5089_50890802_7_dialog_content = "Uh-oh—Urk! L-Let go of me...!",
  ui_story_5089_50890802_8_dialog_content = "Shh, it's only me.",
  ui_story_5089_50890802_9_dialog_content = "Dantang?!",
  ui_story_5089_50890802_10_dialog_content = "Yes, now follow me.",
  ui_story_5089_50890802_11_dialog_content = "What is this place?",
  ui_story_5089_50890802_12_dialog_content = "It's a safe room prepared by the armed escorts we hired to return the crown prince's gold.",
  ui_story_5089_50890802_13_dialog_content = "Since they often work with the criminal underworld, they naturally have a need for spaces like this.",
  ui_story_5089_50890802_14_dialog_content = "And since we placed such an expensive order, it's only normal that they would provide us with a few additional amenities.",
  ui_story_5089_50890802_15_dialog_content = "Were you planning this far ahead all along?!",
  ui_story_5089_50890802_16_dialog_content = "So there was a reason for leaving us behind at the inn!",
  ui_story_5089_50890802_17_dialog_content = "I wasn't entirely sure of the truth back then. All I had were Ministress Armilla's vague hints to guide me.",
  ui_story_5089_50890802_18_dialog_content = "Though the chances were slim, the mere possibility of foul play posed a great threat to the entire Ye Kingdom.",
  ui_story_5089_50890802_19_dialog_content = "Not only that... But the price of gain is far too high.",
  ui_story_5089_50890802_20_dialog_content = "Uncle Li also informed us that Ji Kingdom's merchants have been buying food despite the high prices lately.",
  ui_story_5089_50890802_21_dialog_content = "... The turmoil at the beginning of spring was also due in part to Ye Kingdom's reluctance to deliver cannons to the coast.",
  ui_story_5089_50890802_22_dialog_content = "The Ji Kingdom would never endure these losses without obtaining something in return.",
  ui_story_5089_50890802_23_dialog_content = "Are you saying... that Ji Kingdom is deliberately raising the price of grains?",
  ui_story_5089_50890802_24_dialog_content = "The common citizen is hurt the most when prices are raised like this. When that happens, they're more likely to leave and look for other ways to survive.",
  ui_story_5089_50890802_25_dialog_content = "In recent years, Ye Kingdom has established countless workshops of various sizes. In doing so, they have attracted many of the kingdom's young and healthy citizens, forcing them to abandon their fields in hopes of better-paying work.",
  ui_story_5089_50890802_26_dialog_content = "Our grain stores were already insufficient to handle a population shift of this magnitude.",
  ui_story_5089_50890802_27_dialog_content = "The rising cost of grain has also increased costs for other sectors. In short, the kingdom's economy is caught in a vicious cycle.",
  ui_story_5089_50890802_28_dialog_content = "The Ji Kingdom, however, is not short on funds at all. Should they decide to challenge us to a war of attrition, I fear we stand no chance of winning.",
  ui_story_5089_50890802_29_dialog_content = "However, I'm not convinced that Ji Kingdom wishes to sever ties completely. If anything, they most likely wish to capitalize on our weakness to continue exploiting us.",
  ui_story_5089_50890802_30_dialog_content = "... Their timing couldn't be worse.",
  ui_story_5089_50890802_31_dialog_content = "Their timing?",
  ui_story_5089_50890802_32_dialog_content = "Tell me, PlayerName: what exactly do you consider a \"nation\" to be?",
  ui_story_5089_50890802_33_dialog_content = "Huh? Well... I'd say it's a group of people who come together in search of a better life.",
  ui_story_5089_50890802_34_dialog_content = "Aside from furthering their interests, they also work hard for everyone else in the group.",
  ui_story_5089_50890802_35_dialog_content = "Is that how the people of Eraveil define a nation? I must say, it sounds like quite a utopian existence.",
  ui_story_5089_50890802_36_dialog_content = "A-Am I wrong?",
  ui_story_5089_50890802_37_dialog_content = "Not at all, PlayerName.",
  ui_story_5089_50890802_38_dialog_content = "Although every vassal kingdom in Longzhou falls under the Zhao Empire's rule, they each have their own views on what it means to be a nation.",
  ui_story_5089_50890802_39_dialog_content = "For instance, Ji Kingdom believes governing a country is no different from running a business. The Ye Kingdom, on the other hand, sees things differently.",
  ui_story_5089_50890802_40_dialog_content = "In our eyes, a nation is a massive, formless mechanism. Day and night, it operates without rest.",
  ui_story_5089_50890802_41_dialog_content = "You are the pivot, I am the cog, the artisan is the oil, and the masses are its driving force.",
  ui_story_5089_50890802_42_dialog_content = "So long as every piece of the machine fulfills its role dutifully and normally, our nation will naturally prosper.",
  ui_story_5089_50890802_43_dialog_content = "So what about now?",
  ui_story_5089_50890802_44_dialog_content = "Our king is an imposter, conflicting interests mark his court, the artisans are not free, and the masses are on the verge of even greater suffering. This is the current state of our nation.",
  ui_story_5089_50890802_45_dialog_content = "Rather than trying to resolve each of these problems individually, I decided to cut to the heart of the conflict.",
  ui_story_5089_50890802_46_dialog_content = "And so I voluntarily returned to the palace, hoping to find a flaw at the core of our nation's suffering.",
  ui_story_5089_50890802_47_dialog_content = "Doing so also allowed you and Jiu to continue searching for evidence without being pursued by the king's soldiers.",
  ui_story_5089_50890802_48_dialog_content = "Frankly speaking, I knew that Jiu would never agree to this, which left me no choice but to resort to deception. Please don't hold it against me, PlayerName.",
  ui_story_5089_50890802_49_dialog_content = "I don't blame you for it, Dantang. After our time together, I learned just how stubborn she can be too.",
  ui_story_5089_50890802_50_dialog_content = "Which is why I had to do something similar with her...",
  ui_story_5089_50890802_51_dialog_content = "Pardon the interruption, young masters, but your shipment has safely arrived. May I trouble you for a signature?",
  ui_story_5089_50890802_52_dialog_content = "Yeah, sure. Thanks a lot for your help.",
  ui_story_5089_50890802_53_dialog_content = "Also, Your Highness, we've progressed on the matter since our last conversation.",
  ui_story_5089_50890802_54_dialog_content = "My men outside of the city have informed me that there are indeed Huolong Carriers moving in that direction, and that they appear to be transporting a large amount of goods.",
  ui_story_5089_50890802_55_dialog_content = "Understood. Thank you for all of your help.",
  ui_story_5089_50890802_56_dialog_content = "Just doing our job. Farewell.",
  ui_story_5089_50890802_57_dialog_content = "Was he talking about the secret workshop?",
  ui_story_5089_50890802_58_dialog_content = "Indeed. During my time in the palace, I gathered a fair amount of information.",
  ui_story_5089_50890802_59_dialog_content = "The false king has been exploiting Ye Kingdom's resources in order to manufacture weapons for the Fate Riders.",
  ui_story_5089_50890802_60_dialog_content = "The Ji Kingdom has also been delaying the delivery of its coastal cannons. My suspicion is that they are also conspiring with the Fate Riders, who wish to claim those cannons for themselves.",
  ui_story_5089_50890802_61_dialog_content = "And just recently they once again increased the demand for firearms.",
  ui_story_5089_50890802_62_dialog_content = "They've insisted on the matter several times now, and have even threatened the false king if he fails to deliver.",
  ui_story_5089_50890802_63_dialog_content = "When you mentioned the existence of a hidden workshop, I immediately sent these men to investigate.",
  ui_story_5089_50890802_64_dialog_content = "However, I didn't expect them to take action so quickly...",
  ui_story_5089_50890802_65_dialog_content = "We can't just stand here and let the Fate Riders get their hands on all those weapons!",
  ui_story_5089_50890802_66_dialog_content = "I wholeheartedly agree with you.",
  ui_story_5089_50890802_67_dialog_content = "But given our current predicament, it's quite difficult for us to take action in any way.",
  ui_story_5089_50890802_68_dialog_content = "Even with your assistance, uncovering the truth was by no means simple. If only I could have prepared earlier...",
  ui_story_5089_50890802_69_dialog_content = "That doesn't look or sound like you at all, Dantang.",
  ui_story_5089_50890802_70_dialog_content = "PlayerName?",
  ui_story_5089_50890802_71_dialog_content = "The Dantang I know, would never doubt herself for challenging a situation like this, especially if destiny supposedly had a hand in it.",
  ui_story_5089_50890802_72_dialog_content = "The Dantang I know is brave, to the point that it's almost frightening.",
  ui_story_5089_50890802_73_dialog_content = "... You flatter me, my friend. But unfortunately, our predicament cannot be solved by bravery alone.",
  ui_story_5089_50890802_74_dialog_content = "But if we can bring enough chips to the bargaining table...",
  ui_story_5089_50890802_75_dialog_content = "That shouldn't be a problem.",
  ui_story_5089_50890802_76_dialog_content = "What?",
  ui_story_5089_50890802_77_dialog_content = "If you're worried about bargaining chips, we have plenty.",
  ui_story_5089_50890802_78_dialog_content = "For example... We have enough gold on our hands to buy an entire city.",
  ui_story_5089_50890802_79_dialog_content = "!",
  ui_story_5089_50890802_80_dialog_content = "But that was a gift from the crown prince to you, one that you were planning to return!",
  ui_story_5089_50890802_81_dialog_content = "Well, it wasn't easy for us to get here. It'd be a waste not to utilize everything at our disposal.",
  ui_story_5089_50890802_82_dialog_content = "But even with all this gold, trying to gather sufficient manpower in such a limited time—",
  ui_story_5089_50890802_83_dialog_content = "I have an idea for that too.",
  ui_story_5089_50890802_84_dialog_content = "I don't understand the intricacies of court politics, so I can't offer much of an opinion.",
  ui_story_5089_50890802_85_dialog_content = "But I think we can simplify things a little with this gold.",
  ui_story_5089_50890802_86_dialog_content = "After all, money is meant to be spent on things, right?",
  ui_story_5089_50890802_87_dialog_content = "Then... What exactly do you wish to purchase PlayerName?",
  ui_story_5089_50890802_88_dialog_content = "I'm guessing those guys have never driven a Huolong Carrier before, right?",
  ui_story_5089_50890802_89_dialog_content = "And with all the carriers moving to and from the secret workshop, it's unlikely that the nearby villagers haven't seen or heard anything. In other words, there's no way anyone would believe it was abandoned, at least not recently.",
  ui_story_5089_50890802_90_dialog_content = "And yet, somehow, it seems no one knew anything about it up until now.",
  ui_story_5089_50890802_91_dialog_content = "That can only mean that the workshop has been ensuring its secrecy by receiving smaller shipments over multiple deliveries.",
  ui_story_5089_50890802_92_dialog_content = "But now, because of the Fate Riders' massive order, they seem to be using multiple carriers to transport the necessary materials.",
  ui_story_5089_50890802_93_dialog_content = "The Artisan's Guild oversees the use of the Huolong Carriers.",
  ui_story_5089_50890802_94_dialog_content = "The association itself is comprised of officials from both of the major sects, as well as administrators appointed by the royal court. Together, they regulate the use of the Huolong Carriers.",
  ui_story_5089_50890802_95_dialog_content = "Even the king cannot bypass their protocols or use it freely.",
  ui_story_5089_50890802_96_dialog_content = "However, they don't closely monitor the people who rent the carriers.",
  ui_story_5089_50890802_97_dialog_content = "In other words, the Fate Riders probably had no trouble borrowing the rights to the carriers through one of those workshops, right?",
  ui_story_5089_50890802_98_dialog_content = "Are you saying you want to investigate every single workshop?",
  ui_story_5089_50890802_99_dialog_content = "No.",
  ui_story_5089_50890802_100_dialog_content = "There's no need for us to confront them directly. After all, the Fate Riders are the ones we're after.",
  ui_story_5089_50890802_101_dialog_content = "Now that I'm looking in from the outside, I think I'm starting to understand the \"momentum\" Xuan Ji was talking about.",
  ui_story_5089_50890802_102_dialog_content = "Dantang! The Artisan's Guild is only in charge of renting out the carriers, right?",
  ui_story_5089_50890802_103_dialog_content = "Yes, that's right.",
  ui_story_5089_50890802_104_dialog_content = "Then what I want to buy...",
  ui_story_5089_50890802_105_dialog_content = "Are the tracks themselves.",
  ui_story_5089_50890802_106_dialog_content = "... You are truly a genius, PlayerName!",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>Secret Workshop</color>",
  ui_story_5089_50890802_108_dialog_content = "What's the deal with these Huolong Carriers? Who gave you people permission to act on your own?!",
  ui_story_5089_50890802_109_dialog_content = "Watch your tone. I was just about to ask you the same question.",
  ui_story_5089_50890802_110_dialog_content = "You people never stop urging us to deliver the weapons, but what have you been doing all this time?",
  ui_story_5089_50890802_111_dialog_content = "If we can't produce enough of them on time, just send the batch meant for Ji Kingdom. That shouldn't be too difficult for you, right?",
  ui_story_5089_50890802_112_dialog_content = "... If we fail to fulfill Ji Kingdom's order, it may affect relations between our two nations.",
  ui_story_5089_50890802_113_dialog_content = "Ha, even a three-year-old wouldn't be this naive.",
  ui_story_5089_50890802_114_dialog_content = "We're all in league with the Fate Riders now. Do I really need to tell you whose orders to follow? The ties between the two kingdoms are no longer our concern.",
  ui_story_5089_50890802_115_dialog_content = "Unless... Don't tell me your so-called \"king\" fancies himself the true ruler of Ye Kingdom?",
  ui_story_5089_50890802_116_dialog_content = "Of course not.",
  ui_story_5089_50890802_117_dialog_content = "Good. I understand that he was once sentenced to death, but his allegiance to the Fate Riders is the only thing that has kept him alive as king to this day.",
  ui_story_5089_50890802_118_dialog_content = "If he dares to betray them, he'll lose everything just as quickly as he gained it.",
  ui_story_5089_50890802_119_dialog_content = "Then again, with the uprising nearly at hand, any chaos caused by the disobedience of the vassal states will also work in our favor.",
  ui_story_5089_50890802_120_dialog_content = "Surely you understand that much, right?",
  ui_story_5089_50890802_121_dialog_content = "... Of course.",
  ui_story_5089_50890802_122_dialog_content = "Good, now hurry and load up the goods.",
  ui_story_5089_50890802_123_dialog_content = "Lady Zhui Hu, we've encountered a problem.",
  ui_story_5089_50890802_124_dialog_content = "What now?",
  ui_story_5089_50890802_125_dialog_content = "It appears we cannot use the Huolong Carriers at the moment.",
  ui_story_5089_50890802_126_dialog_content = "What? Didn't we pay off the workshops to ensure exclusive use of the carriers?!",
  ui_story_5089_50890802_127_dialog_content = "Th-That's not the issue. It's just that...",
  ui_story_5089_50890802_128_dialog_content = "The road has been blocked.",
  ui_story_5089_50890802_129_dialog_content = "What?!",
  ui_story_5089_50890901_1_dialog_content = "Your generous contribution has made things much simpler, PlayerName.",
  ui_story_5089_50890901_2_dialog_content = "After temporarily renting the lands surrounding the tracks, I've asked the people to block the way leading to the secret workshop.",
  ui_story_5089_50890901_3_dialog_content = "We've effectively stopped the Fate Riders in their tracks.",
  ui_story_5089_50890901_4_dialog_content = "But it seems our blockade is starting to cause trouble for some of the traveling merchants—",
  ui_story_5089_50890901_5_dialog_content = "Please, friends! I'm only here to procure some grains. I've done nothing wrong!",
  ui_story_5089_50890901_6_dialog_content = "Won't you please let our caravan pass?",
  ui_story_5089_50890901_7_dialog_content = "You're from Ji Kingdom, aren't you?",
  ui_story_5089_50890901_8_dialog_content = "Why, yes, I am. Is that a problem? I can assure you that I have all of my business documents in order...",
  ui_story_5089_50890901_9_dialog_content = "(Dantang.)",
  ui_story_5089_50890901_10_dialog_content = "(Right.)",
  ui_story_5089_50890901_11_dialog_content = "Ahem, do you realize who you're speaking to right now?",
  ui_story_5089_50890901_12_dialog_content = "Er, no... I can't say that I do...",
  ui_story_5089_50890901_13_dialog_content = "This is PlayerName, Lord of Eraveil. He is a special envoy from the land of Astra and an honorable official personally appointed by the King of Ji.",
  ui_story_5089_50890901_14_dialog_content = "Blessed by the Dragon Maiden, he is a close ally to the Lin Guild, and the subject of the crown prince's earnest advances...",
  ui_story_5089_50890901_15_dialog_content = "(Alright already, you've made your point! You can tell he's already convinced by the look in his eyes, so just give it a rest!)",
  ui_story_5089_50890901_16_dialog_content = "Ah, yes, I remember now! To see you once more is the greatest honor I could ever hope for, my lord!",
  ui_story_5089_50890901_17_dialog_content = "Tell me, how may I be of service to you? I will do anything you ask of me, so long as it's within my power... Wait, you were the one who sealed the road, yes?",
  ui_story_5089_50890901_18_dialog_content = "Forgive me for my ignorance, my lord! Even if you were to banish me till the end of time, I would harbor no resentment!",
  ui_story_5089_50890901_19_dialog_content = "I-It's nothing that serious. I just have a business proposition for you, that's all.",
  ui_story_5089_50890901_20_dialog_content = "By all means, my lord! I will offer you the very best price for whatever you desire!",
  ui_story_5089_50890901_21_dialog_content = "How much gold do we have left, Dantang?",
  ui_story_5089_50890901_22_dialog_content = "After paying for the tracks, the land surrounding them, and the artisans' wages... We've only used a very small portion of our funds.",
  ui_story_5089_50890901_23_dialog_content = "Give him the rest, then.",
  ui_story_5089_50890901_24_dialog_content = "I'm sorry...?",
  ui_story_5089_50890901_25_dialog_content = "I want to use this gold to buy all of the food you've procured from Ye Kingdom.",
  ui_story_5089_50890901_26_dialog_content = "Ah, my lord... This presents quite a challenge, you know...",
  ui_story_5089_50890901_27_dialog_content = "I know you're working for the King of Ji.",
  ui_story_5089_50890901_28_dialog_content = "!",
  ui_story_5089_50890901_29_dialog_content = "You can tell him that we forced you to do it, if you have to. I'll take full responsibility for the whole thing.",
  ui_story_5089_50890901_30_dialog_content = "I see... I suppose I can make an exception for you, my lord.",
  ui_story_5089_50890901_31_dialog_content = "Good. And don't worry, I always keep my word.",
  ui_story_5089_50890901_32_dialog_content = "Phew, they finally left.",
  ui_story_5089_50890901_33_dialog_content = "Heheh.",
  ui_story_5089_50890901_34_dialog_content = "Yeah, yeah, go ahead and laugh. I'm sure my \"lordly\" acting must have been fun to watch...",
  ui_story_5089_50890901_35_dialog_content = "Not at all, PlayerName. Your performance was most captivating.",
  ui_story_5089_50890901_36_dialog_content = "Hmm?",
  ui_story_5089_50890901_37_dialog_content = "Those people over there...",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>Moments ago—</color>",
  ui_story_5089_50890901_39_dialog_content = "Knock, knock, knock.",
  ui_story_5089_50890901_40_dialog_content = "Huh? Who could it be at a time like this?",
  ui_story_5089_50890901_41_dialog_content = "...",
  ui_story_5089_50890901_42_dialog_content = "Sister Xuan Ji! Our brother from the Artisan's Guild says that the Caelestite is—",
  ui_story_5089_50890901_43_dialog_content = "Sigh, how many times do I have to tell you, Qian Ji? Stop referring to us as brothers and sisters while we're in the palace.",
  ui_story_5089_50890901_44_dialog_content = "Although we have no intention of taking sides, it's never a good idea to give them a reason to misunderstand us.",
  ui_story_5089_50890901_45_dialog_content = "It's what led to Master Houfeng's conviction last time, remember?",
  ui_story_5089_50890901_46_dialog_content = "Master Houfeng... You mean the inventor from ten years ago?",
  ui_story_5089_50890901_47_dialog_content = "From what I recall, he was a rogue artisan who refused to side with any faction, and instead tried to learn from every source imaginable.",
  ui_story_5089_50890901_48_dialog_content = "He was supposedly very talented, but also somewhat arrogant because of it. Even though both factions tried to coerce him into joining them, he always rejected them.",
  ui_story_5089_50890901_49_dialog_content = "And after he joined the court as an advisor, he was known for proposing many radical reform ideas.",
  ui_story_5089_50890901_50_dialog_content = "He proposed lifting the trade restrictions on clockwork creations and instituting court control over resources for all factions.",
  ui_story_5089_50890901_51_dialog_content = "His fervor for serving his country was undeniable, but his actions were too extreme and failed to consider reality.",
  ui_story_5089_50890901_52_dialog_content = "You can't blame anyone else if you end up like him, Lady Xuan Ji. His example should not be followed.",
  ui_story_5089_50890901_53_dialog_content = "I know, but I'm a perfectly law-abiding citizen of the kingdom. Don't you remember how obedient I was when the king decided to put me behind bars?",
  ui_story_5089_50890901_54_dialog_content = "It seems you've forgotten the reason you were locked up in the first place.",
  ui_story_5089_50890901_55_dialog_content = "Whatever the reason, I'm sure it had nothing to do with me tampering with the arcane blasters that I personally helped design.",
  ui_story_5089_50890901_56_dialog_content = "Alright, now let me see that letter.",
  ui_story_5089_50890901_57_dialog_content = "... Hahaha! How very interesting. I should've expected as much from PlayerName.",
  ui_story_5089_50890901_58_dialog_content = "His strategy is a bit unorthodox, but much to my surprise, it seems to be the best course of action given the circumstances.",
  ui_story_5089_50890901_59_dialog_content = "Looks like he finally sees things clearly.",
  ui_story_5089_50890901_60_dialog_content = "And what exactly would that be?",
  ui_story_5089_50890901_61_dialog_content = "It's nothing to worry about. In any case, I'll need you to deliver a message shortly.",
  ui_story_5089_50890901_62_dialog_content = "As an ordinary artisan with no hand in politics, I would be wrong to involve myself in these affairs.",
  ui_story_5089_50890901_63_dialog_content = "But as a member of the guild, it's only right for me to provide information if it means rooting out any traitors in our midst.",
  ui_story_5089_50890901_64_dialog_content = "So please do your best, brother.",
  ui_story_5089_50890901_65_dialog_content = "Yes, sister.",
  ui_story_5089_50890901_66_dialog_content = "Now then... How are you feeling over there, neighbor?",
  ui_story_5089_50890901_67_dialog_content = "...",
  ui_story_5089_50890901_68_dialog_content = "That's odd, I thought talking about Master Houfeng would get you to open up.",
  ui_story_5089_50890901_69_dialog_content = "After all, his background seems so familiar now. A man appointed to the royal court ten years ago, but then involved himself in its power struggles and, fell from grace, was never seen or heard from again.",
  ui_story_5089_50890901_70_dialog_content = "I can think of only one person who meets all of those criteria.",
  ui_story_5089_50890901_71_dialog_content = "... It's none of my business anymore.",
  ui_story_5089_50890901_72_dialog_content = "My lifelong obsessions with gratitude and revenge are nothing but a joke now.",
  ui_story_5089_50890901_73_dialog_content = "I no longer know how to wield my blade, which means I no longer serve any purpose.",
  ui_story_5089_50890901_74_dialog_content = "So please stop concerning yourself for my sake, Lady Xuan Ji.",
  ui_story_5089_50890901_75_dialog_content = "To live for a single purpose, and to deserve to be abandoned if you can no longer achieve it.",
  ui_story_5089_50890901_76_dialog_content = "The last time I heard such a description, it was directed at the Eclipsites.",
  ui_story_5089_50890901_77_dialog_content = "I have a question for you, Miss Jiu.",
  ui_story_5089_50890901_78_dialog_content = "What's the biggest difference between us and the Eclipsites?",
  ui_story_5089_50890901_79_dialog_content = "...",
  ui_story_5089_50890901_80_dialog_content = "Is there even a difference?",
  ui_story_5089_50890901_81_dialog_content = "Sigh... It seems I won't make much progress here anytime soon.",
  ui_story_5089_50890901_82_dialog_content = "It's up to you now, my friend.",
  ui_story_5089_50890901_83_dialog_content = "...",
  ui_story_5089_50890901_84_dialog_content = "Is something bothering you, PlayerName?",
  ui_story_5089_50890901_85_dialog_content = "The difference... Between us and Eclipsites?",
  ui_story_5089_50890901_86_dialog_content = "Pardon?",
  ui_story_5089_50890901_87_dialog_content = "Er, it's nothing. Were you saying something just now?",
  ui_story_5089_50890901_88_dialog_content = "Yes. I was saying that if the Fate Riders truly wished to push through our obstacles, we wouldn't be able to stop them.",
  ui_story_5089_50890901_89_dialog_content = "Which is why I suggest we call for reinforcements.",
  ui_story_5089_50890901_90_dialog_content = "Jingliang City can only accommodate so many soldiers within its walls, so most of them are stationed outside the city.",
  ui_story_5089_50890901_91_dialog_content = "They may not be as powerful as the soldiers within the city, but we're still at a clear numbers disadvantage.",
  ui_story_5089_50890901_92_dialog_content = "So you're thinking of using your authority as a princess to bring some of them to our side?",
  ui_story_5089_50890901_93_dialog_content = "No, PlayerName.",
  ui_story_5089_50890901_94_dialog_content = "Wait... Why are you suddenly handing me a dagger?!",
  ui_story_5089_50890901_95_dialog_content = "They may be stationed outside the city, but that doesn't make them less unified as soldiers. By now, the news from within the city must have already reached them.",
  ui_story_5089_50890901_96_dialog_content = "We both know that, at this point, my \"uncle\" has no reason to keep his hand against me.",
  ui_story_5089_50890901_97_dialog_content = "It's safe to assume that they will not obey me if I reveal myself to them.",
  ui_story_5089_50890901_98_dialog_content = "So why are we here then?",
  ui_story_5089_50890901_99_dialog_content = "For this.",
  ui_story_5089_50890901_100_dialog_content = "... Why are you giving me a dagger?",
  ui_story_5089_50890901_101_dialog_content = "We can't be certain about the orders given to the soldiers in this place.",
  ui_story_5089_50890901_102_dialog_content = "But so long as my \"uncle\" cares about his status, he won't openly send someone to assassinate me.",
  ui_story_5089_50890901_103_dialog_content = "If that's the case, then I should still be seen as someone who requires their protection. As such...",
  ui_story_5089_50890901_104_dialog_content = "You want me to pretend to kidnap you and lead them all the way to the workshop?",
  ui_story_5089_50890901_105_dialog_content = "But that's way too risky! There's no telling what could go wrong!",
  ui_story_5089_50890901_106_dialog_content = "What if they manage to capture both of us at once? Or worse, what if the fake king already decided that you're not worth keeping alive?!",
  ui_story_5089_50890901_107_dialog_content = "We should go back and rethink our strategy before—",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>Suddenly, Dantang grabs the hand I'm using to hold the dagger, and brings it swiftly to her neck.</color>",
  ui_story_5089_50890901_109_dialog_content = "Dantang?!",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>I desperately try to pull it away, but the dagger still leaves a red mark on her neck.</color>",
  ui_story_5089_50890901_111_dialog_content = "Please watch me, PlayerName.",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>A bead of blood slides down the blade into my palm, but Dantang simply chuckles under the sunlight, filtering through the forest leaves.</color>",
  ui_story_5089_50890901_113_dialog_content = "I trust you.",
  ui_story_5089_50890901_114_dialog_content = "... I know.",
  ui_story_5089_50890901_115_dialog_content = "Who goes there?",
  ui_story_5089_50890901_116_dialog_content = "S-Stay back!",
  ui_story_5089_50890901_117_dialog_content = "Your Princess Zhuohua is in my hands now!",
  ui_story_5089_50890901_118_dialog_content = "!",
  ui_story_5089_50890901_119_dialog_content = "The princess has been kidnapped! All soldiers assemble!",
  ui_story_5089_50890901_120_dialog_content = "Unhand the princess immediately, and your life may yet be spared!",
  ui_story_5089_50890901_121_dialog_content = "You people don't scare me! And besides, do you really think I would surrender so easily?!",
  ui_story_5089_50890901_122_dialog_content = "I'm a member of the Fate Riders, and our stronghold is not too far from here! We have more fighters and weapons than you can handle!",
  ui_story_5089_50890901_123_dialog_content = "So don't make any sudden moves, or we'll have a war on our hands!",
  ui_story_5089_50890901_124_dialog_content = "Archer! Take aim!",
  ui_story_5089_50890901_125_dialog_content = "Force Boost!",
  ui_story_5089_50890901_126_dialog_content = "Urgh—",
  ui_story_5089_50890901_127_dialog_content = "Don't let him escape!",
  ui_story_5089_50890901_128_dialog_content = "We've lost sight of the princess and her kidnapper, sir!",
  ui_story_5089_50890901_129_dialog_content = "Then fan out and search for them, you fool! We can't afford to let anything happen to the princess!",
  ui_story_5089_50890901_130_dialog_content = "But we have no clues to—Wait! There's a begonia on the ground over here!",
  ui_story_5089_50890901_131_dialog_content = "It must be a clue left by the princess. Quick, look for more of them!",
  ui_story_5089_50890901_132_dialog_content = "They may lead us to their hideout!",
  ui_story_5089_50890901_133_dialog_content = "My lord, a group of soldiers from outside of the city is approaching the workshop.",
  ui_story_5089_50890901_134_dialog_content = "For what reason?",
  ui_story_5089_50890901_135_dialog_content = "They say they encountered a criminal who has kidnapped the princess.",
  ui_story_5089_50890901_136_dialog_content = "Not daring to lose track of them, the captain of their squad followed their trail to this location.",
  ui_story_5089_50890901_137_dialog_content = "So not only are the roads blocked, but we are also surrounded by city guards.",
  ui_story_5089_50890901_138_dialog_content = "A siege is likely to break out soon.",
  ui_story_5089_50890901_139_dialog_content = "If that should happen, our people should be capable of defending the workshop. I suggest we keep them in position for the time being.",
  ui_story_5089_50890901_140_dialog_content = "However, they still insist on seeing what is happening here.",
  ui_story_5089_50890901_141_dialog_content = "Heh.",
  ui_story_5089_50890901_142_dialog_content = "So that's their strategy, is it? Pitiful.",
  ui_story_5089_50890901_143_dialog_content = "Go.",
  ui_story_5089_50890901_144_dialog_content = "If they wish for me to reveal myself, then as king, I will gladly confront them.",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>Moments later—</color>",
  ui_story_5089_50890901_146_dialog_content = "Thank goodness, they're finally gone.",
  ui_story_5089_50890901_147_dialog_content = "They say it's darkest under the lamp, but I find that hiding right under the enemy's nose is always the safest choice.",
  ui_story_5089_50890901_148_dialog_content = "Still, I never expected him to just sit here and brood all day. Even with the palace in such a sorry state, he never called on anyone to fix it.",
  ui_story_5089_50890901_149_dialog_content = "But thanks to these wide beams, I've kept hidden without straining my poor old bones too much.",
  ui_story_5089_50890901_150_dialog_content = "Now that they're gone, I should be able to leave the palace without any trouble.",
  ui_story_5089_50890901_151_dialog_content = "Hm? Isn't this... Miss Jiu's sword?",
  ui_story_5089_50890901_152_dialog_content = "I suppose I should return it to her.",
  ui_story_5089_50890901_153_dialog_content = "*panting* Jeez... This whole time... I've been running as fast as I can...",
  ui_story_5089_50890901_154_dialog_content = "How did those soldiers manage to catch up so quickly?!",
  ui_story_5089_50890901_155_dialog_content = "I tried to divert them with my begonias as best as I could, but they saw through it quicker than I imagined.",
  ui_story_5089_50890901_156_dialog_content = "Moreover, their relentless pursuit proves that their training isn't lacking, even outside of the city.",
  ui_story_5089_50890901_157_dialog_content = "For my \"uncle\" to keep such well-trained soldiers in his command and that stockpile of weapons...",
  ui_story_5089_50890901_158_dialog_content = "What could the Fate Riders be planning...?",
  ui_story_5089_50890901_159_dialog_content = "There's no use thinking about it now. We've already done everything we can do.",
  ui_story_5089_50890901_160_dialog_content = "Let's just catch our breath here for a while.",
  ui_story_5089_50890901_161_dialog_content = "I haven't seen any movement coming from the workshop, but there's no telling how they'll react once they see us.",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>Behind us, the well-trained soldiers spread out and surround us. The torches in their hands paint the night sky a fiery red.</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>Before us, the workshop shows signs of activity despite no one being in sight. It looms eerily over us, like a humongous beast preparing to pounce.",
  ui_story_5089_50890901_164_dialog_content = "I never had a chance to tell you this earlier, PlayerName.",
  ui_story_5089_50890901_165_dialog_content = "Even though I shamelessly asked for your help, I never intended to put you in such a dangerous situation today.",
  ui_story_5089_50890901_166_dialog_content = "For this, I am terribly sorry.",
  ui_story_5089_50890901_167_dialog_content = "Don't worry, Dantang. I have a feeling we'll be fine.",
  ui_story_5089_50890901_168_dialog_content = "After all, I trust you too.",
  ui_story_5089_50890901_169_dialog_content = "Huh? Something's happening with the soldiers...",
  ui_story_5089_50890901_170_dialog_content = "The king has arrived—",
  ui_story_5089_50890901_171_dialog_content = "Look, it's...",
  ui_story_5089_50890901_172_dialog_content = "My so-called uncle.",
  ui_story_5089_50890901_173_dialog_content = "Oh Dantang, I thought you would be smarter than this.",
  ui_story_5089_50890901_174_dialog_content = "Don't you know that with a single command from me, that workshop will remain completely untouched?",
  ui_story_5089_50890901_175_dialog_content = "You are the only ones who will meet your end here, in a place where no one will ever find you.",
  ui_story_5089_50890901_176_dialog_content = "You've walked right into your own graves.",
  ui_story_5089_50890901_177_dialog_content = "If you were truly my uncle, you would have the authority to dispose of us like that.",
  ui_story_5089_50890901_178_dialog_content = "But you have no right to do so as an imposter and a puppet!",
  ui_story_5089_50890901_179_dialog_content = "Before all these people, we will expose you for who you truly are—Master Houfeng!",
  ui_story_5089_50890902_1_dialog_content = "Now, PlayerName!",
  ui_story_5089_50890902_2_dialog_content = "Force Boost!",
  ui_story_5089_50890902_3_dialog_content = "Urgh...",
  ui_story_5089_50890902_4_dialog_content = "(These soldiers aren't our target, so we shouldn't waste any time fighting them.)",
  ui_story_5089_50890902_5_dialog_content = "(The Fate Riders use flesh-like masks to conceal themselves.)",
  ui_story_5089_50890902_6_dialog_content = "(All I need is a single opening... To tear through his mask—!)",
  ui_story_5089_50890902_7_dialog_content = "What?!",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>The dagger finds its mark along the side of the false king's face.</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>But what it cuts is not the inorganic mask that they expected.</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>Rather, blood begins to seep out from the wound, indicating that the target's face is entirely real.</color>",
  ui_story_5089_50890902_11_dialog_content = "How could this be...?",
  ui_story_5089_50890902_12_dialog_content = "It's all but confirmed now.",
  ui_story_5089_50890902_13_dialog_content = "Tell me, were the results to your liking?",
  ui_story_5089_50891001_1_dialog_content = "Y-Your Highness...! Don't just stand there, you fools! Defend the king!",
  ui_story_5089_50891001_2_dialog_content = "Stand down, all of you. This is nothing more than a child making a fuss.",
  ui_story_5089_50891001_3_dialog_content = "No... You can't possibly be the true King of Ye, so why...?",
  ui_story_5089_50891001_4_dialog_content = "If all of your scheming was for this singular moment, then your foolishness is even greater than I imagined.",
  ui_story_5089_50891001_5_dialog_content = "I've been using this identity for so many years, and no one has noticed anything unusual.",
  ui_story_5089_50891001_6_dialog_content = "Did you really think that this could be accomplished with something as simple as a mask?",
  ui_story_5089_50891001_7_dialog_content = "!",
  ui_story_5089_50891001_8_dialog_content = "Of course not. For the last ten years, I've been making small, gradual adjustments to my appearance.",
  ui_story_5089_50891001_9_dialog_content = "Slicing and carving through my very own flesh and bones, all to attain the perfect disguise.",
  ui_story_5089_50891001_10_dialog_content = "When my arms weren't long enough, I had them broken so that they would grow longer.",
  ui_story_5089_50891001_11_dialog_content = "When my voice didn't quite match, I gargled poison to reshape my throat and vocal cords.",
  ui_story_5089_50891001_12_dialog_content = "I was told that before he ascended to the throne, my uncle was often targeted for assassination... I see now.",
  ui_story_5089_50891001_13_dialog_content = "You've certainly gone above and beyond for the Fate Riders.",
  ui_story_5089_50891001_14_dialog_content = "The Fate Riders, you say? Ha! Those cowards are no different than the rats infesting the shadows of the empire.",
  ui_story_5089_50891001_15_dialog_content = "Those insolent vermin are sorely mistaken if they think they can challenge the rightful king of Ye Kingdom!",
  ui_story_5089_50891001_16_dialog_content = "You...",
  ui_story_5089_50891001_17_dialog_content = "Our annual ritual of suppression has begun to fail us, and the new emperor is far too young and inexperienced to guide us through the coming storm. If nothing changes, our lands will soon be plunged into darkness.",
  ui_story_5089_50891001_18_dialog_content = "At first, I meant to proceed carefully in order to maintain our relationship with Ji Kingdom.",
  ui_story_5089_50891001_19_dialog_content = "But with things as they are now, I see no problem with giving over all of our weapons to the Fate Riders.",
  ui_story_5089_50891001_20_dialog_content = "With those firearms in hand, their rebellion will commence even sooner.",
  ui_story_5089_50891001_21_dialog_content = "For years, the Fate Riders have infiltrated the courts of Longzhou's various kingdoms. The flooding of Haojin only demonstrated what will befall the rest of the vassal states. Once they are occupied with their own crises, the Fate Riders will once more target the imperial capital of Yangjing.",
  ui_story_5089_50891001_22_dialog_content = "As the mantis stalks the cicada, the sparrow waits patiently to claim the spoils of their battle.",
  ui_story_5089_50891001_23_dialog_content = "For years, I bided my time, waiting for the perfect gust of wind, but it never came.",
  ui_story_5089_50891001_24_dialog_content = "I refuse to wait any longer. I will be the wind that carries me to victory!",
  ui_story_5089_50891001_25_dialog_content = "Over the course of ten long years, I have trained my troops tirelessly so that they will be ready for war at any time.",
  ui_story_5089_50891001_26_dialog_content = "When the forces of these lands finally clash, the victor will not necessarily be decided by the power of the Fate Riders.",
  ui_story_5089_50891001_27_dialog_content = "You have uncovered my secret, Dantang.",
  ui_story_5089_50891001_28_dialog_content = "But despite your foolishness, your talents would still greatly value the kingdom. Are you willing to continue following me as your king?",
  ui_story_5089_50891001_29_dialog_content = "Simply nod your head, and I guarantee that you will remain Princess Zhuohua of Ye Kingdom.",
  ui_story_5089_50891001_30_dialog_content = "As for you, Caelestite, your skills would also be of undeniable use to me in battle. Will you align yourself with my noble aims?",
  ui_story_5089_50891001_31_dialog_content = "For soon, the seven kingdoms of Longzhou will fall under my rule...",
  ui_story_5089_50891001_32_dialog_content = "Are you aware that the Fate Riders have been colluding with the wicked spirits, and that countless lives have been lost as a result of their treachery?",
  ui_story_5089_50891001_33_dialog_content = "Of course. I am fully aware of their methods, given that Ye Kingdom is the main source of their weapons.",
  ui_story_5089_50891001_34_dialog_content = "But why should I concern myself with the lives of others when they can't be of use to me? To worry about the subjects of my mortal enemies is to show weakness as a conqueror.",
  ui_story_5089_50891001_35_dialog_content = "As for the wicked spirits, they are no different than wild animals. If the Fate Riders are shameless enough to employ them in their methods, then so be it.",
  ui_story_5089_50891001_36_dialog_content = "I can always dispose of them later, if necessity demands it.",
  ui_story_5089_50891001_37_dialog_content = "I understand your views, but it seems—",
  ui_story_5089_50891001_38_dialog_content = "That our paths are too different to ever be aligned.",
  ui_story_5089_50891001_39_dialog_content = "I strongly suggest that you do not defy me, princess.",
  ui_story_5089_50891001_40_dialog_content = "Uh... Could I ask you something?",
  ui_story_5089_50891001_41_dialog_content = "Is it really okay for you to be saying all of this out loud?",
  ui_story_5089_50891001_42_dialog_content = "There's a workshop full of Fate Riders right next to us.",
  ui_story_5089_50891001_43_dialog_content = "I have already ordered my people to lock down that workshop. Unlike you, I go to great lengths to prepare for my next move.",
  ui_story_5089_50891001_44_dialog_content = "The Fate Riders aspire to achieve great things but still rely on my firepower.",
  ui_story_5089_50891001_45_dialog_content = "Once the weapons have been delivered, I have no reason to care whether the people in that workshop live or die.",
  ui_story_5089_50891001_46_dialog_content = "So what'll happen if you can't deliver your weapons within the next three days?",
  ui_story_5089_50891001_47_dialog_content = "... How did you find out about that?",
  ui_story_5089_50891001_48_dialog_content = "Well, I have been told that my skills as a Caelestite are undeniably useful.",
  ui_story_5089_50891001_49_dialog_content = "But more to the point, I'm pretty sure you're not going to make your deadline anymore.",
  ui_story_5089_50891001_50_dialog_content = "What have you done?",
  ui_story_5089_50891001_51_dialog_content = "Great King! There's been an issue—",
  ui_story_5089_50891001_52_dialog_content = "Speak!",
  ui_story_5089_50891001_53_dialog_content = "It's the Artisan's Guild! Their people are dismantling the Huolong Carrier tracks as we speak! All of our originally planned transportation routes are out of commission!",
  ui_story_5089_50891001_54_dialog_content = "Who allowed such a thing to happen?!",
  ui_story_5089_50891001_55_dialog_content = "The guild claims that—",
  ui_story_5089_50891001_56_dialog_content = "A wealthy philanthropist made a generous donation for some much-needed repairs, is all.",
  ui_story_5089_50891001_57_dialog_content = "The tracks were completely worn out due to neglect and misuse by the carrier operators.",
  ui_story_5089_50891001_58_dialog_content = "My only condition was to specify the order in which the tracks were repaired. A simple enough request, right?",
  ui_story_5089_50891001_59_dialog_content = "It even helped us turn your attention towards a very serious issue affecting your kingdom.",
  ui_story_5089_50891001_60_dialog_content = "They've already gotten much of the dismantling work done. Even if you started rebuilding the tracks right now, it'd take you more than three days to finish them.",
  ui_story_5089_50891001_61_dialog_content = "From the beginning, this was the \"path\" I wanted to take... If you'll pardon the pun.",
  ui_story_5089_50891001_62_dialog_content = "Your underhanded tricks will never succeed! All it takes is an order from the king to—",
  ui_story_5089_50891001_63_dialog_content = "Silence, fool!",
  ui_story_5089_50891001_64_dialog_content = "Maybe you're right: maybe my tactics really are underhanded.",
  ui_story_5089_50891001_65_dialog_content = "But you should know by now that we're no longer focused on the means.",
  ui_story_5089_50891001_66_dialog_content = "For the Artisan's Guild to side with you... Was this Ministress Armilla's doing?",
  ui_story_5089_50891001_67_dialog_content = "She wasn't imprisoned for tampering with the arcane blasters but for uncovering your secret. Isn't that right, \"Your Highness\"?",
  ui_story_5089_50891001_68_dialog_content = "From the moment you failed to fully lock her away, you lost.",
  ui_story_5089_50891001_69_dialog_content = "Even if you manage to hold on to Ye Kingdom's throne—",
  ui_story_5089_50891001_70_dialog_content = "Every court official and artisan in Longzhou may be watching your every move from the shadows now.",
  ui_story_5089_50891001_71_dialog_content = "Today, the carrier tracks are being dismantled, but tomorrow, there might be a malfunction in a wooden ox.",
  ui_story_5089_50891001_72_dialog_content = "Even if you switch to a horse-drawn carriage, the horses may not be strong enough to keep things moving.",
  ui_story_5089_50891001_73_dialog_content = "Without the Huolong Carriers, I imagine it would be impossible to transport large amounts of freight quickly.",
  ui_story_5089_50891001_74_dialog_content = "But the most important thing, of course...",
  ui_story_5089_50891001_75_dialog_content = "How difficult would it be to explain to your kingdom why you're shipping off so many firearms out of the country?",
  ui_story_5089_50891001_76_dialog_content = "...",
  ui_story_5089_50891001_77_dialog_content = "My apologies, \"Your Highness\".",
  ui_story_5089_50891001_78_dialog_content = "Regardless of what happens next...",
  ui_story_5089_50891001_79_dialog_content = "The \"momentum\" is currently in my favor.",
  ui_story_5089_50891001_80_dialog_content = "I see.",
  ui_story_5089_50891001_81_dialog_content = "The path you're blocking isn't that of fate, but mine.",
  ui_story_5089_50891001_82_dialog_content = "When you said we were walking into a trap, did you ever consider that we were actually setting the trap for you?",
  ui_story_5089_50891001_83_dialog_content = "You're out of options, Master Houfeng.",
  ui_story_5089_50891001_84_dialog_content = "If you fail to deliver the weapons on time, the Fate Riders will inevitably come to investigate.",
  ui_story_5089_50891001_85_dialog_content = "Based on what you've just said, your loyalty to Junming is questionable at best. Your actions, I'm afraid, may not withstand their scrutiny.",
  ui_story_5089_50891001_86_dialog_content = "Now can we please sit down and have a civil discussion?",
  ui_story_5089_50891001_87_dialog_content = "The Eclipsites and the Fate Riders are not so easily exploited. Asking them to submit to you is no different than asking a tiger to part with its hide.",
  ui_story_5089_50891001_88_dialog_content = "A civil discussion, you say? Hahaha! Have you forgotten that I'm still the king?",
  ui_story_5089_50891001_89_dialog_content = "The fate of Ye Kingdom rests solely in my hands!",
  ui_story_5089_50891001_90_dialog_content = "I refuse to let either of you hinder my—!",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>Spurt—</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>The muffled sound of a blade entering flesh is heard.</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>Soon after, blood begins to spatter in all directions.</color>",
  ui_story_5089_50891001_94_dialog_content = "Houfeng—!",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>From behind, a sharp metal hook pierces through the body of the false king.</color>",
  ui_story_5089_50891001_96_dialog_content = "That's... A Stinger!",
  ui_story_5089_50891001_97_dialog_content = "*sigh* Why couldn't you have just kept quiet and followed orders?",
  ui_story_5089_50891001_98_dialog_content = "Unlike my beautiful clockwork creations, which are the result of extensive research and patient planning...",
  ui_story_5089_50891001_99_dialog_content = "Rash, unrealistic ambitions such as yours can be deadly.",
  ui_story_5089_50891001_100_dialog_content = "You... How dare you...!",
  ui_story_5089_50891001_101_dialog_content = "The princess made a valid point.",
  ui_story_5089_50891001_102_dialog_content = "You underestimate the Fate Riders far too much.",
  ui_story_5089_50891001_103_dialog_content = "My master has decreed that Ye Kingdom no longer serves us any purpose.",
  ui_story_5089_50891001_104_dialog_content = "I've been given free rein over your lands, and I'll start by testing the full firepower of my Stinger!",
  ui_story_5089_50891001_105_dialog_content = "And I owe it all to you, mighty king. If you hadn't given me the Zhuyin Flame, none of this would have happened! Hahaha!",
  ui_story_5089_50891001_106_dialog_content = "Now then... I believe my orders were to level that mountain over there.",
  ui_story_5089_50891001_107_dialog_content = "Adjust targets and begin charging, Stinger. We still have a lot of work to do.",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>The Stinger violently rips its tail out of the false king, who crumples to the ground.</color>",
  ui_story_5089_50891001_109_dialog_content = "That's right, I nearly forgot about this useless traitor...",
  ui_story_5089_50891001_110_dialog_content = "By order of the Fate Riders, execute this man!",
  ui_story_5089_50891001_111_dialog_content = "Your Highness—",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>The royal guards prepare to rush in, but something throws their ranks into complete pandemonium.</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>To their utter shock, several soldiers raise their weapons and begin attacking their comrades!</color>",
  ui_story_5089_50891001_114_dialog_content = "This isn't good! The king's in—",
  ui_story_5089_50891001_115_dialog_content = "Shining Begonias!",
  ui_story_5089_50891001_116_dialog_content = "You...",
  ui_story_5089_50891001_117_dialog_content = "Make no mistake, I have no intention of allying with you.",
  ui_story_5089_50891001_118_dialog_content = "But as long as you live, we can counter the Fate Riders.",
  ui_story_5089_50891001_119_dialog_content = "There's also the matter of holding you accountable for your crimes.",
  ui_story_5089_50891001_120_dialog_content = "Cough... Why even bother...",
  ui_story_5089_50891001_121_dialog_content = "If you don't escape now... You won't live... To regret it.",
  ui_story_5089_50891001_122_dialog_content = "My only regret is that I didn't risk everything and replace you sooner.",
  ui_story_5089_50891001_123_dialog_content = "At the foot of that mountain are countless innocent civilians, as well as the fields that nourish and sustain them.",
  ui_story_5089_50891001_124_dialog_content = "If I were to flee right now, I could never call myself a princess of Ye Kingdom ever again.",
  ui_story_5089_50891001_125_dialog_content = "So here I stand, and PlayerName is no different. It's too late to turn tail and run now!",
  ui_story_5089_50891001_126_dialog_content = "Heh... What a surprise... I never knew...",
  ui_story_5089_50891001_127_dialog_content = "You were even more arrogant than me.",
  ui_story_5089_50891001_128_dialog_content = "But words mean nothing... If you don't manage to survive.",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>As the royal guards continue their battle against one another, another group of Fate Rider assassins rush out of the workshop!</color>",
  ui_story_5089_50891002_1_dialog_content = "If the battle continues like this, I'm afraid the odds will be against us.",
  ui_story_5089_50891002_2_dialog_content = "Miss Jiu.",
  ui_story_5089_50891002_3_dialog_content = "Do you really have nothing to say about all of this?",
  ui_story_5089_50891002_4_dialog_content = "...",
  ui_story_5089_50891002_5_dialog_content = "Huh...?",
  ui_story_5089_50891002_6_dialog_content = "Who's there?!",
  ui_story_5089_50891002_7_dialog_content = "Our master has commanded us to exterminate those who stand in our way.",
  ui_story_5089_50891002_8_dialog_content = "Hmph, so they've infiltrated the palace too.",
  ui_story_5089_50891002_9_dialog_content = "Lightning Flash!",
  ui_story_5089_50891002_10_dialog_content = "...",
  ui_story_5089_50891002_11_dialog_content = "!",
  ui_story_5089_50891002_12_dialog_content = "Out of my way!",
  ui_story_5089_50891002_13_dialog_content = "Miss Jiu, even if you decide to ignore everything else that's happening around you...",
  ui_story_5089_50891002_14_dialog_content = "Are you really going to let yourself be killed by these rats who are too cowardly to show their own faces?!",
  ui_story_5089_50891002_15_dialog_content = "...",
  ui_story_5089_50891101_1_dialog_content = "Eurgh—",
  ui_story_5089_50891101_2_dialog_content = "Keep it up, Dantang! We're almost—Ugh...",
  ui_story_5089_50891101_3_dialog_content = "PlayerName! Oh no... You're burning up!",
  ui_story_5089_50891101_4_dialog_content = "It's okay; I just overused my abilities. I'll be fine soon...",
  ui_story_5089_50891101_5_dialog_content = "It certainly doesn't look that way to me!",
  ui_story_5089_50891101_6_dialog_content = "... Wait.",
  ui_story_5089_50891101_7_dialog_content = "We've known each other long enough for me to understand your abilities fairly well.",
  ui_story_5089_50891101_8_dialog_content = "We may be outnumbered, but even a battle of this intensity shouldn't be enough to exhaust you like this.",
  ui_story_5089_50891101_9_dialog_content = "What else have you been doing?",
  ui_story_5089_50891101_10_dialog_content = "... Looks like the jig is up.",
  ui_story_5089_50891101_11_dialog_content = "I'm sorry, I've been meaning to tell you, but I just never found the chance.",
  ui_story_5089_50891101_12_dialog_content = "But now... I think it's faster to just show you.",
  ui_story_5089_50891101_13_dialog_content = "?",
  ui_story_5089_50891101_14_dialog_content = "Psychic Scan!",
  ui_story_5089_50891101_15_dialog_content = "So, you've finally arrived.",
  ui_story_5089_50891101_16_dialog_content = "You've kept me waiting for quite some time, princess.",
  ui_story_5089_50891101_17_dialog_content = "Ministress Armilla! But... Why are you...",
  ui_story_5089_50891101_18_dialog_content = "As much as I'd love to catch up, I still have some unwelcome guests to deal with on my end.",
  ui_story_5089_50891101_19_dialog_content = "Xuan Ji, behind you!",
  ui_story_5089_50891101_20_dialog_content = "Lightning Flash!",
  ui_story_5089_50891101_21_dialog_content = "Much appreciated, PlayerName.",
  ui_story_5089_50891101_22_dialog_content = "Have you been guiding both of our battles all this time, PlayerName?! No wonder your burden is so great!",
  ui_story_5089_50891101_23_dialog_content = "If you're worried about that, you should ask him how long he's maintained his psychic connection with me. The answer might surprise you!",
  ui_story_5089_50891101_24_dialog_content = "...",
  ui_story_5089_50891101_25_dialog_content = "PlayerName?",
  ui_story_5089_50891101_26_dialog_content = "It... It hasn't been that long... I only started communicating with Xuan Ji yesterday.",
  ui_story_5089_50891101_27_dialog_content = "Yes. For an entire day and night, to be exact.",
  ui_story_5089_50891101_28_dialog_content = "It's your own fault for not explaining things more clearly, you know...",
  ui_story_5089_50891101_29_dialog_content = "Besides, I've been careful not to keep a powerful connection to her unless an emergency happened...",
  ui_story_5089_50891101_30_dialog_content = "But to sustain even a weak connection, it means you haven't slept this whole time.",
  ui_story_5089_50891101_31_dialog_content = "...",
  ui_story_5089_50891101_32_dialog_content = "I'm not the only one, either.",
  ui_story_5089_50891101_33_dialog_content = "You're right... I owe Jiu an apology too.",
  ui_story_5089_50891101_34_dialog_content = "What you said last night made me worry that you would do something reckless, so I secretly connected with you to be safe.",
  ui_story_5089_50891101_35_dialog_content = "I also saw your battle with the King of Ye.",
  ui_story_5089_50891101_36_dialog_content = "I understand how you must feel, but...",
  ui_story_5089_50891101_37_dialog_content = "Look out!",
  ui_story_5089_50891101_38_dialog_content = "Nngh...",
  ui_story_5089_50891101_39_dialog_content = "Dantang! Are you okay?!",
  ui_story_5089_50891101_40_dialog_content = "!",
  ui_story_5089_50891101_41_dialog_content = "Please, Jiu! I know you're in a terrible place right now, but we need your help!",
  ui_story_5089_50891101_42_dialog_content = "But... But I...",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>Jiu pauses and lets out a heavy sigh.</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>Without saying anything, she picks up the dagger the Fate Rider assassin dropped and thrusts it at him.</color>",
  ui_story_5089_50891101_45_dialog_content = "!",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>He dodges in panic, but the dagger only grazes him before slipping out of Jiu's hand and clattering against the wall.</color>",
  ui_story_5089_50891101_47_dialog_content = "Miss Jiu, you...",
  ui_story_5089_50891101_48_dialog_content = "In the past, my blade was no different from my body.",
  ui_story_5089_50891101_49_dialog_content = "Whether injured or bloodstained, it made no difference to me.",
  ui_story_5089_50891101_50_dialog_content = "My sword's path was clear—Gratitude is what guided every swing and every strike.",
  ui_story_5089_50891101_51_dialog_content = "But now that my path is no longer clear, my swordsmanship has also abandoned me.",
  ui_story_5089_50891101_52_dialog_content = "As you can see, I can no longer wield a blade.",
  ui_story_5089_50891101_53_dialog_content = "Jiu...",
  ui_story_5089_50891101_54_dialog_content = "Focus on the battle, PlayerName. We don't have time to worry about irrelevant people like her anymore.",
  ui_story_5089_50891101_55_dialog_content = "At first I had doubts, but now I see that relieving her as my guard was the right choice after all.",
  ui_story_5089_50891101_56_dialog_content = "D-Dantang?",
  ui_story_5089_50891101_57_dialog_content = "For ten years, she devoted herself to the art of the blade, but now she's willing to throw it all away without a second thought.",
  ui_story_5089_50891101_58_dialog_content = "Her teacher, the so-called \"greatest swordsman in the world,\" was apparently nothing more than a name without substance.",
  ui_story_5089_50891101_59_dialog_content = "... My lack of skill is no reason to slander my master's name like this, Your Highness.",
  ui_story_5089_50891101_60_dialog_content = "Your \"master\"? Can you still call him that as you are now?",
  ui_story_5089_50891101_61_dialog_content = "Because it seems his teachings are no longer reflected in your swordsmanship.",
  ui_story_5089_50891101_62_dialog_content = "...",
  ui_story_5089_50891101_63_dialog_content = "If you're so obsessed with settling scores, then let's settle some right now.",
  ui_story_5089_50891101_64_dialog_content = "You've had parents who loved you, neighbors who cared for you, and teachers who guided you.",
  ui_story_5089_50891101_65_dialog_content = "If it wasn't for Captain Yuebai's and Ministress Armilla's efforts aboard the Shadowind, we would most likely be at the bottom of the sea right now.",
  ui_story_5089_50891101_66_dialog_content = "And let's not forget that PlayerName has never once abandoned you, especially now.",
  ui_story_5089_50891101_67_dialog_content = "Yet you never truly paid attention to the consideration afforded to you. What a shameful waste of kindness.",
  ui_story_5089_50891101_68_dialog_content = "... Your insights into my character are entirely correct, Your Highness.",
  ui_story_5089_50891101_69_dialog_content = "My debt to all of you is more than I could ever repay. I couldn't possibly fail to understand that.",
  ui_story_5089_50891101_70_dialog_content = "But what about you, Lady Dantang?",
  ui_story_5089_50891101_71_dialog_content = "I consider myself to have faithfully served by your side, never abandoning you for even a moment.",
  ui_story_5089_50891101_72_dialog_content = "And yet you tossed me aside without another word, as if I were a worn-out pair of shoes!",
  ui_story_5089_50891101_73_dialog_content = "Are you angry at me, Jiu?",
  ui_story_5089_50891101_74_dialog_content = "And here I thought you had become nothing more than a soulless puppet.",
  ui_story_5089_50891101_75_dialog_content = "I'm sorry. Have I disappointed you yet again, Your Highness?",
  ui_story_5089_50891101_76_dialog_content = "Yes, actually.",
  ui_story_5089_50891101_77_dialog_content = "Since we know you're still capable of emotion, it means you can also understand our concern for you.",
  ui_story_5089_50891101_78_dialog_content = "So why do you insist on suppressing your blade over things like gratitude and vengeance?!",
  ui_story_5089_50891101_79_dialog_content = "Your Highness...?",
  ui_story_5089_50891101_80_dialog_content = "Dantang, behind you—!",
  ui_story_5089_50891101_81_dialog_content = "Shining Begonias!",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>Without looking back, a sea of begonias erupts behind Dantang and surges in every direction.</color>",
  ui_story_5089_50891101_83_dialog_content = "There's one last thing I need to tell you.",
  ui_story_5089_50891101_84_dialog_content = "I didn't leave you because of your loyalty to others, but because you didn't understand.",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>In the blink of an eye, begonias bloom as far as the eye can see.</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>Upon setting foot in this sea of flowers, their enemies lower their weapons and stand in a trance-like state.</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>In their midst, Dantang's blood-stained appearance is unimaginably captivating.</color>",
  ui_story_5089_50891101_88_dialog_content = "\"The universe follows fifty laws, but Heaven keeps forty-nine secrets, leaving a single path for mankind.\"",
  ui_story_5089_50891101_89_dialog_content = "Even the fickle heavens leave a way for us, so why do you insist on restraining yourself like this?",
  ui_story_5089_50891101_90_dialog_content = "I'll tell you again the words I couldn't finish back at the inn.",
  ui_story_5089_50891101_91_dialog_content = "It must be caged if you seek to admire a bird's splendid plumage.",
  ui_story_5089_50891101_92_dialog_content = "If you seek to admire a tiger's vibrant fur, it must be hunted and turned into a coat.",
  ui_story_5089_50891101_93_dialog_content = "But this is not true admiration.",
  ui_story_5089_50891101_94_dialog_content = "All living creatures are born free. Let them soar through the sky and roar from the mountaintops if you truly wish to admire them.",
  ui_story_5089_50891101_95_dialog_content = "I forced you to seek the truth because I don't want to be the shackle that binds you forever.",
  ui_story_5089_50891101_96_dialog_content = "I don't wish for you to protect me and obey my every whim any longer. I don't want you to spend the rest of your life as a blade hidden in the shadows.",
  ui_story_5089_50891101_97_dialog_content = "I want you to hold your head high, and live freely under the sun's light.",
  ui_story_5089_50891101_98_dialog_content = "I want your name to stand next to mine in the annals of history, not as a silent guardian but as a proud and beloved general.",
  ui_story_5089_50891101_99_dialog_content = "I want you to follow me of your own accord.",
  ui_story_5089_50891101_100_dialog_content = "I want—",
  ui_story_5089_50891101_101_dialog_content = "To be a true ruler to you!",
  ui_story_5089_50891101_102_dialog_content = "Princess Dantang...",
  ui_story_5089_50891101_103_dialog_content = "You aren't my protector any longer. I have no right to give you commands now.",
  ui_story_5089_50891101_104_dialog_content = "But now that you are no longer bound by duty, gratitude, or vengeance, if you are still willing to lend me your strength...",
  ui_story_5089_50891101_105_dialog_content = "Then get up! Crawl if you have to, but do it now—",
  ui_story_5089_50891101_106_dialog_content = "Jiu!",
  ui_story_5089_50891101_107_dialog_content = "Get up and stand by my side!",
  ui_story_5089_50891101_108_dialog_content = "... Have I ever told you how headstrong you can be, Your Highness?",
  ui_story_5089_50891101_109_dialog_content = "Not even once.",
  ui_story_5089_50891101_110_dialog_content = "So come here and say it to me.",
  ui_story_5089_50891101_111_dialog_content = "...",
  ui_story_5089_50891101_112_dialog_content = "As you wish.",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>Moments later.</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>The newly repaired palace gates collapse for a second time.</color>",
  ui_story_5089_50891101_116_dialog_content = "The convict is escaping! After her!",
  ui_story_5089_50891101_117_dialog_content = "I'm back, Sister Xu—Ah! Wh-What in the world is going on here?!",
  ui_story_5089_50891101_118_dialog_content = "Oh, nothing, our newest guest just decided to leave, is all.",
  ui_story_5089_50891101_119_dialog_content = "Th-That gust of wind I felt just now... Was that her?!",
  ui_story_5089_50891101_120_dialog_content = "That's right. My last fight left me a little drained, so I asked her to clear a path out of the prison for us.",
  ui_story_5089_50891101_121_dialog_content = "Honestly... Hey, wait a minute!",
  ui_story_5089_50891101_122_dialog_content = "Did that girl really just leave without a weapon?",
  ui_story_5089_50891101_123_dialog_content = "Of course. With her skills, she could easily split this palace in half.",
  ui_story_5089_50891101_124_dialog_content = "I wouldn't dare put a sword in her hands right now, either.",
  ui_story_5089_50891101_125_dialog_content = "So she plans to face the king's entire army completely unarmed?! Aren't you concerned for her safety?!",
  ui_story_5089_50891101_126_dialog_content = "What's there to be concerned about?",
  ui_story_5089_50891101_127_dialog_content = "I know her gloominess wasn't much to look at before, but now—",
  ui_story_5089_50891101_128_dialog_content = "No one can stop her unless she herself allows it.",
  ui_story_5089_50891101_129_dialog_content = "There she is! Surround the fugitive before she tries to escape!",
  ui_story_5089_50891101_130_dialog_content = "Look, she's unarmed! Seize her!",
  ui_story_5089_50891101_131_dialog_content = "How naive of you to assume I'm unarmed.",
  ui_story_5089_50891101_132_dialog_content = "I may not have a blade in hand, but anything can serve as a weapon for a true swordfighter.",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>With a twirl, she fades into the darkness of the night. Suddenly—</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>Petals scatter.</color>",
  ui_story_5089_50891101_135_dialog_content = "What... What is this...?",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>Leaves gather.</color>",
  ui_story_5089_50891101_137_dialog_content = "Hey, what's the matter with you? Why are you lying down on the ground like that?! Get up and—Uwaaaa!",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>Bamboo sweeps.</color>",
  ui_story_5089_50891101_139_dialog_content = "Run! Run for your lives! Aaaahhhh—",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>Shadows flicker.</color>",
  ui_story_5089_50891101_141_dialog_content = "There you are! Take this!",
  ui_story_5089_50891101_142_dialog_content = "A-A cloak? But where did she... Urgh...",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>In an instant, Jiu cuts a bloody swath through countless soldiers.</color>",
  ui_story_5089_50891101_144_dialog_content = "A demon... She has to be some kind of demon!",
  ui_story_5089_50891101_145_dialog_content = "No. I'm definitely a person.",
  ui_story_5089_50891101_146_dialog_content = "Someone who is far different from demons or wicked spirits.",
  ui_story_5089_50891101_147_dialog_content = "It took me a great deal of time and effort to finally realize this, so could you please stand aside?",
  ui_story_5089_50891101_148_dialog_content = "I have somewhere else to be right now.",
  ui_story_5089_50891101_149_dialog_content = "... Get her.",
  ui_story_5089_50891101_150_dialog_content = "Have it your way, then.",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>Jiu bends down and picks up the spear of a fallen soldier. With a swift motion, she snaps off the blade and brandishes it like a sword.</color>",
  ui_story_5089_50891101_152_dialog_content = "Move.",
  ui_story_5089_50891101_153_dialog_content = "My place—",
  ui_story_5089_50891101_154_dialog_content = "Is at my master's side!",
  ui_story_5089_50891201_1_dialog_content = "Have you located Zhui Hu yet, PlayerName?",
  ui_story_5089_50891201_2_dialog_content = "Yeah! She's just up ahead!",
  ui_story_5089_50891201_3_dialog_content = "Hmph.",
  ui_story_5089_50891201_4_dialog_content = "All those people, and yet they were still powerless to stop you.",
  ui_story_5089_50891201_5_dialog_content = "It seems they really don't compare to clockwork beasts after all.",
  ui_story_5089_50891201_6_dialog_content = "If I remember correctly, didn't we completely destroy your precious Stinger last time?",
  ui_story_5089_50891201_7_dialog_content = "That's right, and our reinforcements will be here any second now. If I were you, I'd surrender before it's too late.",
  ui_story_5089_50891201_8_dialog_content = "Reinforcements? How very frightening.",
  ui_story_5089_50891201_9_dialog_content = "No matter how many reinforcements you call upon, you're all still mortal like anyone else. Are you sure you want them to be here when this mountain comes crashing down?",
  ui_story_5089_50891201_10_dialog_content = "Instead of wasting time with this futile display of bravado, you should begin evacuating everyone immediately.",
  ui_story_5089_50891201_11_dialog_content = "By my estimation, once this mountain collapses, all of the farmland in this entire area will be completely decimated.",
  ui_story_5089_50891201_12_dialog_content = "I see now why I was tasked with such a bizarre mission.",
  ui_story_5089_50891201_13_dialog_content = "This must be one of Ye Kingdom's most important grain-producing regions. It seems this year's harvest will be somewhat lacking.",
  ui_story_5089_50891201_14_dialog_content = "Rumor has it that Ji Kingdom is also meddling with Ye Kingdom's food supplies. If something goes wrong, a widespread famine could be just around the corner.",
  ui_story_5089_50891201_15_dialog_content = "Aren't you from Ye Kingdom too? Why would you do such a thing?!",
  ui_story_5089_50891201_16_dialog_content = "I thought I made myself perfectly clear last time: anyone willing to support my craft deserves to be called my master.",
  ui_story_5089_50891201_17_dialog_content = "Don't let her words distract you, PlayerName.",
  ui_story_5089_50891201_18_dialog_content = "She's simply stalling for... Wait! Where's your Stinger, Zhui Hu?!",
  ui_story_5089_50891201_19_dialog_content = "Hehehe, I'm glad you finally noticed, but it's far too late now.",
  ui_story_5089_50891201_20_dialog_content = "See that light in the distance?",
  ui_story_5089_50891201_21_dialog_content = "My Stinger's attack is fully charged now, and with the power of the Zhuyin Flame, this mountain will soon be nothing but a pile of rubble!",
  ui_story_5089_50891201_22_dialog_content = "Do try to enjoy the show, won't you?",
  ui_story_5089_50891201_23_dialog_content = "Have you gone mad?! If that thing destroys the mountain, you'll die along with the rest of us!",
  ui_story_5089_50891201_24_dialog_content = "Rest assured, I'm perfectly capable of staying alive.",
  ui_story_5089_50891201_25_dialog_content = "More importantly, as this is my Stinger's very first full-scale attack, it's only natural that I observe its effects first-hand.",
  ui_story_5089_50891201_26_dialog_content = "Be grateful, you two. Not everyone gets the chance to witness such a marvelous spectacle.",
  ui_story_5089_50891201_27_dialog_content = "... Ignore her for now, PlayerName! We have to stop the Stinger!",
  ui_story_5089_50891201_28_dialog_content = "There's no stopping it now.",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>A blinding beam of light rips through the colossal mountain, and countless stones of all sizes rain down from the sky.</color>",
  ui_story_5089_50891201_31_dialog_content = "Soldiers! Escort Master Hou—I mean, escort the king to safety! Once he's out of harm's way, search the rubble for survivors and evacuate them!",
  ui_story_5089_50891201_32_dialog_content = "A princess shouldn't abandon her guests so callously, you know.",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>A clockwork beast emerges from the debris and lunges straight at Dantang!</color>",
  ui_story_5089_50891201_34_dialog_content = "Look out—!",
  ui_story_5089_50891201_35_dialog_content = "I'm sorry, but I cannot allow you to pass. It's simply too dangerous up ahead.",
  ui_story_5089_50891201_36_dialog_content = "Argh, we've been arguing about this for hours, my good man! Why won't you believe me?",
  ui_story_5089_50891201_37_dialog_content = "My divinations clearly suggest that a catastrophic event will soon occur somewhere in this direction.",
  ui_story_5089_50891201_38_dialog_content = "We can only stem the tides of chaos and prevent this imminent disaster by swiftly delivering this sword to its rightful owner.",
  ui_story_5089_50891201_39_dialog_content = "I'm certain our soldiers can handle this so-called disaster just fine. Either way, you still cannot pass.",
  ui_story_5089_50891201_40_dialog_content = "I'm begging you, kind sir, just let me—",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5089_50891201_42_dialog_content = "Th-The mountain...! But how can this be?!",
  ui_story_5089_50891201_43_dialog_content = "I warned you, didn't I?",
  ui_story_5089_50891201_44_dialog_content = "There's no time to waste! I'll be taking my leave now!",
  ui_story_5089_50891201_45_dialog_content = "Wait, you—",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>Suddenly, a dark and unsettling wind seems to pass by.</color>",
  ui_story_5089_50891201_47_dialog_content = "Hmm? Did someone pass through here just now?",
  ui_story_5089_50891201_48_dialog_content = "Shining Begonias!",
  ui_story_5089_50891201_49_dialog_content = "Urgh!",
  ui_story_5089_50891201_50_dialog_content = "It seems you've gotten stronger since our last encounter at sea.",
  ui_story_5089_50891201_51_dialog_content = "Unlike you, not all of us cling to our belongings and refuse to move on.",
  ui_story_5089_50891201_52_dialog_content = "Heh, such biting words.",
  ui_story_5089_50891201_53_dialog_content = "Come out, all of you!",
  ui_story_5089_50891201_54_dialog_content = "I'm curious to see whether or not you can survive against my so-called \"belongings\"!",
  ui_story_5089_50891201_55_dialog_content = "!",
  ui_story_5089_50891201_56_dialog_content = "(Dantang's already at her limit. She won't be able to keep going at this rate.)",
  ui_story_5089_50891201_57_dialog_content = "(The mountain still hasn't collapsed, but it can happen any second now... What should we do?)",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>A swift thunderbolt cuts through the dense night.</color>",
  ui_story_5089_50891201_60_dialog_content = "Jiu!",
  ui_story_5089_50891201_61_dialog_content = "You were too slow!",
  ui_story_5089_50891201_62_dialog_content = "Please be reasonable, Your Highness. I came here as quickly as I could.",
  ui_story_5089_50891201_63_dialog_content = "But even so, I still owe you an apology.",
  ui_story_5089_50891201_64_dialog_content = "Forgive me for being so late.",
  ui_story_5089_50891201_65_dialog_content = "Apology accepted.",
  ui_story_5089_50891201_66_dialog_content = "Hmph, yet another nuisance.",
  ui_story_5089_50891201_67_dialog_content = "No matter. I doubt even the three of you can withstand the onslaught of an entire workshop full of clockwork beasts!",
  ui_story_5089_50891201_68_dialog_content = "Roooaaarrr!!!",
  ui_story_5089_50891201_69_dialog_content = "I can handle this alone.",
  ui_story_5089_50891201_70_dialog_content = "If you wish to approach Princess Dantang and PlayerName, you'll have to get past me first!",
  ui_story_5089_50891201_71_dialog_content = "(The battle that unfolded before us could only be described as \"dazzling.\")",
  ui_story_5089_50891201_72_dialog_content = "(Despite facing an army of clockwork beasts and endlessly falling rocks, Jiu never budged an inch.)",
  ui_story_5089_50891201_73_dialog_content = "(Weapons, branches, leaves, stones, and even the wreckage of downed clockwork beasts...)",
  ui_story_5089_50891201_74_dialog_content = "(Any object in Jiu's sight had the potential to become a powerful weapon. She was unstoppable as long as she had something in her hands.)",
  ui_story_5089_50891201_75_dialog_content = "As swift as the legendary archer who shot down the Nine Suns, and as majestic as the emperors atop their soaring dragons.",
  ui_story_5089_50891201_76_dialog_content = "Descending upon the battlefield like a gathering storm, she parts a sea of soldiers like a brilliant bolt of lightning.",
  ui_story_5089_50891201_77_dialog_content = "Have you finally discovered your true blade, Jiu?",
  ui_story_5089_50891201_78_dialog_content = "Creak—",
  ui_story_5089_50891201_79_dialog_content = "No... This can't be! How can a mere mortal command such power?!",
  ui_story_5089_50891201_80_dialog_content = "I'm not finished yet—!",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>But Jiu instantly appears behind her back before she can summon more clockwork beasts.</color>",
  ui_story_5089_50891201_82_dialog_content = "Don't move.",
  ui_story_5089_50891201_83_dialog_content = "!",
  ui_story_5089_50891201_84_dialog_content = "Hmph, you think this is over just because you've captured me?",
  ui_story_5089_50891201_85_dialog_content = "So long as the Fate Riders manage to retrieve my all-powerful stinger, it will continue wreaking havoc across the battlefield!",
  ui_story_5089_50891201_86_dialog_content = "And besides, even with your supernatural strength, you could never hope to prevent this mountain from collapsing!",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>Under enormous pressure, the layers of rock beneath the mountain begin to emit ominous sounds. Suddenly, massive boulders begin breaking off and crashing down to the ground.</color>",
  ui_story_5089_50891201_89_dialog_content = "Dantang! Jiu! It isn't safe here! We have to go right now!",
  ui_story_5089_50891201_90_dialog_content = "That appears to be our only choice. By now, the royal guards should have evacuated the civilians.",
  ui_story_5089_50891201_91_dialog_content = "We'll discuss things once we make it to safety.",
  ui_story_5089_50891201_92_dialog_content = "... Jiu? Why aren't you retreating?",
  ui_story_5089_50891201_93_dialog_content = "I can stop it.",
  ui_story_5089_50891201_94_dialog_content = "What?",
  ui_story_5089_50891201_95_dialog_content = "My master once said that the Thundering Edge technique is capable of splitting mountains and parting seas.",
  ui_story_5089_50891201_96_dialog_content = "But I thought you said your master never taught you that move?",
  ui_story_5089_50891201_97_dialog_content = "He claimed that he had no way of teaching it to me, yes. At first, I thought he was simply making excuses.",
  ui_story_5089_50891201_98_dialog_content = "But now I'm beginning to see that he was right all along.",
  ui_story_5089_50891201_99_dialog_content = "The Thundering Edge cannot be taught because it's not a real sword technique at all.",
  ui_story_5089_50891201_100_dialog_content = "Rather, it's the heart of one's sword.",
  ui_story_5089_50891201_101_dialog_content = "Even if that's the case, you don't have a sword right now—",
  ui_story_5089_50891201_102_dialog_content = "Friends! I could really use some assistance right now!",
  ui_story_5089_50891201_103_dialog_content = "Oh dear, oh my, how am I supposed to dodge all of these rocks—",
  ui_story_5089_50891201_104_dialog_content = "Tianxian! This is no time to be playing games!",
  ui_story_5089_50891201_105_dialog_content = "I am in the middle of serious divinations right now—Ah! No going that way, I suppose.",
  ui_story_5089_50891201_106_dialog_content = "Miss Jiu, I have your sword right here! Catch!",
  ui_story_5089_50891201_107_dialog_content = "Not on my watch!",
  ui_story_5089_50891201_108_dialog_content = "!",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>As Jiu's sword sails through the air, several fire crabs immediately pounce at Dantang.</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>Jiu stumbles and her blade lands in the claws of a fire crab instead. In the next moment, it scuttles towards an area of extremely dense rubble.</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>Almost instantly, the fire crab is crushed under the falling rocks, trapping Jiu's blade along with it.</color>",
  ui_story_5089_50891201_112_dialog_content = "... I'll go get it!",
  ui_story_5089_50891201_113_dialog_content = "PlayerName! / PlayerName!",
  ui_story_5089_50891201_114_dialog_content = "Force Boost!",
  ui_story_5089_50891201_115_dialog_content = "(As long as I can accurately predict where the stones will land, I can make it!)",
  ui_story_5089_50891201_116_dialog_content = "Got it!",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>The earth shakes violently as the mountain, which has been teetering for a long time, finally collapses completely!</color>",
  ui_story_5089_50891201_119_dialog_content = "(Not good, I can't dodge that many rocks at once—!)",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>A flash of golden light.</color>",
  ui_story_5089_50891201_121_dialog_content = "The rocks... They're all being deflected?",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>A familiar, golden barrier in the shape of a lotus hangs in the sky, blocking the cascade of falling boulders.</color>",
  ui_story_5089_50891201_123_dialog_content = "Huh? Something feels warm in my pocket... Wait... Isn't this the leaf Chen'ni gave me?",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>This was no ordinary leaf...</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>But an iridescent dragon scale.</color>",
  ui_story_5089_50891201_126_dialog_content = "... Thank you, Chen'ni.",
  ui_story_5089_50891201_127_dialog_content = "I'll be sure to buy you many snacks next time we meet!",
  ui_story_5089_50891201_128_dialog_content = "Heads up, Jiu—!",
  ui_story_5089_50891201_129_dialog_content = "Thanks.",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>The mountain continues its cataclysmic descent, as though threatening to shatter the entire planet under its immeasurable weight.</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>Standing amid the rumbling earth and falling rubble, Jiu closes her eyes and shuts out the world around her.</color>",
  ui_story_5089_50891201_132_dialog_content = "Master, it seems that I finally understand the meaning of a sword.",
  ui_story_5089_50891201_133_dialog_content = "\"The universe follows fifty laws, but Heaven keeps forty-nine secrets, leaving a single path for mankind.\"",
  ui_story_5089_50891201_134_dialog_content = "Even the fickle heavens leave a way for us, so why do you insist on restraining yourself like this?",
  ui_story_5089_50891201_135_dialog_content = "Never mind. If you really need a time limit, then...",
  ui_story_5089_50891201_136_dialog_content = "Your orders won't end until the day you can swing your blade without doing so out of gratitude or vengeance. How about that?",
  ui_story_5089_50891201_137_dialog_content = "I have a question for you, Miss Jiu.",
  ui_story_5089_50891201_138_dialog_content = "What's the biggest difference between us and the Eclipsites?",
  ui_story_5089_50891201_139_dialog_content = "Please forgive me, Lady Xuan Ji. I was too much of a fool to understand your question at the time.",
  ui_story_5089_50891201_140_dialog_content = "But thankfully, I have many wonderful people at my side who will guide me when I'm lost.",
  ui_story_5089_50891201_141_dialog_content = "So now, allow me to give you my answer.",
  ui_story_5089_50891201_142_dialog_content = "The biggest difference between us and the Eclipsites is that our instincts or orders do not wholly control us.",
  ui_story_5089_50891201_143_dialog_content = "If that were the case, we would be devoid of meaning without them.",
  ui_story_5089_50891201_144_dialog_content = "Even if we get lost, fall into darkness, or imprison ourselves in a cage of foolishness, we can always encounter people of boundless kindness and warmth.",
  ui_story_5089_50891201_145_dialog_content = "Gentle souls who will guide us out of the oppressive shadows—",
  ui_story_5089_50891201_146_dialog_content = "And into the warm glow of the sun!",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>Jiu suddenly opens her eyes and swings her blade with almost imperceivable speed.</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>The mountain disintegrates immediately afterward as heaven and earth resonate in unison.</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>A blade that embodies the utmost ferocity, yet carries an extreme lightness.</color>",
  ui_story_5089_50891201_150_dialog_content = "I no longer wield my blade for gratitude or vengeance.",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>Rather, she wields it as a gift to the many friends who have shown her kindness.</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>The shockwave of her ultimate attack sweeps across the smallest pebble to the tallest mountain, crushing all that it touches to dust.</color>",
  ui_story_5089_50891201_153_dialog_content = "Incredible...",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>Looking up again, the immense mountain that was just crashing down a moment ago has turned into a cloud of dust.</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>The frost blade splits the air, leaving thunder in its wake.</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>Echoing across the tops of distant mountains.</color>",
  ui_story_5089_50891201_157_dialog_content = "Sister Xuan Ji... That attack just now won't happen again, will it?",
  ui_story_5089_50891201_158_dialog_content = "Most likely not.",
  ui_story_5089_50891201_159_dialog_content = "Still, I never expected her blade to possess such formidable power.",
  ui_story_5089_50891201_160_dialog_content = "Even from this distance, the Stinger was completely cleaved in half... Hmm?",
  ui_story_5089_50891201_161_dialog_content = "Sister... Is that the Zhuyin Flame?!",
  ui_story_5089_50891201_162_dialog_content = "Like I always say, an artisan should be meticulous in all that they do.",
  ui_story_5089_50891201_163_dialog_content = "Though I must say, this is the first time I've seen someone cut a flame in half.",
  ui_story_5089_50891201_164_dialog_content = "This isn't the time to be joking, Sister Xuan Ji!",
  ui_story_5089_50891201_165_dialog_content = "The Zhuyin Flame is our sect's most treasured artifact, but look at it now! It's been cut in half!",
  ui_story_5089_50891201_166_dialog_content = "Yes, and two perfectly symmetrical halves, no less.",
  ui_story_5089_50891201_167_dialog_content = "Miss Jiu has truly done us a great favor.",
  ui_story_5089_50891201_168_dialog_content = "What in the world are you talking about?! How are we supposed to explain this to the guild?!",
  ui_story_5089_50891201_169_dialog_content = "Don't worry, I'll take care of everything.",
  ui_story_5089_50891201_170_dialog_content = "Now go and inform the others below. The clockwork beast over here has been dealt with, so have them assist with the rest of the efforts.",
  ui_story_5089_50891201_171_dialog_content = "After all, we should be the ones responsible for cleaning up after our own traitors.",
  ui_story_5089_50891201_172_dialog_content = "Understood.",
  ui_story_5089_50891201_173_dialog_content = "Nngh.",
  ui_story_5089_50891201_174_dialog_content = "Are you alright, Jiu?",
  ui_story_5089_50891201_175_dialog_content = "I'm fine, just feeling a bit drained...",
  ui_story_5089_50891201_176_dialog_content = "Wait a minute... You're completely covered in blood! You've been fighting in this condition the whole time?!",
  ui_story_5089_50891201_177_dialog_content = "Quick, call a medic!",
  ui_story_5089_50891201_178_dialog_content = "I appreciate your concern, PlayerName, but I still have something I must do.",
  ui_story_5089_50891201_179_dialog_content = "What could you possibly have to do after all of this?!",
  ui_story_5089_50891201_180_dialog_content = "Don't just stand there, Dantang! Say something to her!",
  ui_story_5089_50891201_181_dialog_content = "Leave her be, PlayerName.",
  ui_story_5089_50891201_182_dialog_content = "It's time for her to lay everything to rest once and for all.",
  ui_story_5089_50891201_183_dialog_content = "But what could she be... Oh, I see now!",
  ui_story_5089_50891201_184_dialog_content = "You're right, it's time to finish this.",
  ui_story_5089_50891201_185_dialog_content = "So you've come.",
  ui_story_5089_50891201_186_dialog_content = "That's right.",
  ui_story_5089_50891201_187_dialog_content = "Guards, bring me a sword.",
  ui_story_5089_50891201_188_dialog_content = "But Your Highness, you're still gravely wounded! You shouldn't be moving right now!",
  ui_story_5089_50891201_189_dialog_content = "I said bring me a sword.",
  ui_story_5089_50891201_190_dialog_content = "I owe this much to her, at the very least.",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>Jiu pulls out her mask and dons it once more.</color>",
  ui_story_5089_50891201_192_dialog_content = "Let's settle this.",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>Clang—</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>In an empty field, the two figures collide. After a brief exchange, the false king's sword is struck from his hands and into the air.</color>",
  ui_story_5089_50891202_3_dialog_content = "Cough... Cough, cough...",
  ui_story_5089_50891202_4_dialog_content = "Please, Your Highness! Enough of this fighting!",
  ui_story_5089_50891202_5_dialog_content = "The outcome is clear.",
  ui_story_5089_50891202_6_dialog_content = "You have bested me.",
  ui_story_5089_50891202_7_dialog_content = "...",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>Crack.</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>Jiu's mask is sliced in two by the false king's attack, and it falls to the ground.</color>",
  ui_story_5089_50891202_10_dialog_content = "With this, our grudges are now settled.",
  ui_story_5089_50891202_11_dialog_content = "Agreed.",
  ui_story_5089_50891202_12_dialog_content = "Now go.",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>Jiu sheathes her sword, bows slightly to Dantang in the distance, then turns and leaves.</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>Not once does she look back.</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>Royal Palace of Ji Kingdom</color>",
  ui_story_5089_50891300_2_dialog_content = "Father! Father! I hear my betrothed has sent me gifts!",
  ui_story_5089_50891300_3_dialog_content = "Indeed, my child.",
  ui_story_5089_50891300_4_dialog_content = "Let me see! Let me see!",
  ui_story_5089_50891300_5_dialog_content = "Here, a fortune in gold.",
  ui_story_5089_50891300_6_dialog_content = "Eh? But aren't these the gifts I offered him before he left?",
  ui_story_5089_50891300_7_dialog_content = "Is he not fond of gold? I should've known my beloved hero wouldn't care for paltry trinkets such as these.",
  ui_story_5089_50891300_8_dialog_content = "I'll have to put more thought into my gifts from now on!",
  ui_story_5089_50891300_9_dialog_content = "That boy...",
  ui_story_5089_50891300_10_dialog_content = "That young man used the crown prince's gift of gold to exchange for the food we previously purchased from Ye Kingdom. His intentions appear to be quite clear.",
  ui_story_5089_50891300_11_dialog_content = "How shall we proceed, Your Highness?",
  ui_story_5089_50891300_12_dialog_content = "PlayerName is a friend of Ji Kingdom, one whose honor I can personally vouch for. I have yet to repay him for saving Haojin, as well.",
  ui_story_5089_50891300_13_dialog_content = "If he wishes to involve himself in these matters, I will respect his decision.",
  ui_story_5089_50891300_14_dialog_content = "However, I will not be so gracious if Ye Kingdom seeks conflict with us again in the future.",
  ui_story_5089_50891300_15_dialog_content = "Yes, my lord.",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>Fwoosh—</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>On the bustling dock, another large ship hoists its sails and departs.</color>",
  ui_story_5089_50891300_18_dialog_content = "So, Jiu never comes back after that?",
  ui_story_5089_50891300_19_dialog_content = "Yes. Given that I willingly granted her freedom, it's only natural that I respect her choice.",
  ui_story_5089_50891300_20_dialog_content = "Even if she never returns, I will always remember how fortunate I was to have such a close friend.",
  ui_story_5089_50891300_21_dialog_content = "But what about you, PlayerName? What will you do next?",
  ui_story_5089_50891300_22_dialog_content = "Huh? We're on a ship heading to Ji Kingdom right now, aren't we?",
  ui_story_5089_50891300_23_dialog_content = "You're the one who said that the Fate Riders are our common enemy. Our next goal is to convince the Ji and Ye Kingdoms to set aside their differences for the time being.",
  ui_story_5089_50891300_24_dialog_content = "I also need to return all this gold to the crown prince. I never got the chance to thank Houfeng... I mean, the King of Ye... For helping me cover the difference.",
  ui_story_5089_50891300_25_dialog_content = "Speaking of, are you sure it's okay to let him continue serving as king?",
  ui_story_5089_50891300_26_dialog_content = "Unfortunately, we have no other choice.",
  ui_story_5089_50891300_27_dialog_content = "My real uncle is mentally unfit to rule, and my elder sister is still too young to assume the responsibilities of the throne. As it stands, Ye Kingdom cannot afford even the slightest disturbance.",
  ui_story_5089_50891300_28_dialog_content = "Though Master Houfeng is somewhat arrogant, he truly has the best interests of Ye Kingdom at heart.",
  ui_story_5089_50891300_29_dialog_content = "What's more, with Ministress Armilla and the Artisan's Guild commanding greater authority than before, he won't be able to act with impunity for the time being.",
  ui_story_5089_50891300_30_dialog_content = "But that wasn't the point of my question. I was referring more to your future plans.",
  ui_story_5089_50891300_31_dialog_content = "Well, now that I've been to Haojin and Jingliang City, I want to see more of Longzhou.",
  ui_story_5089_50891300_32_dialog_content = "But after being away from Astra for so long, maybe I should make a trip back first? I'd rather not make Vice and Carleen worry more than I have to.",
  ui_story_5089_50891300_33_dialog_content = "What do you think, Dantang?",
  ui_story_5089_50891300_34_dialog_content = "Surely you jest?",
  ui_story_5089_50891300_35_dialog_content = "You're neither a bird in a cage nor a beast in a pen. It's not my place to dictate your future.",
  ui_story_5089_50891300_36_dialog_content = "So if I'm not one or the other, then what exactly am I in your eyes, Dantang?",
  ui_story_5089_50891300_37_dialog_content = "If I had to say...",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>Under the morning sun, she chuckles as she looks up, her serious eyes brimming with a radiant light.</color>",
  ui_story_5089_50891300_39_dialog_content = "You are the Peng to my Kun.",
  ui_story_5089_50891300_40_dialog_content = "A great and majestic bird that will eventually soar through the nine heavens.",
  ui_story_5089_50891300_41_dialog_content = "That's a little too much, don't you think?",
  ui_story_5089_50891300_42_dialog_content = "Not at all.",
  ui_story_5089_50891300_43_dialog_content = "Hey, look out there! Someone's chasing after our ship!",
  ui_story_5089_50891300_44_dialog_content = "Have you been in the sun too long? How could someone possibly—Wait, you're right! Dragon Maiden is above; there really is someone running on the water!",
  ui_story_5089_50891300_45_dialog_content = "What are you two shouting about—Whoa!",
  ui_story_5089_50891300_46_dialog_content = "Is that Jiu?!",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>The ship has sailed far from the shore, yet a figure strides upon the water, rushing towards it at an incredible speed.</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>As she approaches the ship, she makes a daring leap and lands gracefully on the deck.</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>Standing before us, fresh as the ocean breeze, is none other than Jiu herself.</color>",
  ui_story_5089_50891300_50_dialog_content = "Your Highness, don't you think it was careless of you to depart for another kingdom without your loyal guard?",
  ui_story_5089_50891300_51_dialog_content = "Have you decided then?",
  ui_story_5089_50891300_52_dialog_content = "If you've chosen to continue following me, let it be known that I won't tolerate the same mistake twice, Jiu.",
  ui_story_5089_50891300_53_dialog_content = "My mind is decided, Your Highness.",
  ui_story_5089_50891300_54_dialog_content = "On my honor, I will not disappoint you.",
  ui_story_5089_50891300_55_dialog_content = "Good. Now let's go.",
  ui_story_5089_50891300_56_dialog_content = "The Fate Riders are still a threat to the entire Zhao Empire. Once our business in Ji Kingdom is concluded, we will be traveling to the other vassal kingdoms to continue our investigation.",
  ui_story_5089_50891300_57_dialog_content = "But with the empire in such peril, wouldn't it be better to send others to the vassal kingdoms in your stead?",
  ui_story_5089_50891300_58_dialog_content = "Journeying across the land in every conceivable direction is an opportunity afforded to very few people.",
  ui_story_5089_50891300_59_dialog_content = "I have always aspired to travel like this. How could I possibly let a small crisis stop me from attaining my lifelong dream?",
  ui_story_5089_50891300_60_dialog_content = "Moreover, birds and fish are free to roam the world.",
  ui_story_5089_50891300_61_dialog_content = "If I don't dare to explore every corner of the world, how can I expect to ever find a companion as extraordinary as them to soar beside me?",
  ui_story_5089_50891300_62_dialog_content = "We still have a long journey ahead of us.",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>In a teahouse somewhere</color>",
  ui_story_5089_50891300_64_dialog_content = "... And so, Princess Zhuohua and the Envoy of Astra departed on their respective journeys.",
  ui_story_5089_50891300_65_dialog_content = "The shifting winds and rolling clouds above them had finally subsided, at least for the moment.",
  ui_story_5089_50891300_66_dialog_content = "As for me, this is the perfect opportunity for me to ask for a few spare coins in exchange for my wonderful tale. After all, my poor little birds have to eat, as well!",
  ui_story_5089_50891300_67_dialog_content = "What's that? You think I'm making the whole thing up? My, what a grave misconception!",
  ui_story_5089_50891300_68_dialog_content = "Every word of what I just said is true, and this ocean is proof of it!",
  ui_story_5089_50891300_69_dialog_content = "Etched upon the ocean waves, a ship full of shining begonias sails onward.",
  ui_story_5089_50891300_70_dialog_content = "On the eve of the Spring Festival, a dance between fish and dragons takes place, and the storm's power calms the sea.",
  ui_story_5089_50891300_71_dialog_content = "A thundering sword becomes a blade of pure frost, and strikes the demons into dust.",
  ui_story_5089_50891300_72_dialog_content = "The caged bird breaks free, stirring the heavens with its wings as it finds joy in the vastness of the world.",
  ui_story_5089_50891300_73_dialog_content = "Thus, the Tale of the Drifting Begonia comes to an end.",
  ui_story_5089_50891300_74_dialog_content = "Naturally, the hero's journey is still far from over. If you would like to hear the rest of it—",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>Clack!</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>With a click of the wooden gavel, the book that had been flipped to the end slowly closes, the candlelight fades away, and the curtain falls.</color>",
  ui_story_5089_50891300_77_dialog_content = "What's next... Well, maybe we stand on opposite ends of the sea, we will meet again so long as fate allows it.",
  ui_story_5089_50891400_1_dialog_content = "Have you made your decision?",
  ui_story_5089_50891400_2_dialog_content = "Moving forward means saying goodbye to everyone you know now.",
  ui_story_5089_50891400_3_dialog_content = "All the connections you've worked so hard to build will fade away.",
  ui_story_5089_50891400_4_dialog_content = "But even so, you would still travel to the ends of the world for her, wouldn't you?",
  ui_story_5089_50891400_5_option_content = "Yes.",
  ui_story_5089_50891400_6_option_content = "Yes, I've decided.",
  ui_story_5089_50891400_7_dialog_content = "...",
  ui_story_5089_50891400_8_dialog_content = "Your travels in Longzhou seem to have made you more decisive.",
  ui_story_5089_50891400_9_dialog_content = "Then, let's say our goodbyes.",
  ui_story_5089_50891400_10_dialog_content = "At the last of the last, with all of my friends...",
  ui_story_5089_50891400_11_dialog_content = "One last trip around Astra, right?",
  ui_story_5089_50891400_12_dialog_content = "Just like in the beginning, we'll set out with style!",
  ui_story_5089_50891400_13_dialog_content = "You came all this way just to say goodbye?",
  ui_story_5089_50891400_14_dialog_content = "Oh, I'm good at this, you know. But you're coming back someday, right?",
  ui_story_5089_50891400_15_option_content = "I'm not sure either.",
  ui_story_5089_50891400_16_option_content = "Hmm...",
  ui_story_5089_50891400_17_dialog_content = "Sigh, come here.",
  ui_story_5089_50891400_18_dialog_content = "Here. When guys embrace like this, they don't have to say anything else.",
  ui_story_5089_50891400_19_dialog_content = "I know you have your reasons, and I support you.",
  ui_story_5089_50891400_20_dialog_content = "And... Thanks. You've always been a big help to us, and to me.",
  ui_story_5089_50891400_21_dialog_content = "If you ever come back, remember to give us a holler.",
  ui_story_5089_50891400_22_dialog_content = "And if things don't pan out, don't forget that you'll always have a place here.",
  ui_story_5089_50891400_23_dialog_content = "Thanks, I'll definitely remember.",
  ui_story_5089_50891400_24_dialog_content = "Argh, here I go, getting all teary-eyed... This is your fault.",
  ui_story_5089_50891400_25_dialog_content = "Now go say your farewells to Eve and the others.",
  ui_story_5089_50891400_26_dialog_content = "Goodbye, Sinsa.",
  ui_story_5089_50891400_27_dialog_content = "... Goodbye, PlayerName.",
  ui_story_5089_50891400_28_dialog_content = "What? Just like that... and you're leaving and never coming back?!",
  ui_story_5089_50891400_29_dialog_content = "Ah, th-that's not necessarily the case, but I'm not entirely sure when I'll be back...",
  ui_story_5089_50891400_30_dialog_content = "O-Oh, Eve, don't cry. If Sinsa sees this, I'll be in huge trouble!",
  ui_story_5089_50891400_31_dialog_content = "But...",
  ui_story_5089_50891400_32_dialog_content = "I know we'll meet again someday!",
  ui_story_5089_50891400_33_dialog_content = "And when I finally make my way back here...",
  ui_story_5089_50891400_34_dialog_content = "I'll have tons of new stories to share with you, ones that you could never see here in Astra!",
  ui_story_5089_50891400_35_dialog_content = "You promise?",
  ui_story_5089_50891400_36_dialog_content = "Of course!",
  ui_story_5089_50891400_37_dialog_content = "Pinky promise?",
  ui_story_5089_50891400_38_dialog_content = "Absolutely!",
  ui_story_5089_50891400_39_dialog_content = "Good! Come on, I'll take you to the others so you can say your goodbyes to them.",
  ui_story_5089_50891400_40_dialog_content = "We miss you all the time, you know?",
  ui_story_5089_50891400_41_dialog_content = "Oh, and remember that lady you introduced to us before? You still haven't seen her around here!",
  ui_story_5089_50891400_42_dialog_content = "And there's also Miss Attar! She...",
  ui_story_5089_50891400_43_dialog_content = "Eve?",
  ui_story_5089_50891400_44_dialog_content = "I'm sorry. I know I promised I wouldn't cry anymore.",
  ui_story_5089_50891400_45_dialog_content = "But... I suddenly remembered everything we've been through together...",
  ui_story_5089_50891400_46_dialog_content = "I know what you mean. It's been a while, huh?",
  ui_story_5089_50891400_47_dialog_content = "Before we knew it, we made lots of new friends. They've all grown in so many ways too.",
  ui_story_5089_50891400_48_dialog_content = "This place will always be near and dear to my heart.",
  ui_story_5089_50891400_49_dialog_content = "Just like the hot pot in Longzhou.",
  ui_story_5089_50891400_50_dialog_content = "That's why I think you'll be fine, Eve.",
  ui_story_5089_50891400_51_dialog_content = "Because you'll still have everyone by your side.",
  ui_story_5089_50891400_52_dialog_content = "A-Alright.",
  ui_story_5089_50891400_53_dialog_content = "We'll always be here waiting for you with smiles on our faces, PlayerName.",
  ui_story_5089_50891400_54_dialog_content = "Come on, let's go say goodbye.",
  ui_story_5089_50891400_55_dialog_content = "I've been told about the matter.",
  ui_story_5089_50891400_56_dialog_content = "Since it involves Vice, I won't stop you.",
  ui_story_5089_50891400_57_dialog_content = "I've also approved Vice's request for time off. If you need anything else, don't hesitate to let me know.",
  ui_story_5089_50891400_58_dialog_content = "It's okay, this is more than enough. Thank you and Reinhardt for all of your help!",
  ui_story_5089_50891400_59_dialog_content = "Our journey's going to take us deep into unknown territory.",
  ui_story_5089_50891400_60_dialog_content = "It's not something that can be solved just by finding more people.",
  ui_story_5089_50891400_61_dialog_content = "I understand, but I'd still like to lend a hand if possible.",
  ui_story_5089_50891400_62_dialog_content = "Things will be a bit lonely without you, I'm sure.",
  ui_story_5089_50891400_63_dialog_content = "I know Barton will feel it when sitting around at home.",
  ui_story_5089_50891400_64_dialog_content = "Why not let Gronru take him out to play more? It's not healthy for him to stay at home when there are no battles to fight.",
  ui_story_5089_50891400_65_dialog_content = "Heh, I'm only joking.",
  ui_story_5089_50891400_66_dialog_content = "His old commander is watching him closely now, so he'll have plenty to do.",
  ui_story_5089_50891400_67_dialog_content = "Commander Hiiro telling jokes... I can't believe I lived to see this day.",
  ui_story_5089_50891400_68_dialog_content = "Hmm. Perhaps it's just the kind of change you bring out in other people.",
  ui_story_5089_50891400_69_dialog_content = "You have greatly influenced the Grand Marshal, and I'm no exception.",
  ui_story_5089_50891400_70_dialog_content = "...",
  ui_story_5089_50891400_71_dialog_content = "Take care of yourself.",
  ui_story_5089_50891400_72_dialog_content = "I will!",
  ui_story_5089_50891400_73_dialog_content = "Hey! Over here!",
  ui_story_5089_50891400_74_dialog_content = "Here, here, PlayerName!",
  ui_story_5089_50891400_75_dialog_content = "I'm here to say bye-bye.",
  ui_story_5089_50891400_76_dialog_content = "Has the Colossus always taken off this quickly?",
  ui_story_5089_50891400_77_dialog_content = "Hey—PlayerName!",
  ui_story_5089_50891400_78_dialog_content = "Take good care of yourself on your journey, you hear? Remember to eat three square meals a day, and don't be late for a single one!",
  ui_story_5089_50891400_79_dialog_content = "And you'd better bring Vice back home safe and sound too!",
  ui_story_5089_50891400_80_dialog_content = "I will—Just you wait!",
  ui_story_5089_50891400_81_dialog_content = "I promise I'll bring her back safely!",
  ui_story_5089_50891400_82_dialog_content = "Ah, brat... Thinks he can just fly off with one of Illumina's best soldiers whenever he wants...",
  ui_story_5089_50891400_83_dialog_content = "Aren't you going to say goodbye?",
  ui_story_5089_50891400_84_dialog_content = "Nah.",
  ui_story_5089_50891400_85_dialog_content = "He's a free bird. I don't want to add unnecessary burdens on him.",
  ui_story_5089_50891400_86_dialog_content = "What happens next is for PlayerName to decide. It's his story, after all.",
  ui_story_5089_50891400_87_dialog_content = "As his friend, all I can do is offer him my best wishes as he takes flight.",
  ui_story_5089_50891400_88_dialog_content = "... Wlet's go. We have plenty of decisions to make for ourselves, don't we?",
  ui_story_5089_50891400_89_dialog_content = "Farewell...?",
  ui_story_5089_50891400_90_dialog_content = "...",
  ui_story_5089_50891400_91_dialog_content = "But no one's here right now... Lady Victoria, Paloma, Pasolo... None of them.",
  ui_story_5089_50891400_92_dialog_content = "Yeah, but you're still here, right?",
  ui_story_5089_50891400_93_dialog_content = "At the very least, I can see you one last time before I go.",
  ui_story_5089_50891400_94_dialog_content = "And that's all I could ask for.",
  ui_story_5089_50891400_95_dialog_content = "It would feel like something was missing if we didn't get to say goodbye to each other.",
  ui_story_5089_50891400_96_dialog_content = "?!",
  ui_story_5089_50891400_97_dialog_content = "Though it's a pity that I can't see Paloma...",
  ui_story_5089_50891400_98_dialog_content = "Maybe Victoria will help me deliver the message, she always knows everything, right?",
  ui_story_5089_50891400_99_dialog_content = "And if that doesn't work—",
  ui_story_5089_50891400_100_dialog_content = "Hey—! Master Hermit—!",
  ui_story_5089_50891400_101_dialog_content = "Please make sure Victoria and the others get my message—!",
  ui_story_5089_50891400_102_dialog_content = "... Who are you talking to?",
  ui_story_5089_50891400_103_dialog_content = "Heheh... Someone who understands.",
  ui_story_5089_50891400_104_dialog_content = "...",
  ui_story_5089_50891400_105_dialog_content = "I...",
  ui_story_5089_50891400_106_dialog_content = "I hope you'll return safely someday.",
  ui_story_5089_50891400_107_dialog_content = "Of course I will!",
  ui_story_5089_50891400_108_dialog_content = "Goodbye!",
  ui_story_5089_50891400_109_dialog_content = "Goodbye.",
  ui_story_5089_50891400_110_dialog_content = "... There. That should be the last of it.",
  ui_story_5089_50891400_111_dialog_content = "That's all the supplies for your journey from Umbraton Guild and... the Lovegators.",
  ui_story_5089_50891400_112_dialog_content = "I didn't expect to get so much free stuff just by coming to Umbraton...",
  ui_story_5089_50891400_113_dialog_content = "I'm a little embarrassed to accept it.",
  ui_story_5089_50891400_114_dialog_content = "You've always been a friend of Umbraton, and to us as well.",
  ui_story_5089_50891400_115_dialog_content = "Consider it a token of that friendship.",
  ui_story_5089_50891400_116_dialog_content = "Wow! Y-You scared me!",
  ui_story_5089_50891400_117_dialog_content = "Hahaha! Don't forget, the place where you're going lies far beyond the watchful gaze of Umbraton's shadows.",
  ui_story_5089_50891400_118_dialog_content = "Be cautious in all that you do.",
  ui_story_5089_50891400_119_dialog_content = "I will.",
  ui_story_5089_50891400_120_dialog_content = "... I leave the rest to you, Bethel.",
  ui_story_5089_50891400_121_dialog_content = "...",
  ui_story_5089_50891400_122_dialog_content = "Luke, Smokey, Genevieve, and Naroxel are all waiting for you in the back.",
  ui_story_5089_50891400_123_dialog_content = "As one of Astra's most famous celebrities, they all want to say goodbye in person.",
  ui_story_5089_50891400_124_dialog_content = "I see...",
  ui_story_5089_50891400_125_dialog_content = "Guess that means I should offer them a proper farewell.",
  ui_story_5089_50891400_126_dialog_content = "And you as well, Bethel.",
  ui_story_5089_50891400_127_dialog_content = "...!",
  ui_story_5089_50891400_128_dialog_content = "... Will you really be gone for that long?",
  ui_story_5089_50891400_129_dialog_content = "I can't say for sure. In fact, I don't even know if I'll be able to come back afterward.",
  ui_story_5089_50891400_130_dialog_content = "But I do know that I'll never forget any of the great people I met here.",
  ui_story_5089_50891400_131_dialog_content = "So, if there's even a chance for me to return, I'll do everything I can to make it happen.",
  ui_story_5089_50891400_132_dialog_content = "PlayerName...",
  ui_story_5089_50891400_133_dialog_content = "Please take care of yourself.",
  ui_story_5089_50891400_134_dialog_content = "And if I come across any interesting novels along the way, I'll be sure to bring them back for you too.",
  ui_story_5089_50891400_135_dialog_content = "When that day comes, we can spend some time reading in the cafe with everyone!",
  ui_story_5089_50891400_136_dialog_content = "But for now...",
  ui_story_5089_50891400_137_dialog_content = "Goodbye, Bethel.",
  ui_story_5089_50891400_138_dialog_content = "Found him. He's over there.",
  ui_story_5089_50891400_139_dialog_content = "PlayerName!",
  ui_story_5089_50891400_140_dialog_content = "Goodbye!",
  ui_story_5089_50891400_141_dialog_content = "Ah...",
  ui_story_5089_50891400_142_dialog_content = "Goodbye—",
  ui_story_5089_50891400_143_dialog_content = "I hope you always have music and hope to guide your way....",
  ui_story_5089_50891400_144_dialog_content = "... Goodbye.",
  ui_story_5089_50891400_145_dialog_content = "Huh? You want to come along too?",
  ui_story_5089_50891400_146_dialog_content = "I-It's not like I want to go with you, per se...",
  ui_story_5089_50891400_147_dialog_content = "But exploring an unknown land of fantasy sounds like an interesting time.",
  ui_story_5089_50891400_148_dialog_content = "Even Antony is thrilled by the prospect, so isn't it normal for me to be a little interested?",
  ui_story_5089_50891400_149_dialog_content = "You should say what's on your mind, or you might regret it later.",
  ui_story_5089_50891400_150_dialog_content = "...",
  ui_story_5089_50891400_151_dialog_content = "As the Phospherus of Astra, allowing you to embark on such a dangerous journey is concerning, to say the least.",
  ui_story_5089_50891400_152_dialog_content = "Oh? Then how about this?",
  ui_story_5089_50891400_153_dialog_content = "I'll go find four more fighters, and all of us will be at your command!",
  ui_story_5089_50891400_154_dialog_content = "We'll have every element covered, and nothing will stand in our way...",
  ui_story_5089_50891400_155_dialog_content = "Even so, I have seen your future.",
  ui_story_5089_50891400_156_dialog_content = "And in that distant place, you still possess an infinite radiance.",
  ui_story_5089_50891400_157_dialog_content = "Perhaps that is where your battle truly lies.",
  ui_story_5089_50891400_158_dialog_content = "A place full of both fantasy and reality, where you will fight for the betterment of all.",
  ui_story_5089_50891400_159_dialog_content = "That is your own path.",
  ui_story_5089_50891400_160_dialog_content = "And though our hearts are filled with worry for you, all we can do is offer you our blessings.",
  ui_story_5089_50891400_161_dialog_content = "Thank you. Your well-wishes put me at ease more than you know.",
  ui_story_5089_50891400_162_dialog_content = "Huh? So there won't be any more chances for us to level up together? I was really hoping we could go on more adventures and take down a few more Wraiths.",
  ui_story_5089_50891400_163_dialog_content = "Honestly, it's so boring around here.",
  ui_story_5089_50891400_164_dialog_content = "You're enjoying your time here, huh, Freya?",
  ui_story_5089_50891400_165_dialog_content = "I guess that's one way to put it...",
  ui_story_5089_50891400_166_dialog_content = "I visited my old hometown, made sure that the \"treasure\" was still safe, and bought myself some new clothes...",
  ui_story_5089_50891400_167_dialog_content = "It's like I've been tapped on the shoulder by fate itself.",
  ui_story_5089_50891400_168_dialog_content = "But that's not nearly enough to satisfy me, you know!",
  ui_story_5089_50891400_169_dialog_content = "And you just had to go and show up with some new and exciting adventure, only to tell us we can't go with you!",
  ui_story_5089_50891400_170_dialog_content = "My fists are itching for a fight so badly it hurts...",
  ui_story_5089_50891400_171_dialog_content = "So how about we throw a couple of punches before you go, Navigator?",
  ui_story_5089_50891400_172_dialog_content = "After all, my dream is—",
  ui_story_5089_50891400_173_dialog_content = "Goodbye, Freya.",
  ui_story_5089_50891400_174_dialog_content = "...",
  ui_story_5089_50891400_175_dialog_content = "Seeing you smiling so happily and genuinely like this...",
  ui_story_5089_50891400_176_dialog_content = "It really puts my heart at ease too.",
  ui_story_5089_50891400_177_dialog_content = "... Make sure to bid them a proper farewell, okay?",
  ui_story_5089_50891400_178_dialog_content = "I will.",
  ui_story_5089_50891400_179_dialog_content = "Goodbye, Queen Bethlehem.",
  ui_story_5089_50891400_180_dialog_content = "Farewell.",
  ui_story_5089_50891400_181_dialog_content = "The ones you wish to see are outside of the palace.",
  ui_story_5089_50891400_182_dialog_content = "Go meet them, PlayerName.",
  ui_story_5089_50891400_183_dialog_content = "Goodbye, Zarya.",
  ui_story_5089_50891400_184_dialog_content = "I still want to go.",
  ui_story_5089_50891400_185_dialog_content = "Huh?",
  ui_story_5089_50891400_186_dialog_content = "N-Nothing.",
  ui_story_5089_50891400_187_dialog_content = "Goodbye...",
  ui_story_5089_50891400_188_dialog_content = "Oh my. Here, let me share some of my elderly wisdom with you.",
  ui_story_5089_50891400_189_dialog_content = "Hey!",
  ui_story_5089_50891400_190_dialog_content = "This is a rare opportunity, you know? You can only pull the young girl card around the Queen and the Mountain God.",
  ui_story_5089_50891400_191_dialog_content = "Hey!!!",
  ui_story_5089_50891400_192_dialog_content = "... So this is the final stop.",
  ui_story_5089_50891400_193_dialog_content = "PlayerName... You'd better come back.",
  ui_story_5089_50891400_194_dialog_content = "I'll do my best, Leyn. Help me pass on my farewells to the others, would you?",
  ui_story_5089_50891400_195_dialog_content = "Well, looks like it's time to let the main characters take the stage.",
  ui_story_5089_50891400_196_dialog_content = "Let's go, everyone.",
  ui_story_5089_50891400_197_dialog_content = "...",
  ui_story_5089_50891400_198_dialog_content = "...",
  ui_story_5089_50891400_199_dialog_content = "What's the matter? Didn't you come to say goodbye?",
  ui_story_5089_50891400_200_dialog_content = "I did, but for some reason, I can't seem to find the right words to say...",
  ui_story_5089_50891400_201_dialog_content = "Then let me do the talking!",
  ui_story_5089_50891400_202_dialog_content = "Huh? Maya?",
  ui_story_5089_50891400_203_dialog_content = "Wait a minute... Achilles?! Y-You're not Maya!",
  ui_story_5089_50891400_204_dialog_content = "She's talking from behind me—",
  ui_story_5089_50891400_205_dialog_content = "I came as soon as I heard you were leaving, PlayerName!",
  ui_story_5089_50891400_206_dialog_content = "But then I got lost... Thankfully, this big guy was kind enough to bring me here!",
  ui_story_5089_50891400_207_dialog_content = "That explains why I couldn't find you earlier...",
  ui_story_5089_50891400_208_dialog_content = "If Jeno and Elvis knew you were running around like this, they'd be worried sick.",
  ui_story_5089_50891400_209_dialog_content = "Ahem.",
  ui_story_5089_50891400_210_dialog_content = "I-I mean Elvis would be sad.",
  ui_story_5089_50891400_211_dialog_content = "That's Laird Elvis to you, mister!",
  ui_story_5089_50891400_212_dialog_content = "Cough, cough.",
  ui_story_5089_50891400_213_dialog_content = "So you've made your decision then?",
  ui_story_5089_50891400_214_dialog_content = "Because once you leave, we won't be able to help you.",
  ui_story_5089_50891400_215_dialog_content = "I know, but I can't always rely on everyone.",
  ui_story_5089_50891400_216_dialog_content = "...",
  ui_story_5089_50891400_217_dialog_content = "You've all been given a chance at a new future...",
  ui_story_5089_50891400_218_dialog_content = "I hope you can spend the rest of your days exactly the way you want to spend them.",
  ui_story_5089_50891400_219_dialog_content = "I see... And what if some of us want to spend those days at your side?",
  ui_story_5089_50891400_220_dialog_content = "Uh, what?",
  ui_story_5089_50891400_221_dialog_content = "If you entrust us with the right to choose, then you must value every single one of our opinions.",
  ui_story_5089_50891400_222_dialog_content = "Some of us may be unwilling to leave you.",
  ui_story_5089_50891400_223_dialog_content = "Some of us may not want to let go of the adventures we've shared with you.",
  ui_story_5089_50891400_224_dialog_content = "Those of us who feel that way may want to continue fighting at your side.",
  ui_story_5089_50891400_225_dialog_content = "And there may just be enough of us to fill every room aboard your Colossus.",
  ui_story_5089_50891400_226_dialog_content = "Y-You really think so?",
  ui_story_5089_50891400_227_dialog_content = "Then I want to go too!",
  ui_story_5089_50891400_228_dialog_content = "And if there isn't enough room for me, I can just have my ancestor take me!",
  ui_story_5089_50891400_229_dialog_content = "But what about the aquarium?",
  ui_story_5089_50891400_230_dialog_content = "... Oh, no!!!",
  ui_story_5089_50891400_231_dialog_content = "I was so worried about PlayerName and his trip that I totally forgot!",
  ui_story_5089_50891400_232_dialog_content = "Oh...",
  ui_story_5089_50891400_233_dialog_content = "You really don't have to force yourself, Maya.",
  ui_story_5089_50891400_234_dialog_content = "This isn't something that should be decided in a short amount of time.",
  ui_story_5089_50891400_235_dialog_content = "You don't have to rush your decision. It won't change the way I think of you if you decide not to go.",
  ui_story_5089_50891400_236_dialog_content = "Really?",
  ui_story_5089_50891400_237_dialog_content = "Really.",
  ui_story_5089_50891400_238_dialog_content = "Then... I'll be waiting for you back at the aquarium.",
  ui_story_5089_50891400_239_dialog_content = "Alright, it's a deal.",
  ui_story_5089_50891400_240_dialog_content = "Great! I'll go back and tell Jeno and Elvis right away!",
  ui_story_5089_50891400_241_dialog_content = "AHEM—!",
  ui_story_5089_50891400_242_dialog_content = "Looks like you're starting to understand now.",
  ui_story_5089_50891400_243_dialog_content = "Saying \"goodbye\" means that we have to go our separate ways for a time.",
  ui_story_5089_50891400_244_dialog_content = "But that time doesn't necessarily have to last forever.",
  ui_story_5089_50891400_245_dialog_content = "And since you hope to return someday, there's no need to let your \"goodbyes\" weigh so heavily on your heart.",
  ui_story_5089_50891400_246_dialog_content = "You shouldn't have to force yourself to say those words, either.",
  ui_story_5089_50891400_247_dialog_content = "After all, your story is still far from over.",
  ui_story_5089_50891400_248_dialog_content = "So make your choices, and guide your story to the perfect ending in your heart.",
  ui_story_5089_50891400_249_dialog_content = "Achilles...",
  ui_story_5089_50891400_250_dialog_content = "Goodbye, PlayerName.",
  ui_story_5089_50891400_251_dialog_content = "May the Last Caelestite fly higher into the sky than ever before.",
  ui_story_5089_50891400_252_dialog_content = "...",
  ui_story_5089_50891400_253_dialog_content = "...",
  ui_story_5089_50891400_254_dialog_content = "Carleen, I...",
  ui_story_5089_50891400_255_dialog_content = "Soroz is here.",
  ui_story_5089_50891400_256_dialog_content = "Which means it's time to depart, right?",
  ui_story_5089_50891400_257_dialog_content = "Yeah.",
  ui_story_5089_50891400_258_dialog_content = "... It's just like when we first met.",
  ui_story_5089_50891400_259_dialog_content = "You, Soroz, Vice, and I, all in Lumopolis...",
  ui_story_5089_50891400_260_dialog_content = "...",
  ui_story_5089_50891400_261_dialog_content = "Goodb—",
  ui_story_5089_50891400_262_dialog_content = "Come with us, Carleen.",
  ui_story_5089_50891400_263_dialog_content = "Just like how it all began?",
  ui_story_5089_50891400_264_dialog_content = "Exactly like that.",
  ui_story_5089_50891400_265_dialog_content = "...",
  ui_story_5089_50891400_266_dialog_content = "Then let's go, PlayerName!",
  ui_story_5089_50891400_267_dialog_content = "What took you so long, PlayerName?",
  ui_story_5089_50891400_268_dialog_content = "I'm starting to get dizzy from picking up all your slack!",
  ui_story_5089_50891400_269_dialog_content = "Vice, I...",
  ui_story_5089_50891400_270_dialog_content = "I knew you would come, Carleen.",
  ui_story_5089_50891400_271_dialog_content = "I just didn't expect it to take this long.",
  ui_story_5089_50891400_272_dialog_content = "Well, it's not nice to drag people away without a proper explanation...",
  ui_story_5089_50891400_273_dialog_content = "You mean like what you did to me?",
  ui_story_5089_50891400_274_dialog_content = "I swear, you act like we haven't already known each other.",
  ui_story_5089_50891400_275_dialog_content = "You're gonna hurt people's feelings if you keep acting like that.",
  ui_story_5089_50891400_276_dialog_content = "Sigh...",
  ui_story_5089_50891400_277_dialog_content = "Is there anything else you need help with?",
  ui_story_5089_50891400_278_dialog_content = "Nope, we're just about ready. All that's left is to set our destination.",
  ui_story_5089_50891400_279_dialog_content = "Our destination... You mean the \"land of fantasy\" we previously discovered?",
  ui_story_5089_50891400_280_dialog_content = "That's right. We're heading straight for that rift, the one where Vice's memory fragments flew across. It's been calling out to me.",
  ui_story_5089_50891400_281_dialog_content = "And after having Migard, Victoria, the Saintess, and a few other parties look into it, we've all but confirmed that there's a completely different world on the other side.",
  ui_story_5089_50891400_282_dialog_content = "I've been told that this other world is practically overflowing with N-matter.",
  ui_story_5089_50891400_283_dialog_content = "That's right, which means it must be an extremely realistic world. The X-matter that composes fantasy worlds is practically undetectable.",
  ui_story_5089_50891400_284_dialog_content = "It should be a pretty safe place, but it's still surrounded in mystery.",
  ui_story_5089_50891400_285_dialog_content = "That's why I don't want to allow other people to come with me.",
  ui_story_5089_50891400_286_dialog_content = "But... My friends... They're not just \"other people.\"",
  ui_story_5089_50891400_287_dialog_content = "Hey, that reminds me. Why do we keep calling it a \"land of fantasy\"?",
  ui_story_5089_50891400_288_dialog_content = "Well... At the end of the day, this is how Bethlehem described it—",
  ui_story_5089_50891400_289_dialog_content = "When compared to our world, it's possible that the other world is the real world...",
  ui_story_5089_50891400_290_dialog_content = "And yet, it shares a fascinating and inseparable bond with Astra.",
  ui_story_5089_50891400_291_dialog_content = "This is ultimately the reason why Vice's memories flowed into it. The truth which you seek also lies in that world, Caelestite.",
  ui_story_5089_50891400_292_dialog_content = "Perhaps, in that reality, a corresponding fantasy exists.",
  ui_story_5089_50891400_293_dialog_content = "This implies that even in the \"real\" world, people can still conjure up beautiful \"fantasies\" out of thin air.",
  ui_story_5089_50891400_294_dialog_content = "Their yearning for the imaginary ultimately led to our two worlds' connection.",
  ui_story_5089_50891400_295_dialog_content = "... But we're not going there to end those fantasies.",
  ui_story_5089_50891400_296_dialog_content = "We're not just going to accept their world as the one and only reality, either.",
  ui_story_5089_50891400_297_dialog_content = "In the end, we're just embarking on a new journey into the unknown, chasing after the beautiful dreams that we also yearn for.",
  ui_story_5089_50891400_298_dialog_content = "Even if we can only accomplish that in the real world, I truly believe we'll make it happen someday.",
  ui_story_5089_50891400_299_dialog_content = "And when that time comes, we'll all return to Astra!",
  ui_story_5089_50891400_300_dialog_content = "To be honest, I don't really understand this way of thinking either.",
  ui_story_5089_50891400_301_dialog_content = "I'm just happy to join everyone on yet another adventure.",
  ui_story_5089_50891400_302_dialog_content = "Me too.",
  ui_story_5089_50891400_303_dialog_content = "I may not say much, but please remember to include me as well.",
  ui_story_5089_50891400_304_dialog_content = "How could we forget?",
  ui_story_5089_50891400_305_dialog_content = "Especially after how hard it was to find you again!",
  ui_story_5089_50891400_306_dialog_content = "Then please set the coordinates for our new destination.",
  ui_story_5089_50891400_307_dialog_content = "Vice.",
  ui_story_5089_50891400_308_dialog_content = "Yep! Want to join us this time, Carleen?",
  ui_story_5089_50891400_309_dialog_content = "But I can't play...",
  ui_story_5089_50891400_310_dialog_content = "Oh, that doesn't matter. There's only so much of this final fantasy left, after all.",
  ui_story_5089_50891400_311_dialog_content = "She's right! Vice and I can guide you through it as long as you put your heart into it.",
  ui_story_5089_50891400_312_dialog_content = "... Understood.",
  ui_story_5089_50891400_313_dialog_content = "Alright...",
  ui_story_5089_50891400_314_dialog_content = "Let's go!",
  ui_story_5089_50891400_315_dialog_content = "Goodbye, Astra.",
  ui_story_5089_50891400_316_dialog_content = "Goodbye to everyone who journeyed through this beautiful dream with me.",
  ui_story_5089_50891400_317_dialog_content = "Until next time!",
  ui_story_5089_50891400_318_dialog_content = "THE END",
  ui_story_5089_50891400_319_dialog_content = "Thank you for playing."
}
return config
